import hashlib
import os
import re
import subprocess
import time
from pathlib import Path
from typing import Any, Iterable

from .ml import RuntimeMCPClient, sanitize


_TEXT_EXTENSIONS = {
    ".py", ".pyi", ".js", ".mjs", ".cjs", ".ts", ".tsx", ".jsx", ".php",
    ".go", ".rs", ".c", ".h", ".cc", ".cpp", ".cxx", ".hpp", ".java", ".kt",
    ".kts", ".scala", ".sh", ".bash", ".zsh", ".fish", ".ps1", ".sql", ".yaml",
    ".yml", ".json", ".json5", ".toml", ".ini", ".cfg", ".conf", ".md", ".rst",
    ".txt", ".html", ".htm", ".css", ".scss", ".sass", ".less", ".vue", ".svelte",
    ".xml", ".xsd", ".proto", ".graphql", ".gql", ".lean", ".tla", ".nix", ".lua",
    ".rb", ".pl", ".pm", ".r", ".jl", ".ex", ".exs", ".erl", ".hrl", ".clj",
    ".cljs", ".cljc", ".edn", ".fs", ".fsx", ".vb", ".cs", ".sol", ".asm",
}
_SPECIAL_NAMES = {
    "Dockerfile", "Containerfile", "Makefile", "CMakeLists.txt", "Justfile", "Procfile",
    "Gemfile", "Rakefile", "Vagrantfile", "Jenkinsfile", "Brewfile", "requirements.txt",
    "package.json", "composer.json", "Cargo.toml", "go.mod", "go.sum", "pyproject.toml",
}
_SECRET_PATH = re.compile(
    r"(^|/)(\.env(?:\.|$)|credentials?(?:\.|/|$)|secrets?(?:\.|/|$)|private[_-]?key|"
    r"id_rsa|id_ed25519|\.aws|\.ssh)(/|$)|\.(pem|key|p12|pfx|jks|keystore)$",
    re.I,
)
_SKIP_COMPONENTS = {
    ".git", "node_modules", "vendor", ".venv", "venv", "__pycache__", ".pytest_cache",
    ".mypy_cache", ".ruff_cache", "dist", ".next", ".nuxt", "target", "coverage",
}
_ASSIGNMENT_SECRET = re.compile(
    r"(?im)^(\s*(?:export\s+)?[A-Za-z_][A-Za-z0-9_]*(?:password|passwd|secret|token|api[_-]?key|"
    r"private[_-]?key|credential|database[_-]?url|dsn)[A-Za-z0-9_]*\s*[:=]\s*)([^\n#]+)"
)
_BEARER = re.compile(r"(?i)Bearer\s+[A-Za-z0-9._~+/=-]+")
_BASIC = re.compile(r"(?i)Basic\s+[A-Za-z0-9+/=]+")
_PEM = re.compile(r"-----BEGIN [^-]+-----.*?-----END [^-]+-----", re.S)
_TOKEN = re.compile(r"(?<![A-Za-z0-9])(?:sk-[A-Za-z0-9_-]{20,}|gh[pousr]_[A-Za-z0-9]{20,}|[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,})(?![A-Za-z0-9])")


def _sha256(data: bytes | str) -> str:
    raw = data.encode("utf-8") if isinstance(data, str) else data
    return "sha256:" + hashlib.sha256(raw).hexdigest()


def _run(argv: list[str], cwd: Path, timeout: int = 60) -> subprocess.CompletedProcess[str]:
    return subprocess.run(argv, cwd=cwd, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=timeout, check=False)


def _repository_id(path: Path) -> str:
    name = re.sub(r"[^A-Za-z0-9_.-]+", "-", path.name).strip("-") or "repository"
    return f"{name}-{hashlib.sha256(str(path).encode()).hexdigest()[:10]}"


def _language(path: Path) -> str:
    if path.name in {"Dockerfile", "Containerfile"}: return "dockerfile"
    if path.name == "Makefile": return "make"
    return path.suffix.lower().lstrip(".") or "text"


def _safe_text(path: Path, max_file_bytes: int) -> tuple[str | None, dict[str, Any]]:
    relative = path.as_posix()
    if _SECRET_PATH.search(relative):
        return None, {"skip": "secret_path"}
    if any(part in _SKIP_COMPONENTS for part in path.parts):
        return None, {"skip": "generated_or_dependency"}
    if path.name not in _SPECIAL_NAMES and path.suffix.lower() not in _TEXT_EXTENSIONS:
        return None, {"skip": "unsupported_extension"}
    try:
        size = path.stat().st_size
    except OSError as exc:
        return None, {"skip": f"stat:{exc}"}
    if size > max_file_bytes:
        return None, {"skip": "too_large", "size": size}
    try:
        raw = path.read_bytes()
    except OSError as exc:
        return None, {"skip": f"read:{exc}"}
    if b"\x00" in raw:
        return None, {"skip": "binary"}
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        text = raw.decode("utf-8", errors="replace")
    source_digest = _sha256(raw)
    redactions = 0
    text, n = _PEM.subn("[REDACTED PEM BLOCK]", text); redactions += n
    text, n = _BEARER.subn("Bearer REDACTED", text); redactions += n
    text, n = _BASIC.subn("Basic REDACTED", text); redactions += n
    text, n = _ASSIGNMENT_SECRET.subn(lambda m: m.group(1) + "REDACTED", text); redactions += n
    text, n = _TOKEN.subn("REDACTED_TOKEN", text); redactions += n
    return text, {"size": size, "source_digest": source_digest, "redaction_count": redactions}


def _chunks(text: str, size: int, overlap: int) -> Iterable[tuple[int, str]]:
    if not text:
        yield 0, ""
        return
    step = max(1, size - overlap)
    index = 0
    start = 0
    while start < len(text):
        yield index, text[start:start + size]
        index += 1
        start += step


class SourceIndexer:
    def __init__(self, config: dict[str, Any], client: RuntimeMCPClient | None = None) -> None:
        self.config = config
        self.settings = dict(config.get("source_index") or {})
        self.client = client or RuntimeMCPClient()

    def discover(self) -> list[dict[str, Any]]:
        roots = [Path(p) for p in self.settings.get("discover_roots", ["/var/www/xavi"])]
        max_depth = int(self.settings.get("max_depth", 5))
        repos: dict[str, Path] = {}
        for base in roots:
            if not base.is_dir():
                continue
            base_depth = len(base.parts)
            for current, dirs, files in os.walk(base):
                path = Path(current)
                depth = len(path.parts) - base_depth
                dirs[:] = [d for d in dirs if d not in _SKIP_COMPONENTS and not d.startswith(".cache")]
                if depth > max_depth:
                    dirs[:] = []
                    continue
                if ".git" in dirs or ".git" in files:
                    proc = _run(["git", "rev-parse", "--show-toplevel"], path)
                    if proc.returncode == 0:
                        top = Path(proc.stdout.strip()).resolve()
                        repos[str(top)] = top
                    dirs[:] = [d for d in dirs if d != ".git"]
        return [{"repository_id": _repository_id(path), "path": str(path)} for path in sorted(repos.values())]

    def _files(self, repo: Path) -> list[tuple[Path, bool]]:
        proc = _run(["git", "ls-files", "-z", "--cached", "--others", "--exclude-standard"], repo, timeout=120)
        if proc.returncode != 0:
            raise RuntimeError(proc.stderr.strip() or "git ls-files failed")
        tracked_proc = _run(["git", "ls-files", "-z", "--cached"], repo, timeout=120)
        tracked = set(tracked_proc.stdout.split("\0")) if tracked_proc.returncode == 0 else set()
        rows=[]
        for rel in proc.stdout.split("\0"):
            if not rel:
                continue
            path=(repo/rel).resolve()
            try: path.relative_to(repo.resolve())
            except ValueError: continue
            if path.is_file(): rows.append((path, rel in tracked))
        return rows

    def index_repository(self, repo_path: str | Path) -> dict[str, Any]:
        repo = Path(repo_path).resolve()
        if not (repo / ".git").exists():
            proc = _run(["git", "rev-parse", "--show-toplevel"], repo)
            if proc.returncode != 0 or Path(proc.stdout.strip()).resolve() != repo:
                raise RuntimeError(f"not a Git repository: {repo}")
        repository_id = _repository_id(repo)
        commit_proc = _run(["git", "rev-parse", "HEAD"], repo)
        commit_id = commit_proc.stdout.strip() if commit_proc.returncode == 0 else None
        generation_id = f"src-{repository_id}-{int(time.time()*1000)}"
        begin = self.client.call("runtime.source_begin", {
            "generation_id": generation_id,
            "repository_id": repository_id,
            "root_path": str(repo),
            "commit_id": commit_id,
            "metadata": {"manager": "xavi-stack-manager", "index_mode": "git-cached-plus-unignored"},
        }, timeout=60)
        if not begin.ok:
            raise RuntimeError(f"source_begin failed: {begin.error}")
        max_file_bytes = int(self.settings.get("max_file_bytes", 1048576))
        chunk_chars = int(self.settings.get("chunk_chars", 24000))
        overlap_chars = int(self.settings.get("overlap_chars", 512))
        batch_size = int(self.settings.get("batch_size", 30))
        batch=[]; indexed_files=0; indexed_chunks=0; indexed_bytes=0; skipped=[]
        try:
            for path, tracked in self._files(repo):
                rel=str(path.relative_to(repo))
                text, meta = _safe_text(Path(rel), max_file_bytes) if False else _safe_text(path, max_file_bytes)
                if text is None:
                    if len(skipped) < 200: skipped.append({"path": rel, **meta})
                    continue
                indexed_files += 1
                indexed_bytes += len(text.encode("utf-8"))
                for chunk_index, chunk in _chunks(text, chunk_chars, overlap_chars):
                    batch.append({
                        "repository_id": repository_id,
                        "generation_id": generation_id,
                        "path": rel,
                        "chunk_index": chunk_index,
                        "language": _language(path),
                        "content_digest": _sha256(chunk),
                        "source_digest": meta.get("source_digest"),
                        "content": chunk,
                        "metadata": sanitize({"tracked": tracked, "file_size": meta.get("size"), "redaction_count": meta.get("redaction_count", 0), "commit_id": commit_id}),
                        "training_eligible": True,
                    })
                    indexed_chunks += 1
                    if len(batch) >= batch_size:
                        result=self.client.call("runtime.source_upsert", {"documents": batch}, timeout=120)
                        if not result.ok: raise RuntimeError(f"source_upsert failed: {result.error}")
                        batch=[]
            if batch:
                result=self.client.call("runtime.source_upsert", {"documents": batch}, timeout=120)
                if not result.ok: raise RuntimeError(f"source_upsert failed: {result.error}")
            final=self.client.call("runtime.source_finalize", {"generation_id": generation_id, "status": "completed", "keep_generations": int(self.settings.get("keep_generations", 2))}, timeout=60)
            if not final.ok: raise RuntimeError(f"source_finalize failed: {final.error}")
        except Exception:
            self.client.call("runtime.source_finalize", {"generation_id": generation_id, "status": "failed", "keep_generations": 2}, timeout=30)
            raise
        return {"repository_id": repository_id,"repository_path": str(repo),"generation_id": generation_id,"commit_id": commit_id,"indexed_files": indexed_files,"indexed_chunks": indexed_chunks,"indexed_bytes": indexed_bytes,"skipped_count": len(skipped),"skipped_sample": skipped}

    def index_all(self, repositories: list[str] | None = None) -> dict[str, Any]:
        repos = repositories or [row["path"] for row in self.discover()]
        results=[]; errors=[]
        for repo in repos:
            try: results.append(self.index_repository(repo))
            except Exception as exc: errors.append({"repository_path": repo, "error": f"{type(exc).__name__}: {exc}"})
        return {"indexed": len(results), "failed": len(errors), "results": results, "errors": errors}

    def status(self) -> dict[str, Any]:
        result=self.client.call("runtime.source_status", {}, timeout=30)
        return result.result if result.ok else {"ok": False, "error": result.error}

    def search(self, query: str, repository_id: str | None = None, limit: int = 20) -> dict[str, Any]:
        result=self.client.call("runtime.source_search", {"query": query,"repository_id": repository_id,"limit": limit}, timeout=60)
        return result.result if result.ok else {"ok": False, "error": result.error}
'''
