import tempfile
import unittest

from xavi_stack.code_index import _chunks, _safe_text


class CodeIndexTests(unittest.TestCase):
    def test_chunks_overlap(self):
        rows=list(_chunks("abcdefghij", 6, 2))
        self.assertEqual(rows, [(0,"abcdef"),(1,"efghij"),(2,"ij")])

    def test_secret_redaction(self):
        with tempfile.TemporaryDirectory() as td:
            path=Path(td)/"config.py"
            path.write_text("API_TOKEN = abcdefghijklmnopqrstuvwxyz\nprint('ok')\n")
            text,meta=_safe_text(path,1024)
            self.assertIsNotNone(text)
            self.assertIn("REDACTED", text)
            self.assertGreaterEqual(meta["redaction_count"],1)

    def test_secret_path_skipped(self):
        with tempfile.TemporaryDirectory() as td:
            path=Path(td)/".env"
            path.write_text("TOKEN=x")
            text,meta=_safe_text(path,1024)
            self.assertIsNone(text)
            self.assertEqual(meta["skip"],"secret_path")


if __name__ == "__main__":
    unittest.main()
''')
