<?php

namespace Application\Controller\SinglePage;

use Application\SinglePages\XaviMan\Auth\XaviManAuth;
use Concrete\Core\Http\ResponseFactory;
use Concrete\Core\Page\Controller\PageController;
use Concrete\Core\User\User;
use Symfony\Component\HttpFoundation\JsonResponse;

defined('C5_EXECUTE') or die('Access Denied.');

require_once DIR_APPLICATION . '/single_pages/xavi_man/auth/XaviManAuth.php';

final class XaviMan extends PageController
{
    public function auth_check()
    {
        $rf = $this->app->make(ResponseFactory::class);
        $auth = new XaviManAuth();
        $user = new User();
        $identity = $auth->identity($user);

        if (!$identity) {
            $request = $this->app->make('request');
            $authorization = (string) $request->headers->get('Authorization', '');
            if (stripos($authorization, 'Bearer ') === 0) {
                $claims = $auth->verifyToken(trim(substr($authorization, 7)));
                if ($claims) {
                    $identity = [
                        'siteUserId' => $claims['uid'] ?? $claims['sub'] ?? '',
                        'siteUsername' => (string) ($claims['username'] ?? 'jwt-admin'),
                        'email' => (string) ($claims['email'] ?? ''),
                        'admin' => true,
                    ];
                }
            }
        }

        if (!$identity) {
            return $rf->create('', $user->isRegistered() ? 403 : 401, ['Cache-Control' => 'no-store']);
        }

        $response = $rf->create('', 204);
        $response->headers->set('Cache-Control', 'no-store');
        $response->headers->set('X-Xavi-Man-User-Id', (string) $identity['siteUserId']);
        $response->headers->set('X-Xavi-Man-User-Name', (string) $identity['siteUsername']);
        $response->headers->set('X-Xavi-Man-User-Email', (string) $identity['email']);
        $response->headers->set('X-Xavi-Man-Admin', '1');
        return $response;
    }

    public function session_token()
    {
        $user = new User();
        if (!$user->isRegistered()) {
            return new JsonResponse(['message' => 'ConcreteCMS login required'], 401, ['Cache-Control' => 'no-store']);
        }
        $auth = new XaviManAuth();
        $identity = $auth->identity($user);
        $userInfo = $user->getUserInfoObject();
        if (!$identity || !$userInfo) {
            return new JsonResponse(['message' => 'ConcreteCMS administrator access required'], 403, ['Cache-Control' => 'no-store']);
        }
        $issued = $auth->issueToken($userInfo);
        return new JsonResponse([
            'token' => $issued['token'],
            'expiresAt' => $issued['expiresAt'],
            'username' => $identity['siteUsername'],
            'email' => $identity['email'],
            'audience' => 'xavi-man',
            'scope' => ['xavi-man:read', 'xavi-man:control'],
        ], 200, ['Cache-Control' => 'no-store']);
    }
}
