      <div class="xavi-taskbar-windows" data-tasks aria-label="Open programs" aria-live="polite"></div>
      ${showClock ? '<time data-clock></time>' : ''}
    </nav>`, 'xavi-pane-taskbar');

    const menu = this.querySelector('[data-start-menu]');
