    const setMenu = open => {
      if (!menu || !toggle) return;
      menu.hidden = !open;
      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    };
    toggle?.addEventListener('click', event => {
      event.stopPropagation();
      setMenu(menu?.hidden ?? true);
    });
    this.querySelector('[data-menu-close]')?.addEventListener('click', () => setMenu(false));
    this.querySelectorAll('[data-program]').forEach(button => button.addEventListener('click', () => {
      window.XaviFusionOS?.openBuiltin(button.dataset.program, this.bus);
      setMenu(false);
    }));
    if (!this.outsideMenuListener) {
      this.outsideMenuListener = event => {
        if (!this.contains(event.target)) setMenu(false);
