new=r'''class WindowManager {
  constructor(){this.windows=new Map();this.apps=new Map();this.z=100400;this.registerDefaults();this.active=location.pathname.startsWith('/fusion')||Boolean(document.querySelector('[data-fusion-component]'));if(!this.active)return;document.body.classList.add('xavi-fusion-active');}
  registerDefaults(){
    this.registerApp('patchbay',{title:'Fusion Patchbay',shortTitle:'Patchbay',description:'Connect Fusion blocks and route typed events.',component:'xavi-fusion-patchbay'});
    this.registerApp('calculator',{title:'Calculator',description:'Basic calculations.',component:'xavi-calculator-app'});
    this.registerApp('notepad',{title:'Notepad',description:'Workspace notes stored in this browser.',component:'xavi-notepad-app'});
    this.registerApp('media-player',{title:'Media Player',shortTitle:'Media',description:'Open media associated with the workspace.',component:'xavi-media-app'});
    this.registerApp('json-inspector',{title:'JSON Inspector',shortTitle:'JSON',description:'Inspect structured records and Fusion state.',component:'xavi-json-app'});
  }
  registerApp(id,spec){
    const key=String(id||'').trim(); if(!/^[A-Za-z0-9_.:-]+$/.test(key)) throw new Error('Invalid program ID');
    if(!spec||!spec.title||!spec.component) throw new Error('Programs require a title and custom-element component');
    this.apps.set(key,{id:key,title:String(spec.title),shortTitle:String(spec.shortTitle||spec.title),description:String(spec.description||''),component:String(spec.component),attrs:{...(spec.attrs||{})}});
    window.dispatchEvent(new CustomEvent('xavi:apps-changed',{detail:{apps:this.listApps()}}));
    return key;
  }
  unregisterApp(id){const removed=this.apps.delete(String(id));if(removed)window.dispatchEvent(new CustomEvent('xavi:apps-changed',{detail:{apps:this.listApps()}}));return removed;}
  listApps(){return [...this.apps.values()].map(spec=>({...spec,attrs:{...spec.attrs}}));}
  openBuiltin(id,bus=FusionBus.get('primary')){const spec=this.apps.get(String(id));if(!spec)return false;const attrs={...spec.attrs};if(id==='patchbay')Object.assign(attrs,{workspace:bus.key,node:`patchbay-window-${bus.key}`});this.open({id:`${id}-${bus.key}`,workspace:bus.key,...spec,attrs});return true;}
'''
