write('src/Xavi/FusionOS/AutomationService.php',r'''<?php
namespace Xavi\FusionOS;

use Concrete\Core\Config\Repository\Repository;

class AutomationService
{
    private $db;
    private SidecarClient $sidecar;
    private Repository $config;

    public function __construct(SidecarClient $sidecar, Repository $config)
    {
        $this->db = app('database')->connection();
        $this->sidecar = $sidecar;
        $this->config = $config;
        $this->ensureSchema();
    }

    public function ensureSchema(): void
    {
        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionAutomations (
            automationID INT UNSIGNED NOT NULL AUTO_INCREMENT,
            name VARCHAR(190) NOT NULL,
            actionHandle VARCHAR(80) NOT NULL,
            enabled TINYINT(1) NOT NULL DEFAULT 1,
            intervalMinutes INT UNSIGNED NOT NULL DEFAULT 60,
            payloadJson LONGTEXT NOT NULL,
            nextRunAt DATETIME NULL,
            lastRunAt DATETIME NULL,
            lastStatus VARCHAR(32) NULL,
            lastMessage TEXT NULL,
            createdAt DATETIME NOT NULL,
            updatedAt DATETIME NOT NULL,
            PRIMARY KEY (automationID),
            KEY xaviFusionAutomationDue (enabled, nextRunAt),
            KEY xaviFusionAutomationAction (actionHandle)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionAutomationRuns (
            runID BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
            automationID INT UNSIGNED NULL,
            actionHandle VARCHAR(80) NOT NULL,
            triggerType VARCHAR(24) NOT NULL,
            actor VARCHAR(190) NOT NULL,
            status VARCHAR(32) NOT NULL,
            startedAt DATETIME NOT NULL,
            finishedAt DATETIME NULL,
            durationMs INT UNSIGNED NULL,
            summaryJson LONGTEXT NULL,
            errorText TEXT NULL,
            PRIMARY KEY (runID),
            KEY xaviFusionRunAutomation (automationID, startedAt),
            KEY xaviFusionRunStatus (status, startedAt)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    }

    public function definitions(): array
    {
        return [
            'sidecar_health' => ['label' => t('Sidecar health check'), 'description' => t('Verify the private Fusion sidecar and record its health response.'), 'payload' => []],
            'connector_health' => ['label' => t('Connector health check'), 'description' => t('Query all configured information-fusion connector statuses.'), 'payload' => []],
            'dataset_discover' => ['label' => t('Discover datasets'), 'description' => t('Discover datasets below the governed data root. Optional project_id.'), 'payload' => ['project_id' => '']],
            'dataset_scan' => ['label' => t('Scan dataset assets'), 'description' => t('Refresh the asset catalogue for one dataset.'), 'payload' => ['dataset_id' => '']],
            'dataset_profile' => ['label' => t('Profile dataset'), 'description' => t('Refresh schema and statistical profile information for one dataset.'), 'payload' => ['dataset_id' => '']],
            'dataset_import' => ['label' => t('Import dataset'), 'description' => t('Submit a bounded dataset import using the supplied sidecar payload.'), 'payload' => ['dataset_id' => '', 'mode' => 'copy-to-postgis']],
            'workspace_audit' => ['label' => t('Audit workspace state'), 'description' => t('Read a workspace state and record its current revision/digest.'), 'payload' => ['workspace_key' => 'primary']],
            'witness_verify' => ['label' => t('Verify witness ledger'), 'description' => t('Verify witness envelopes for a workspace or case.'), 'payload' => ['workspace_key' => 'primary', 'case_id' => '']],
            'prune_automation_history' => ['label' => t('Prune automation history'), 'description' => t('Remove old successful automation run records.'), 'payload' => ['days' => 30]],
        ];
    }

    public function stats(): array
    {
        return [
            'total' => (int) $this->db->fetchOne('SELECT COUNT(*) FROM XaviFusionAutomations'),
            'enabled' => (int) $this->db->fetchOne('SELECT COUNT(*) FROM XaviFusionAutomations WHERE enabled = 1'),
            'due' => (int) $this->db->fetchOne('SELECT COUNT(*) FROM XaviFusionAutomations WHERE enabled = 1 AND nextRunAt IS NOT NULL AND nextRunAt <= UTC_TIMESTAMP()'),
            'failed24h' => (int) $this->db->fetchOne("SELECT COUNT(*) FROM XaviFusionAutomationRuns WHERE status = 'failed' AND startedAt >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL 1 DAY)"),
        ];
    }

    public function all(): array
    {
        return $this->db->fetchAllAssociative('SELECT * FROM XaviFusionAutomations ORDER BY enabled DESC, nextRunAt ASC, name ASC');
    }

    public function recentRuns(int $limit = 100): array
    {
        $limit = max(1, min(500, $limit));
        return $this->db->fetchAllAssociative('SELECT r.*, a.name automationName FROM XaviFusionAutomationRuns r LEFT JOIN XaviFusionAutomations a ON a.automationID = r.automationID ORDER BY r.runID DESC LIMIT ' . $limit);
    }

    public function save(array $input): int
    {
        $definitions = $this->definitions();
        $id = max(0, (int) ($input['automation_id'] ?? 0));
        $name = trim((string) ($input['name'] ?? ''));
        $action = trim((string) ($input['action_handle'] ?? ''));
        $interval = max(1, min(10080, (int) ($input['interval_minutes'] ?? 60)));
        $enabled = !empty($input['enabled']) ? 1 : 0;
        $payloadText = trim((string) ($input['payload_json'] ?? '{}'));
        $payload = json_decode($payloadText, true);
        if ($name === '') throw new \InvalidArgumentException(t('Automation name is required.'));
        if (!isset($definitions[$action])) throw new \InvalidArgumentException(t('Unknown automation action.'));
        if (!is_array($payload)) throw new \InvalidArgumentException(t('Automation payload must be valid JSON.'));
        $now = gmdate('Y-m-d H:i:s');
        $next = $enabled ? gmdate('Y-m-d H:i:s', time() + ($interval * 60)) : null;
        $row = [
            'name' => $name,
            'actionHandle' => $action,
            'enabled' => $enabled,
            'intervalMinutes' => $interval,
            'payloadJson' => json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
            'nextRunAt' => $next,
            'updatedAt' => $now,
        ];
        if ($id > 0) {
            $this->db->update('XaviFusionAutomations', $row, ['automationID' => $id]);
            return $id;
        }
        $row['createdAt'] = $now;
        $this->db->insert('XaviFusionAutomations', $row);
        return (int) $this->db->lastInsertId();
    }

    public function toggle(int $id): void
    {
        $row = $this->get($id);
        $enabled = empty($row['enabled']) ? 1 : 0;
        $this->db->update('XaviFusionAutomations', [
            'enabled' => $enabled,
            'nextRunAt' => $enabled ? gmdate('Y-m-d H:i:s', time() + ((int) $row['intervalMinutes'] * 60)) : null,
            'updatedAt' => gmdate('Y-m-d H:i:s'),
        ], ['automationID' => $id]);
    }

    public function delete(int $id): void
    {
        $this->db->delete('XaviFusionAutomations', ['automationID' => $id]);
    }

    public function get(int $id): array
    {
        $row = $this->db->fetchAssociative('SELECT * FROM XaviFusionAutomations WHERE automationID = ?', [$id]);
        if (!$row) throw new \RuntimeException(t('Automation not found.'));
        return $row;
    }

    public function run(int $id, string $trigger = 'manual', string $actor = 'system'): array
    {
        $automation = $this->get($id);
        return $this->execute($automation, $trigger, $actor);
    }

    public function runDue(int $limit = 10): array
    {
        $limit = max(1, min(50, $limit));
        $rows = $this->db->fetchAllAssociative("SELECT * FROM XaviFusionAutomations WHERE enabled = 1 AND nextRunAt IS NOT NULL AND nextRunAt <= UTC_TIMESTAMP() ORDER BY nextRunAt ASC LIMIT " . $limit);
        $results = [];
        foreach ($rows as $row) {
            $claimed = $this->db->executeStatement("UPDATE XaviFusionAutomations SET nextRunAt = DATE_ADD(UTC_TIMESTAMP(), INTERVAL intervalMinutes MINUTE), updatedAt = UTC_TIMESTAMP() WHERE automationID = ? AND enabled = 1 AND nextRunAt <= UTC_TIMESTAMP()", [(int) $row['automationID']]);
            if ($claimed === 1) $results[] = $this->execute($row, 'schedule', 'xavi-automation');
        }
        return $results;
    }

    public function pruneRuns(int $days): int
    {
        $days = max(1, min(3650, $days));
        return $this->db->executeStatement("DELETE FROM XaviFusionAutomationRuns WHERE status = 'success' AND startedAt < DATE_SUB(UTC_TIMESTAMP(), INTERVAL " . $days . " DAY)");
    }

    private function execute(array $automation, string $trigger, string $actor): array
    {
        $id = (int) ($automation['automationID'] ?? 0);
        $action = (string) $automation['actionHandle'];
        $payload = json_decode((string) ($automation['payloadJson'] ?? '{}'), true);
        $payload = is_array($payload) ? $payload : [];
        $started = microtime(true);
        $this->db->insert('XaviFusionAutomationRuns', [
            'automationID' => $id ?: null,
            'actionHandle' => $action,
            'triggerType' => $trigger,
            'actor' => $actor,
            'status' => 'running',
            'startedAt' => gmdate('Y-m-d H:i:s'),
        ]);
        $runID = (int) $this->db->lastInsertId();
        try {
            $result = $this->executeAction($action, $payload);
            $duration = (int) round((microtime(true) - $started) * 1000);
            $summary = json_encode($result, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
            if (strlen($summary) > 250000) $summary = substr($summary, 0, 250000);
            $this->db->update('XaviFusionAutomationRuns', [
                'status' => 'success', 'finishedAt' => gmdate('Y-m-d H:i:s'), 'durationMs' => $duration,
                'summaryJson' => $summary, 'errorText' => null,
            ], ['runID' => $runID]);
            if ($id) $this->db->update('XaviFusionAutomations', [
                'lastRunAt' => gmdate('Y-m-d H:i:s'), 'lastStatus' => 'success', 'lastMessage' => t('Completed in %s ms.', $duration),
                'nextRunAt' => !empty($automation['enabled']) ? gmdate('Y-m-d H:i:s', time() + ((int) $automation['intervalMinutes'] * 60)) : null,
                'updatedAt' => gmdate('Y-m-d H:i:s'),
            ], ['automationID' => $id]);
            return ['automation_id' => $id, 'run_id' => $runID, 'status' => 'success', 'result' => $result];
        } catch (\Throwable $exc) {
            $duration = (int) round((microtime(true) - $started) * 1000);
            $this->db->update('XaviFusionAutomationRuns', [
                'status' => 'failed', 'finishedAt' => gmdate('Y-m-d H:i:s'), 'durationMs' => $duration,
                'errorText' => substr($exc->getMessage(), 0, 60000),
            ], ['runID' => $runID]);
            if ($id) $this->db->update('XaviFusionAutomations', [
                'lastRunAt' => gmdate('Y-m-d H:i:s'), 'lastStatus' => 'failed', 'lastMessage' => substr($exc->getMessage(), 0, 2000),
                'nextRunAt' => !empty($automation['enabled']) ? gmdate('Y-m-d H:i:s', time() + ((int) $automation['intervalMinutes'] * 60)) : null,
                'updatedAt' => gmdate('Y-m-d H:i:s'),
            ], ['automationID' => $id]);
            return ['automation_id' => $id, 'run_id' => $runID, 'status' => 'failed', 'error' => $exc->getMessage()];
        }
    }

    private function executeAction(string $action, array $payload): array
    {
        switch ($action) {
            case 'sidecar_health':
                return $this->sidecar->publicJson('/healthz');
            case 'connector_health':
                return $this->sidecar->systemJson('GET', '/internal/v1/connectors/status');
            case 'dataset_discover':
                return $this->sidecar->systemJson('POST', '/internal/v1/datasets/discover', null, ['project_id' => (string) ($payload['project_id'] ?? '')]);
            case 'dataset_scan':
                $id = $this->required($payload, 'dataset_id');
                return $this->sidecar->systemJson('POST', '/internal/v1/datasets/' . rawurlencode($id) . '/scan', []);
            case 'dataset_profile':
                $id = $this->required($payload, 'dataset_id');
                return $this->sidecar->systemJson('POST', '/internal/v1/datasets/' . rawurlencode($id) . '/profile', []);
            case 'dataset_import':
                $this->required($payload, 'dataset_id');
                return $this->sidecar->systemJson('POST', '/internal/v1/dataset-imports', $payload);
            case 'workspace_audit':
                $key = $this->required($payload, 'workspace_key');
                $result = $this->sidecar->systemJson('GET', '/internal/v1/workspace/' . rawurlencode($key));
                return ['workspace_key' => $key, 'digest' => hash('sha256', json_encode($result, JSON_UNESCAPED_SLASHES)), 'state' => $result];
            case 'witness_verify':
                return $this->sidecar->systemJson('GET', '/internal/v1/witness/verify', null, [
                    'workspace_key' => (string) ($payload['workspace_key'] ?? ''),
                    'case_id' => (string) ($payload['case_id'] ?? ''),
                ]);
            case 'prune_automation_history':
                return ['deleted' => $this->pruneRuns((int) ($payload['days'] ?? 30))];
        }
        throw new \RuntimeException(t('Unsupported automation action.'));
    }

    private function required(array $payload, string $key): string
    {
        $value = trim((string) ($payload[$key] ?? ''));
        if ($value === '') throw new \InvalidArgumentException(t('%s is required.', $key));
        return $value;
    }
}
''')

write('src/Xavi/FusionOS/AutomationHttpController.php',r'''<?php
namespace Xavi\FusionOS;

use Concrete\Core\Controller\Controller;
use Concrete\Core\Http\Request;
use Symfony\Component\HttpFoundation\JsonResponse;

class AutomationHttpController extends Controller
{
    private Request $request;
    private AutomationService $automations;

    public function __construct(Request $request, AutomationService $automations)
    {
        parent::__construct();
        $this->request = $request;
        $this->automations = $automations;
    }

    public function runDue(): JsonResponse
    {
        $runtimeFile = dirname(__DIR__, 3) . '/config/runtime.php';
        $runtime = is_file($runtimeFile) ? require $runtimeFile : [];
        $expected = is_array($runtime) ? (string) ($runtime['automation_token'] ?? '') : '';
        $provided = (string) $this->request->headers->get('X-Xavi-Automation-Token', '');
        if ($expected === '' || $provided === '' || !hash_equals($expected, $provided)) {
            return new JsonResponse(['error' => 'Not found'], 404, ['Cache-Control' => 'no-store']);
        }
        $results = $this->automations->runDue(10);
        return new JsonResponse(['ok' => true, 'count' => count($results), 'results' => $results], 200, ['Cache-Control' => 'no-store']);
    }
}
''')

