# Patch SidecarClient with a system-signed request path.
p=root/'src/Xavi/FusionOS/SidecarClient.php';s=p.read_text()
anchor="    public function publicJson(string $path, array $query = []): array\n"
insert=r'''    public function systemJson(string $method, string $path, ?array $payload = null, array $query = []): array
    {
        $runtime = $this->runtime();
        $secret = (string) ($runtime['shared_secret'] ?? $this->config->get('xavi_fusion_os.shared_secret'));
        if ($secret === '') throw new \RuntimeException('Fusion sidecar shared secret is not configured.');
        $method = strtoupper($method);
        $body = $payload === null ? '' : json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        $timestamp = (string) time();
        $actor = 'xavi-automation';
        $signature = hash_hmac('sha256', implode("\n", [$method, $path, $timestamp, $actor, hash('sha256', $body)]), $secret);
        [$status, $headers, $response] = $this->transport($method, $path, $body, $query, [
            'Accept: application/json', 'Content-Type: application/json', 'X-Xavi-User: ' . $actor,
            'X-Xavi-Timestamp: ' . $timestamp, 'X-Xavi-Signature: ' . $signature,
        ], 130);
        $decoded = json_decode($response, true);
        if ($status < 200 || $status >= 300) {
            $detail = is_array($decoded) ? ($decoded['detail'] ?? $response) : $response;
            throw new \RuntimeException('Fusion sidecar returned HTTP ' . $status . ': ' . $detail);
        }
        return is_array($decoded) ? $decoded : ['value' => $response];
    }

'''
