<?php
namespace Xavi\FusionOS;

defined('C5_EXECUTE') or die('Access Denied.');

use Concrete\Core\User\User;

/**
 * Persistent Fusion Launcher layout service.
 *
 * The historical class/table names are intentionally retained as storage/API
 * compatibility aliases. User-visible language is "Launcher", not "Start".
 */
class StartMenuService
{
    private $db;
    private const SIZES = ['small','medium','wide','large'];
    private const EVENTS = ['category:open','category:updated','tile:pinned','tile:unpinned','tile:moved','tile:opened','folder:created','folder:updated','automation:test'];
    private const DEFAULT_GROUP = 'pinned';
    private const DEFAULT_COLUMNS = 8;
    private const MAX_COLUMNS = 128;
    private const MAX_ROWS = 512;

    public function __construct()
    {
        $this->db = app('database')->connection();
        $this->ensureSchema();
    }

    public function ensureSchema(): void
    {
        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionStartMenuItems (
            uID INT UNSIGNED NOT NULL,
            appID VARCHAR(128) NOT NULL,
            startPinned TINYINT(1) NOT NULL DEFAULT 0,
            taskbarPinned TINYINT(1) NOT NULL DEFAULT 0,
            tileSize VARCHAR(16) NOT NULL DEFAULT 'medium',
            tileX INT NULL DEFAULT NULL,
            tileY INT NULL DEFAULT NULL,
            groupID VARCHAR(64) NOT NULL DEFAULT 'pinned',
            sortOrder INT NOT NULL DEFAULT 0,
            groupName VARCHAR(190) NOT NULL DEFAULT 'Pinned',
            folderID VARCHAR(64) NULL DEFAULT NULL,
            folderSortOrder INT NOT NULL DEFAULT 0,
            liveEnabled TINYINT(1) NOT NULL DEFAULT 0,
            locked TINYINT(1) NOT NULL DEFAULT 0,
            updatedAt DATETIME NOT NULL,
            PRIMARY KEY (uID, appID),
            KEY xaviFusionStartUserPosition (uID, startPinned, groupID, tileY, tileX),
            KEY xaviFusionTaskbarUserOrder (uID, taskbarPinned, sortOrder),
            KEY xaviFusionLauncherFolderChildren (uID, folderID, folderSortOrder)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $this->ensureTableColumn('XaviFusionStartMenuItems','tileX','INT NULL DEFAULT NULL');
        $this->ensureTableColumn('XaviFusionStartMenuItems','tileY','INT NULL DEFAULT NULL');
        $this->ensureTableColumn('XaviFusionStartMenuItems','groupID',"VARCHAR(64) NOT NULL DEFAULT 'pinned'");
        $this->ensureTableColumn('XaviFusionStartMenuItems','folderID','VARCHAR(64) NULL DEFAULT NULL');
        $this->ensureTableColumn('XaviFusionStartMenuItems','folderSortOrder','INT NOT NULL DEFAULT 0');
        $this->ensureTableColumn('XaviFusionStartMenuItems','liveEnabled','TINYINT(1) NOT NULL DEFAULT 0');
        $this->ensureTableColumn('XaviFusionStartMenuItems','locked','TINYINT(1) NOT NULL DEFAULT 0');

        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionStartMenuGroups (
            uID INT UNSIGNED NOT NULL,
            groupID VARCHAR(64) NOT NULL,
            name VARCHAR(190) NOT NULL,
            accent VARCHAR(16) NOT NULL DEFAULT '#0067c0',
            background VARCHAR(16) NOT NULL DEFAULT '#202020',
            gridColumns INT NOT NULL DEFAULT 8,
            gridRows INT NOT NULL DEFAULT 10,
            sortOrder INT NOT NULL DEFAULT 10,
            collapsed TINYINT(1) NOT NULL DEFAULT 0,
            locked TINYINT(1) NOT NULL DEFAULT 0,
            automationEnabled TINYINT(1) NOT NULL DEFAULT 0,
            automationEvents VARCHAR(512) NOT NULL DEFAULT '',
            automationCode LONGTEXT NOT NULL,
            createdAt DATETIME NOT NULL,
            updatedAt DATETIME NOT NULL,
            PRIMARY KEY (uID, groupID),
            KEY xaviFusionStartGroupsOrder (uID, sortOrder, name)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $this->ensureTableColumn('XaviFusionStartMenuGroups','locked','TINYINT(1) NOT NULL DEFAULT 0');

        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionLauncherFolders (
            uID INT UNSIGNED NOT NULL,
            folderID VARCHAR(64) NOT NULL,
            name VARCHAR(190) NOT NULL DEFAULT '',
            groupID VARCHAR(64) NOT NULL DEFAULT 'pinned',
            tileSize VARCHAR(16) NOT NULL DEFAULT 'medium',
            tileX INT NOT NULL DEFAULT 0,
            tileY INT NOT NULL DEFAULT 0,
            sortOrder INT NOT NULL DEFAULT 10,
            expanded TINYINT(1) NOT NULL DEFAULT 0,
            locked TINYINT(1) NOT NULL DEFAULT 0,
            createdAt DATETIME NOT NULL,
            updatedAt DATETIME NOT NULL,
            PRIMARY KEY (uID, folderID),
            KEY xaviFusionLauncherFoldersPosition (uID, groupID, tileY, tileX),
            KEY xaviFusionLauncherFoldersOrder (uID, groupID, sortOrder)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $this->migrateLegacyRows();
    }

    public function layout(User $user): array
    {
        $this->registered($user);
        $this->ensureDefaultGroup((int)$user->getUserID());
        $rows=$this->db->fetchAllAssociative(
            'SELECT i.appID,i.startPinned,i.taskbarPinned,i.tileSize,i.tileX,i.tileY,i.groupID,i.sortOrder,i.groupName,i.folderID,i.folderSortOrder,i.liveEnabled,i.locked,i.updatedAt,g.name AS resolvedGroupName
             FROM XaviFusionStartMenuItems i
             LEFT JOIN XaviFusionStartMenuGroups g ON g.uID=i.uID AND g.groupID=i.groupID
             WHERE i.uID=? ORDER BY i.sortOrder,i.appID',
            [(int)$user->getUserID()]
        );
        return array_map(fn(array $row):array=>$this->normalizeRow($row),$rows);
    }

    public function groups(User $user): array
    {
        $this->registered($user);$uID=(int)$user->getUserID();$this->ensureDefaultGroup($uID);
        $rows=$this->db->fetchAllAssociative(
            'SELECT g.*,COUNT(DISTINCT i.appID) AS itemCount
             FROM XaviFusionStartMenuGroups g
             LEFT JOIN XaviFusionStartMenuItems i ON i.uID=g.uID AND i.groupID=g.groupID AND i.startPinned=1
             WHERE g.uID=? GROUP BY g.uID,g.groupID,g.name,g.accent,g.background,g.gridColumns,g.gridRows,g.sortOrder,g.collapsed,g.locked,g.automationEnabled,g.automationEvents,g.automationCode,g.createdAt,g.updatedAt
             ORDER BY g.sortOrder,g.name,g.groupID',[$uID]);
        return array_map(fn(array $row):array=>$this->normalizeGroup($row),$rows);
    }

    public function folders(User $user): array
    {
        $this->registered($user);$uID=(int)$user->getUserID();
