from __future__ import annotations

import argparse
import json
from typing import Any, Iterable

from .backend import XaviBackend


def clean(value: Any) -> str:
    return str(value if value is not None else "").replace("\t", " ").replace("\r", " ").replace("\n", " ")


def get(row: dict[str, Any], *names: str, default: Any = "") -> Any:
    for name in names:
        if name in row and row[name] not in (None, ""):
            return row[name]
    return default


def state_text(state: dict[str, Any]) -> str:
    doctor = state.get("doctor", {}) or {}
    identity = state.get("identity", {}) or {}
    return "\n".join([
        "XAVI BACKEND CONTROL CENTER",
        "===========================",
        "",
        f"User: {get(identity, 'user', default='-')}",
        f"Rootless container graph: {get(identity, 'graph_root', default='-')}",
        "",
        f"Containers: {len(state.get('containers', []) or [])}",
        f"Services: {len(state.get('services', []) or [])}",
        f"Projects: {len(state.get('projects', []) or [])}",
        f"Remote nodes: {len(state.get('remote_nodes', []) or [])}",
        f"Filesystems: {len(state.get('filesystems', []) or [])}",
        "",
        f"Doctor: {'PASS' if doctor.get('ok') else 'ATTENTION'}",
        f"Issues: {doctor.get('issue_count', 0)}    Warnings: {doctor.get('warning_count', 0)}",
        "",
        "Mouse: click buttons; drag title bars; resize from window borders.",
        "Mutations are always previewed before the native UI offers Apply.",
    ])


def rows_for(state: dict[str, Any], kind: str) -> Iterable[tuple[str, str, str]]:
    if kind == "container":
        for row in state.get("containers", []) or []:
            details = row.get("details", {}) or {}
            yield clean(get(row, "name", "id")), clean(get(row, "state", default=get(details, "state", default="-"))), clean(get(details, "health", default=""))
    elif kind == "service":
        for row in state.get("services", []) or []:
            target = clean(get(row, "name", "unit"))
            state_s = clean(get(row, "active", "state", default="-"))
            detail = clean(get(row, "sub", "description", default=""))
            yield target, state_s, detail
    elif kind == "project":
        for row in state.get("projects", []) or []:
            yield clean(get(row, "id", "name", "project")), clean(get(row, "state", "status", default="-")), clean(get(row, "path", "description", default=""))
    elif kind == "remote-container":
        for node in state.get("remote_nodes", []) or []:
            node_name = clean(get(node, "name", "host", default="remote"))
            containers = node.get("containers", []) or []
            if containers:
                for row in containers:
                    cname = clean(get(row, "name", "id"))
                    # Backend remote target convention may already be present. Prefer it.
                    target = clean(get(row, "target", default=f"{node_name}:{cname}"))
                    yield target, clean(get(row, "state", "status", default="-")), node_name
            else:
                # Read-only node row; action controls are suppressed by native UI if target is empty.
                yield "", clean(get(node, "status", "state", default="-")), node_name


def report(backend: XaviBackend, name: str) -> str:
    state = backend.state(max_age=0)
    if name == "overview":
        return state_text(state)
    if name == "doctor":
        return json.dumps(state.get("doctor", {}), indent=2, sort_keys=True, default=str)
    if name == "storage":
        return json.dumps(state.get("filesystems", []), indent=2, sort_keys=True, default=str)
    if name == "resources":
        return json.dumps(backend.resources(), indent=2, sort_keys=True, default=str)
    if name == "advisor":
        return json.dumps(backend.advisor_status(), indent=2, sort_keys=True, default=str)
    if name == "contract":
        return json.dumps(backend.contract(), indent=2, sort_keys=True, default=str)
    raise SystemExit(f"unknown report: {name}")


def main() -> int:
    parser = argparse.ArgumentParser(prog="xavi-man-native-bridge")
    sub = parser.add_subparsers(dest="cmd", required=True)
    p_report = sub.add_parser("report")
    p_report.add_argument("name", choices=["overview", "doctor", "storage", "resources", "advisor", "contract"])
    p_list = sub.add_parser("list")
    p_list.add_argument("kind", choices=["container", "service", "project", "remote-container"])
    p_action = sub.add_parser("action")
    p_action.add_argument("kind", choices=["container", "service", "project", "remote-container"])
    p_action.add_argument("verb", choices=["start", "stop", "restart", "enable", "disable"])
    p_action.add_argument("target")
    p_action.add_argument("mode", choices=["preview", "apply"])
    args = parser.parse_args()

    backend = XaviBackend()
    if args.cmd == "report":
        print(report(backend, args.name))
        return 0
    if args.cmd == "list":
        state = backend.state(max_age=0)
        for target, status, detail in rows_for(state, args.kind):
            print("\t".join((clean(target), clean(status), clean(detail))))
        return 0
    if args.cmd == "action":
        if args.kind != "service" and args.verb in {"enable", "disable"}:
            raise SystemExit("enable/disable only valid for services")
        result = backend.action(kind=args.kind, verb=args.verb, target=args.target, apply=args.mode == "apply")
        print(json.dumps(result, indent=2, sort_keys=True, default=str))
        return 0
    return 2


if __name__ == "__main__":
    raise SystemExit(main())
PY

cat > "$ROOT/native/xavi_man_twin.c" <<'C'
#define _GNU_SOURCE
#include <Tw/Tw.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_WINDOWS 48
#define MAX_ROWS 120
#define MAX_TEXT 65536

enum {
  CODE_OVERVIEW = 10,
  CODE_CONTAINERS = 11,
  CODE_SERVICES = 12,
  CODE_PROJECTS = 13,
  CODE_REMOTE = 14,
  CODE_STORAGE = 15,
  CODE_DOCTOR = 16,
  CODE_RESOURCES = 17,
  CODE_ADVISOR = 18,
  CODE_CONTRACT = 19,
  CODE_REFRESH = 20,
  CODE_EXIT = 21,
  CODE_ACTION_BASE = 1000,
  CODE_CONFIRM_APPLY = 30000,
  CODE_CONFIRM_CANCEL = 30001
};

typedef struct {
  char target[256];
  char status[128];
  char detail[256];
} Row;

typedef struct {
  twindow win;
  int kind;              /* 0 report, 1 container, 2 service, 3 project, 4 remote */
  int row_count;
  Row rows[MAX_ROWS];
} ManagedWindow;

static ManagedWindow windows[MAX_WINDOWS];
static int window_count = 0;
static twindow main_win = TW_NOID;
static tmenu main_menu = TW_NOID;
static tmsgport msgport = TW_NOID;
static twindow confirm_win = TW_NOID;
static char pending_kind[32];
static char pending_verb[32];
static char pending_target[256];
static char bridge_cmd[1024];

TW_DECL_MAGIC(xavi_magic);

static const char *kind_name(int kind) {
  switch (kind) {
    case 1: return "container";
    case 2: return "service";
    case 3: return "project";
    case 4: return "remote-container";
    default: return "";
  }
}

static int kind_id(const char *kind) {
  if (!strcmp(kind, "container")) return 1;
  if (!strcmp(kind, "service")) return 2;
  if (!strcmp(kind, "project")) return 3;
  if (!strcmp(kind, "remote-container")) return 4;
  return 0;
}

static char *shell_quote(const char *s) {
  size_t n = 3;
  const char *p;
  char *out, *q;
  for (p = s; *p; ++p) n += (*p == '\'' ? 4 : 1);
  out = malloc(n);
  if (!out) return NULL;
  q = out; *q++ = '\'';
  for (p = s; *p; ++p) {
    if (*p == '\'') { memcpy(q, "'\\''", 4); q += 4; }
    else *q++ = *p;
  }
  *q++ = '\''; *q = 0;
  return out;
}

static char *run_bridge(const char *args) {
  FILE *fp;
  char *buf = calloc(1, MAX_TEXT);
  size_t used = 0;
  if (!buf) return NULL;
  snprintf(bridge_cmd, sizeof(bridge_cmd),
           "/var/www/xavi/xavi-man-app/.venv/bin/python -m xavi_man.native_bridge %s 2>&1", args);
  fp = popen(bridge_cmd, "r");
  if (!fp) { snprintf(buf, MAX_TEXT, "Failed to start Xavi backend bridge.\n"); return buf; }
  while (used + 1 < MAX_TEXT) {
    size_t got = fread(buf + used, 1, MAX_TEXT - used - 1, fp);
    used += got;
    if (!got) break;
  }
  buf[used] = 0;
  pclose(fp);
  return buf;
}

static ManagedWindow *register_window(twindow win, int kind) {
  ManagedWindow *m;
  if (window_count >= MAX_WINDOWS) return NULL;
  m = &windows[window_count++];
  memset(m, 0, sizeof(*m));
  m->win = win;
  m->kind = kind;
  return m;
}

static ManagedWindow *find_window(twindow win) {
  int i;
  for (i = 0; i < window_count; ++i) if (windows[i].win == win) return &windows[i];
  return NULL;
}

static void forget_window(twindow win) {
  int i;
  for (i = 0; i < window_count; ++i) {
    if (windows[i].win == win) {
      windows[i] = windows[window_count - 1];
      --window_count;
      return;
    }
  }
}

static void write_lines(twindow win, const char *text, int maxw, int maxlines) {
  int y = 0;
  const char *p = text;
  while (*p && y < maxlines) {
    const char *e = strchr(p, '\n');
    size_t n = e ? (size_t)(e - p) : strlen(p);
    if ((int)n > maxw) n = maxw;
    TwGotoXYWindow(win, 1, y++);
    TwWriteCharsetWindow(win, n, p);
    p = e ? e + 1 : p + n;
    if (!e) break;
  }
}

static twindow make_window(const char *title, int w, int h, int scroll) {
  twindow win = TwCreateWindow(strlen(title), title, NULL, main_menu,
      TCOL(tblack, twhite), TW_LINECURSOR,
      TW_WINDOW_WANT_KEYS | TW_WINDOW_WANT_CHANGES | TW_WINDOW_DRAG |
      TW_WINDOW_RESIZE | TW_WINDOW_Y_BAR | TW_WINDOW_CLOSE,
      TW_WINDOWFL_ROWS_DEFCOL, w, h, scroll);
  if (win) {
    TwSetColorsWindow(win, (1 << 6), TCOL0, TCOL0, TCOL0, TCOL0, TCOL0, TCOL0,
                      TCOL(tWHITE, tblue), TCOL0, TCOL0);
    TwMapWindow(win, TwFirstScreen());
  }
  return win;
}

static void report_window(const char *title, const char *report) {
  char args[128];
  char *text;
  twindow win;
  snprintf(args, sizeof(args), "report %s", report);
  text = run_bridge(args);
  if (!text) return;
  win = make_window(title, 82, 28, 220);
  if (win) {
    register_window(win, 0);
    write_lines(win, text, 78, 210);
  }
  free(text);
  TwFlush();
}

static int parse_rows(char *text, Row *rows, int maxrows) {
  int n = 0;
  char *save1 = NULL, *line = strtok_r(text, "\n", &save1);
  while (line && n < maxrows) {
    char *save2 = NULL;
    char *a = strtok_r(line, "\t", &save2);
    char *b = strtok_r(NULL, "\t", &save2);
    char *c = strtok_r(NULL, "\t", &save2);
    snprintf(rows[n].target, sizeof(rows[n].target), "%s", a ? a : "");
    snprintf(rows[n].status, sizeof(rows[n].status), "%s", b ? b : "");
    snprintf(rows[n].detail, sizeof(rows[n].detail), "%s", c ? c : "");
    ++n;
    line = strtok_r(NULL, "\n", &save1);
  }
  return n;
}

static void add_action_buttons(twindow win, int row, int y, int service) {
  int base = CODE_ACTION_BASE + row * 10;
  TwCreateButtonGadget(win, 7, 1, " Start ", base + 1, 0,
      TCOL(tblack, twhite), TCOL(twhite, tblue), TCOL(tWHITE, tblue), 47, y);
  TwCreateButtonGadget(win, 6, 1, " Stop ", base + 2, 0,
      TCOL(tblack, twhite), TCOL(twhite, tblue), TCOL(tWHITE, tblue), 56, y);
  TwCreateButtonGadget(win, 9, 1, " Restart ", base + 3, 0,
      TCOL(tblack, twhite), TCOL(twhite, tblue), TCOL(tWHITE, tblue), 64, y);
  if (service) {
    TwCreateButtonGadget(win, 8, 1, " Enable ", base + 4, 0,
        TCOL(tblack, twhite), TCOL(twhite, tblue), TCOL(tWHITE, tblue), 75, y);
    TwCreateButtonGadget(win, 9, 1, " Disable ", base + 5, 0,
        TCOL(tblack, twhite), TCOL(twhite, tblue), TCOL(tWHITE, tblue), 85, y);
  }
}

static void list_window(const char *title, const char *kind) {
  char args[128];
  char *text;
  twindow win;
  ManagedWindow *m;
  int i, kid = kind_id(kind);
  snprintf(args, sizeof(args), "list %s", kind);
  text = run_bridge(args);
  if (!text) return;
  win = make_window(title, kid == 2 ? 98 : 80, 28, 240);
  if (!win) { free(text); return; }
  m = register_window(win, kid);
  if (!m) { TwDeleteWindow(win); free(text); return; }
  m->row_count = parse_rows(text, m->rows, MAX_ROWS);
  TwGotoXYWindow(win, 1, 0); TwWriteCharsetWindow(win, 42, "Target / Unit                              State");
  for (i = 0; i < m->row_count; ++i) {
    char line[96];
    int y = 2 + i * 2;
    snprintf(line, sizeof(line), "%-40.40s %-14.14s", m->rows[i].target[0] ? m->rows[i].target : m->rows[i].detail, m->rows[i].status);
    TwGotoXYWindow(win, 1, y); TwWriteCharsetWindow(win, strlen(line), line);
    if (m->rows[i].target[0]) add_action_buttons(win, i, y, kid == 2);
    if (m->rows[i].detail[0]) {
      snprintf(line, sizeof(line), "  %.70s", m->rows[i].detail);
      TwGotoXYWindow(win, 1, y + 1); TwWriteCharsetWindow(win, strlen(line), line);
    }
  }
  free(text);
  TwFlush();
}

static void close_confirm(void) {
  if (confirm_win) { TwDeleteWindow(confirm_win); confirm_win = TW_NOID; TwFlush(); }
}

static void action_result(const char *mode) {
  char *q, args[1024], *text;
  twindow win;
  q = shell_quote(pending_target);
  if (!q) return;
  snprintf(args, sizeof(args), "action %s %s %s %s", pending_kind, pending_verb, q, mode);
  free(q);
  text = run_bridge(args);
  if (!text) return;
  win = make_window(!strcmp(mode, "apply") ? "Action Result" : "Action Preview", 78, 24, 180);
  if (win) {
    register_window(win, 0);
    write_lines(win, text, 74, 160);
  }
  free(text);
  TwFlush();
}

static void confirm_action(ManagedWindow *m, int row, int op) {
  const char *verb = op == 1 ? "start" : op == 2 ? "stop" : op == 3 ? "restart" : op == 4 ? "enable" : "disable";
  char *q, args[1024], *preview;
  if (!m || row < 0 || row >= m->row_count) return;
  snprintf(pending_kind, sizeof(pending_kind), "%s", kind_name(m->kind));
  snprintf(pending_verb, sizeof(pending_verb), "%s", verb);
  snprintf(pending_target, sizeof(pending_target), "%s", m->rows[row].target);
  q = shell_quote(pending_target);
  if (!q) return;
  snprintf(args, sizeof(args), "action %s %s %s preview", pending_kind, pending_verb, q);
  free(q);
  preview = run_bridge(args);
  close_confirm();
  confirm_win = make_window("Confirm Xavi Action", 72, 22, 160);
  if (confirm_win) {
    char heading[512];
    snprintf(heading, sizeof(heading), "PREVIEW ONLY\n\n%s %s\nTarget: %s\n\n", pending_verb, pending_kind, pending_target);
    write_lines(confirm_win, heading, 68, 8);
    if (preview) {
      TwGotoXYWindow(confirm_win, 1, 6);
      write_lines(confirm_win, preview, 68, 10);
    }
    TwCreateButtonGadget(confirm_win, 9, 1, "  APPLY  ", CODE_CONFIRM_APPLY, 0,
        TCOL(tblack, twhite), TCOL(twhite, tblue), TCOL(tWHITE, tblue), 18, 18);
    TwCreateButtonGadget(confirm_win, 10, 1, "  Cancel  ", CODE_CONFIRM_CANCEL, 0,
        TCOL(tblack, twhite), TCOL(twhite, tblue), TCOL(tWHITE, tblue), 38, 18);
  }
  free(preview);
  TwFlush();
}

static void build_main(void) {
  const char *title = "Xavi Backend Manager";
  main_win = TwCreateWindow(strlen(title), title, NULL, main_menu,
      TCOL(tblack, twhite), TW_LINECURSOR,
      TW_WINDOW_DRAG | TW_WINDOW_RESIZE | TW_WINDOW_CLOSE,
      TW_WINDOWFL_ROWS_DEFCOL, 76, 24, 0);
  if (!main_win) return;
  TwSetColorsWindow(main_win, (1 << 6), TCOL0, TCOL0, TCOL0, TCOL0, TCOL0, TCOL0,
                    TCOL(tWHITE, tblue), TCOL0, TCOL0);
  TwGotoXYWindow(main_win, 2, 1);
  TwWriteCharsetWindow(main_win, 55, "XAVI PROJECTS / HOST / CONTAINER OPERATIONS DESKTOP");
  TwGotoXYWindow(main_win, 2, 3);
  TwWriteCharsetWindow(main_win, 65, "Mouse-driven windows. Every mutation is preview-first and confirmed.");

#define BTN(code,label,x,y) TwCreateButtonGadget(main_win, strlen(label), 1, label, code, 0, TCOL(tblack,twhite), TCOL(twhite,tblue), TCOL(tWHITE,tblue), x, y)
  BTN(CODE_OVERVIEW,   " Overview ",    4, 6);
  BTN(CODE_CONTAINERS, " Containers ", 20, 6);
  BTN(CODE_SERVICES,   " Services ",   39, 6);
  BTN(CODE_PROJECTS,   " Projects ",   55, 6);
  BTN(CODE_REMOTE,     " Remote Nodes ",4, 10);
  BTN(CODE_STORAGE,    " Storage ",    23, 10);
  BTN(CODE_DOCTOR,     " Doctor ",     39, 10);
  BTN(CODE_RESOURCES,  " Resources ",  54, 10);
  BTN(CODE_ADVISOR,    " AI Advisor ", 4, 14);
  BTN(CODE_CONTRACT,   " Contract ",   22, 14);
  BTN(CODE_REFRESH,    " Refresh ",    39, 14);
  BTN(CODE_EXIT,       " Exit ",       55, 14);
#undef BTN
  TwGotoXYWindow(main_win, 2, 19);
  TwWriteCharsetWindow(main_win, 68, "Drag windows by title; resize borders; use scrollbars on long lists.");
  TwMapWindow(main_win, TwFirstScreen());
  TwFlush();
}

static void handle_main_code(udat code) {
  switch (code) {
    case 0: exit(0);
    case CODE_OVERVIEW: report_window("Xavi Overview", "overview"); break;
    case CODE_CONTAINERS: list_window("Containers", "container"); break;
    case CODE_SERVICES: list_window("Services", "service"); break;
    case CODE_PROJECTS: list_window("Projects", "project"); break;
    case CODE_REMOTE: list_window("Remote Containers / Nodes", "remote-container"); break;
    case CODE_STORAGE: report_window("Storage / Filesystems", "storage"); break;
    case CODE_DOCTOR: report_window("Xavi Doctor", "doctor"); break;
    case CODE_RESOURCES: report_window("WG-RNN / Host Resources", "resources"); break;
    case CODE_ADVISOR: report_window("AI Advisor", "advisor"); break;
    case CODE_CONTRACT: report_window("Witness Contract", "contract"); break;
    case CODE_REFRESH: report_window("Fresh Xavi Overview", "overview"); break;
    case CODE_EXIT: exit(0);
  }
}

int main(void) {
  tmsg msg;
  tevent_any ev;
  uldat err;

  if (!(TwCheckMagic(xavi_magic) && TwOpen(NULL) &&
        (msgport = TwCreateMsgPort(8, "xavi-man")))) goto fail;

  main_menu = TwCreateMenu(TCOL(tblack, twhite), TCOL(twhite, tblue),
                           TCOL(tBLACK, twhite), TCOL(tBLACK, tblack),
                           TCOL(tred, twhite), TCOL(tred, tblue), (byte)0);
  build_main();
  if (!main_win) goto fail;

  while ((msg = TwReadMsg(ttrue))) {
    ev = &msg->Event;
    if (msg->Type != TW_MSG_WIDGET_GADGET) continue;
    if (ev->EventGadget.W == main_win) {
      handle_main_code(ev->EventGadget.Code);
      continue;
    }
    if (confirm_win && ev->EventGadget.W == confirm_win) {
      if (ev->EventGadget.Code == 0 || ev->EventGadget.Code == CODE_CONFIRM_CANCEL) close_confirm();
      else if (ev->EventGadget.Code == CODE_CONFIRM_APPLY) {
        close_confirm();
        action_result("apply");
      }
      continue;
    }
    {
      ManagedWindow *m = find_window(ev->EventGadget.W);
      if (!m) continue;
      if (ev->EventGadget.Code == 0) {
        twindow old = m->win;
        forget_window(old);
        TwDeleteWindow(old);
        TwFlush();
      } else if (ev->EventGadget.Code >= CODE_ACTION_BASE) {
        int v = ev->EventGadget.Code - CODE_ACTION_BASE;
        int row = v / 10;
        int op = v % 10;
        if (op >= 1 && op <= 5) confirm_action(m, row, op);
      }
    }
  }

fail:
  err = TwErrno;
  if (err) fprintf(stderr, "xavi-man-twin: libtw error: %s%s\n", TwStrError(err), TwStrErrorDetail(err, TwErrnoDetail));
  if (!TwInPanic()) TwClose();
  return 1;
}
