  for (i = 0; i < MAX_ICONS; ++i) if (icons[i].gadget == g) return i;
  return -1;
}

static char *shell_quote(const char *s) {
  size_t n = 3;
  const char *p;
  char *out, *q;
  for (p = s; *p; ++p) n += (*p == '\'' ? 4 : 1);
  out = malloc(n);
  if (!out) return NULL;
  q = out; *q++ = '\'';
  for (p = s; *p; ++p) {
    if (*p == '\'') { memcpy(q, "'\\''", 4); q += 4; }
    else *q++ = *p;
  }
  *q++ = '\''; *q = 0;
  return out;
}

static char *run_bridge(const char *args) {
  FILE *fp;
  char *buf = calloc(1, MAX_TEXT);
  size_t used = 0;
  if (!buf) return NULL;
  snprintf(bridge_cmd, sizeof(bridge_cmd),
           "cd /var/www/xavi/xavi-man-app && /var/www/xavi/xavi-man-app/.venv/bin/python -m xavi_man.native_bridge %s 2>&1", args);
  fp = popen(bridge_cmd, "r");
  if (!fp) { snprintf(buf, MAX_TEXT, "Failed to start Xavi backend bridge.\n"); return buf; }
  while (used + 1 < MAX_TEXT) {
    size_t got = fread(buf + used, 1, MAX_TEXT - used - 1, fp);
    used += got;
    if (!got) break;
  }
  buf[used] = 0;
  pclose(fp);
  return buf;
}

static void write_lines_at(twindow win, const char *text, int maxw, int maxlines, int start_y) {
  int y = start_y;
  const char *p = text;
  while (*p && y < maxlines) {
    const char *e = strchr(p, '\n');
    size_t n = e ? (size_t)(e - p) : strlen(p);
    if ((int)n > maxw) n = maxw;
    TwGotoXYWindow(win, 1, y++);
    TwWriteCharsetWindow(win, n, p);
    p = e ? e + 1 : p + n;
    if (!e) break;
  }
}

static twindow make_window(const char *title, int w, int h, int scroll) {
  twindow win = TwCreateWindow(strlen(title), title, NULL, main_menu,
      TCOL(tblack, twhite), TW_LINECURSOR,
      TW_WINDOW_WANT_KEYS | TW_WINDOW_WANT_MOUSE | TW_WINDOW_WANT_CHANGES |
      TW_WINDOW_DRAG | TW_WINDOW_RESIZE | TW_WINDOW_Y_BAR | TW_WINDOW_CLOSE,
      TW_WINDOWFL_ROWS_DEFCOL, w, h, scroll);
  if (win) {
    TwSetColorsWindow(win, (1 << 6), (tcolor)0, (tcolor)0, (tcolor)0, (tcolor)0, (tcolor)0, (tcolor)0,
                      TCOL((thigh | twhite), tblue), (tcolor)0, (tcolor)0);
    TwMapWindow(win, TwFirstScreen());
    TwRaiseWindow(win);
  }
  return win;
}

static void rebuild_taskbar(void);

static ManagedWindow *register_window(twindow win, int kind, int app_code, const char *title) {
  ManagedWindow *m;
  if (window_count >= MAX_WINDOWS) return NULL;
  m = &windows[window_count++];
  memset(m, 0, sizeof(*m));
  m->win = win;
  m->kind = kind;
  m->app_code = app_code;
  m->task_code = next_task_code++;
  snprintf(m->title, sizeof(m->title), "%s", title ? title : "Xavi Window");
  rebuild_taskbar();
  return m;
}

static ManagedWindow *find_window(twindow win) {
  int i;
  for (i = 0; i < window_count; ++i) if (windows[i].win == win) return &windows[i];
  return NULL;
}

static ManagedWindow *find_app_window(int app_code) {
  int i;
  if (!app_code) return NULL;
  for (i = 0; i < window_count; ++i) if (windows[i].app_code == app_code) return &windows[i];
  return NULL;
}

static ManagedWindow *find_task_code(udat code) {
  int i;
  for (i = 0; i < window_count; ++i) if (windows[i].task_code == code) return &windows[i];
  return NULL;
}

static void forget_window(twindow win) {
  int i;
  for (i = 0; i < window_count; ++i) {
    if (windows[i].win == win) {
      if (windows[i].task_gadget) TwDeleteGadget(windows[i].task_gadget);
      windows[i] = windows[window_count - 1];
      --window_count;
      rebuild_taskbar();
      return;
    }
  }
}

static void close_aux(twindow *w) {
  if (*w) { TwDeleteWindow(*w); *w = TW_NOID; TwFlush(); }
}

static void close_confirm(void) { close_aux(&confirm_win); }

static void rebuild_taskbar(void) {
  int i, shown = 0, x = 18;
  char label[16];
  if (!main_win) return;
  for (i = 0; i < window_count; ++i) {
    if (windows[i].task_gadget) {
      TwDeleteGadget(windows[i].task_gadget);
      windows[i].task_gadget = TW_NOID;
    }
  }
  for (i = 0; i < window_count && shown < TASK_SLOTS; ++i) {
    snprintf(label, sizeof(label), " %-10.10s ", windows[i].title);
    windows[i].task_gadget = TwCreateButtonGadget(main_win, 13, 1, label, 0, windows[i].task_code,
        TCOL(tblack,twhite), TCOL(twhite,tblue), TCOL((thigh|twhite),tblue), x, TASKBAR_Y);
    x += 14;
    ++shown;
  }
  TwFlush();
}

static void save_layout(void) {
  FILE *f;
  int i;
  char dir[512], *slash;
  snprintf(dir, sizeof(dir), "%s", layout_path);
  slash = strrchr(dir, '/');
  if (slash) { *slash = 0; mkdir(dir, 0755); }
  f = fopen(layout_path, "w");
  if (!f) return;
  for (i = 0; i < MAX_ICONS; ++i) fprintf(f, "%d\t%d\t%d\n", icons[i].code, icons[i].x, icons[i].y);
  fclose(f);
}

static void load_layout(void) {
  FILE *f = fopen(layout_path, "r");
  int code, x, y;
  if (!f) return;
  while (fscanf(f, "%d\t%d\t%d", &code, &x, &y) == 3) {
    DesktopIcon *ic = icon_by_code(code);
    if (ic) { ic->x = x; ic->y = y; }
  }
  fclose(f);
}

static void arrange_icons(void) {
  int i;
  for (i = 0; i < MAX_ICONS; ++i) {
    int col = i % 5, row = i / 5;
    icons[i].x = 4 + col * 17;
    icons[i].y = 3 + row * 7;
    if (icons[i].gadget) TwSetXYGadget(icons[i].gadget, icons[i].x, icons[i].y);
  }
  save_layout();
  TwFlush();
}

static void set_icon_art(tgadget g, const char *glyph, const char *label) {
  char art[ICON_W * ICON_H];
  size_t gl = strlen(glyph), ll = strlen(label);
  int gx, lx;
  memset(art, ' ', sizeof(art));
  gx = (ICON_W - (int)gl) / 2;
  lx = (ICON_W - (int)ll) / 2;
  if (gx < 0) gx = 0;
  if (lx < 0) lx = 0;
  if (gl > ICON_W) gl = ICON_W;
  if (ll > ICON_W) ll = ICON_W;
  memcpy(art + gx, glyph, gl);
  memcpy(art + ICON_W * 2 + lx, label, ll);
  TwSetTextGadget(g, ICON_W, ICON_H, art, 0, 0);
}

static void create_desktop_icons(void) {
  int i;
  for (i = 0; i < MAX_ICONS; ++i) {
    icons[i].gadget = TwCreateButtonGadget(main_win, ICON_W, ICON_H, "",
        TW_GADGET_WANT_MOUSE | TW_GADGET_WANT_MOUSE_MOTION, icons[i].code,
        TCOL(tblack,twhite), TCOL(tblack,twhite), TCOL((thigh|twhite),tblue), icons[i].x, icons[i].y);
    if (icons[i].gadget) set_icon_art(icons[i].gadget, icons[i].glyph, icons[i].label);
  }
}

static int parse_rows(char *text, Row *rows, int maxrows) {
  int n = 0;
  char *save1 = NULL, *line = strtok_r(text, "\n", &save1);
  while (line && n < maxrows) {
    char *save2 = NULL;
    char *a = strtok_r(line, "\t", &save2);
    char *b = strtok_r(NULL, "\t", &save2);
    char *c = strtok_r(NULL, "\t", &save2);
    snprintf(rows[n].target, sizeof(rows[n].target), "%s", a ? a : "");
    snprintf(rows[n].status, sizeof(rows[n].status), "%s", b ? b : "");
    snprintf(rows[n].detail, sizeof(rows[n].detail), "%s", c ? c : "");
    ++n;
    line = strtok_r(NULL, "\n", &save1);
  }
  return n;
}

static void add_action_buttons(twindow win, int row, int y, int service) {
  int base = CODE_ACTION_BASE + row * 10;
  TwCreateButtonGadget(win, 7, 1, " Start ", 0, base + 1,
      TCOL(tblack,twhite), TCOL(twhite,tblue), TCOL((thigh|twhite),tblue), 47, y);
  TwCreateButtonGadget(win, 6, 1, " Stop ", 0, base + 2,
      TCOL(tblack,twhite), TCOL(twhite,tblue), TCOL((thigh|twhite),tblue), 56, y);
  TwCreateButtonGadget(win, 9, 1, " Restart ", 0, base + 3,
      TCOL(tblack,twhite), TCOL(twhite,tblue), TCOL((thigh|twhite),tblue), 64, y);
  if (service) {
    TwCreateButtonGadget(win, 8, 1, " Enable ", 0, base + 4,
        TCOL(tblack,twhite), TCOL(twhite,tblue), TCOL((thigh|twhite),tblue), 75, y);
    TwCreateButtonGadget(win, 9, 1, " Disable ", 0, base + 5,
        TCOL(tblack,twhite), TCOL(twhite,tblue), TCOL((thigh|twhite),tblue), 85, y);
  }
}

static void report_window(const char *title, const char *report, int app_code) {
  char args[128];
  char *text;
  twindow win;
  ManagedWindow *existing = find_app_window(app_code);
  if (existing) { TwRaiseWindow(existing->win); TwFlush(); return; }
  snprintf(args, sizeof(args), "report %s", report);
  text = run_bridge(args);
  if (!text) return;
  win = make_window(title, 84, 26, 220);
  if (win) {
    register_window(win, 0, app_code, title);
    write_lines_at(win, text, 80, 210, 0);
  }
  free(text);
  TwFlush();
}

static void list_window(const char *title, const char *kind, int app_code) {
  char args[128];
  char *text;
  twindow win;
  ManagedWindow *m, *existing = find_app_window(app_code);
  int i, kid = kind_id(kind);
  if (existing) { TwRaiseWindow(existing->win); TwFlush(); return; }
  snprintf(args, sizeof(args), "list %s", kind);
  text = run_bridge(args);
  if (!text) return;
  win = make_window(title, kid == 2 ? 98 : 84, 27, 240);
  if (!win) { free(text); return; }
  m = register_window(win, kid, app_code, title);
  if (!m) { TwDeleteWindow(win); free(text); return; }
  m->row_count = parse_rows(text, m->rows, MAX_ROWS);
  TwGotoXYWindow(win, 1, 0); TwWriteCharsetWindow(win, 42, "Target / Unit                              State");
  for (i = 0; i < m->row_count; ++i) {
    char line[96];
    int y = 2 + i * 2;
    snprintf(line, sizeof(line), "%-40.40s %-14.14s", m->rows[i].target[0] ? m->rows[i].target : m->rows[i].detail, m->rows[i].status);
    TwGotoXYWindow(win, 1, y); TwWriteCharsetWindow(win, strlen(line), line);
    if (m->rows[i].target[0]) add_action_buttons(win, i, y, kid == 2);
    if (m->rows[i].detail[0]) {
      snprintf(line, sizeof(line), "  %.70s", m->rows[i].detail);
      TwGotoXYWindow(win, 1, y + 1); TwWriteCharsetWindow(win, strlen(line), line);
    }
  }
  free(text);
  TwFlush();
}

static void action_result(const char *mode) {
  char *q, args[1024], *text;
  twindow win;
  q = shell_quote(pending_target);
  if (!q) return;
  snprintf(args, sizeof(args), "action %s %s %s %s", pending_kind, pending_verb, q, mode);
  free(q);
  text = run_bridge(args);
  if (!text) return;
  win = make_window(!strcmp(mode, "apply") ? "Action Result" : "Action Preview", 78, 24, 180);
  if (win) {
    register_window(win, 0, 0, !strcmp(mode, "apply") ? "Action Result" : "Action Preview");
    write_lines_at(win, text, 74, 160, 0);
  }
  free(text);
  TwFlush();
}

static void confirm_action(ManagedWindow *m, int row, int op) {
  const char *verb = op == 1 ? "start" : op == 2 ? "stop" : op == 3 ? "restart" : op == 4 ? "enable" : "disable";
  char *q, args[1024], *preview;
  if (!m || row < 0 || row >= m->row_count) return;
  snprintf(pending_kind, sizeof(pending_kind), "%s", kind_name(m->kind));
  snprintf(pending_verb, sizeof(pending_verb), "%s", verb);
  snprintf(pending_target, sizeof(pending_target), "%s", m->rows[row].target);
  q = shell_quote(pending_target);
  if (!q) return;
  snprintf(args, sizeof(args), "action %s %s %s preview", pending_kind, pending_verb, q);
  free(q);
  preview = run_bridge(args);
  close_confirm();
  confirm_win = make_window("Confirm Xavi Action", 72, 22, 160);
  if (confirm_win) {
    char heading[512];
    snprintf(heading, sizeof(heading), "PREVIEW ONLY\n\n%s %s\nTarget: %s\n\n", pending_verb, pending_kind, pending_target);
    write_lines_at(confirm_win, heading, 68, 8, 0);
    if (preview) write_lines_at(confirm_win, preview, 68, 10, 7);
    TwCreateButtonGadget(confirm_win, 9, 1, "  APPLY  ", 0, CODE_CONFIRM_APPLY,
        TCOL(tblack,twhite), TCOL(twhite,tblue), TCOL((thigh|twhite),tblue), 18, 18);
    TwCreateButtonGadget(confirm_win, 10, 1, "  Cancel  ", 0, CODE_CONFIRM_CANCEL,
        TCOL(tblack,twhite), TCOL(twhite,tblue), TCOL((thigh|twhite),tblue), 38, 18);
  }
  free(preview);
  TwFlush();
}

static void properties_window(int app_code) {
  DesktopIcon *ic = icon_by_code(app_code);
  char text[512];
  twindow w;
  if (!ic) return;
  snprintf(text, sizeof(text),
      "%s\n\n%s\n\nDesktop position: %d, %d\nLeft-click: open/focus\nRight-click: context menu\nDrag: move icon\n",
      ic->label, ic->description, ic->x, ic->y);
  w = make_window("Desktop Item Properties", 54, 16, 40);
  if (w) {
    register_window(w, 0, 0, "Properties");
    write_lines_at(w, text, 50, 30, 0);
  }
  TwFlush();
}

static void handle_app_code(udat code) {
  switch (code) {
    case CODE_OVERVIEW: report_window("Xavi Overview", "overview", CODE_OVERVIEW); break;
    case CODE_CONTAINERS: list_window("Containers", "container", CODE_CONTAINERS); break;
    case CODE_SERVICES: list_window("Services", "service", CODE_SERVICES); break;
    case CODE_PROJECTS: list_window("Projects", "project", CODE_PROJECTS); break;
    case CODE_REMOTE: list_window("Remote Containers / Nodes", "remote-container", CODE_REMOTE); break;
    case CODE_STORAGE: report_window("Storage / Filesystems", "storage", CODE_STORAGE); break;
    case CODE_DOCTOR: report_window("Xavi Doctor", "doctor", CODE_DOCTOR); break;
    case CODE_RESOURCES: report_window("WG-RNN / Host Resources", "resources", CODE_RESOURCES); break;
    case CODE_ADVISOR: report_window("AI Advisor", "advisor", CODE_ADVISOR); break;
    case CODE_CONTRACT: report_window("Witness Contract", "contract", CODE_CONTRACT); break;
    case CODE_REFRESH: report_window("Fresh Xavi Overview", "overview", 0); break;
    case CODE_ARRANGE: arrange_icons(); break;
    case CODE_EXIT: exit(0);
  }
}

