static void handle_main_code(udat code) {
  if (code == 0 || code == CODE_EXIT) exit(0);
  if (code == CODE_START) { open_start_menu(); return; }
  if (code == CODE_TASKS) { open_tasks_menu(); return; }
  if (code >= CODE_TASK_BASE && code < CODE_CONFIRM_APPLY) {
    ManagedWindow *m = find_task_code(code);
    if (m) { TwRaiseWindow(m->win); TwFlush(); }
    return;
  }
  handle_app_code(code);
}

static void handle_icon_mouse(tevent_mouse mev) {
  int idx = icon_index_by_gadget(mev->W);
  DesktopIcon *ic;
  int nx, ny;
  if (idx < 0) return;
  ic = &icons[idx];
  if (mev->Code == PRESS_RIGHT) {
    drag_icon = -1;
    open_icon_context(ic->code);
    return;
  }
  if (mev->Code == PRESS_LEFT) {
    drag_icon = idx;
    drag_anchor_x = mev->X;
    drag_anchor_y = mev->Y;
    return;
  }
  if (drag_icon == idx && isMOVE(mev->Code) && (mev->Code & HOLD_LEFT)) {
    nx = ic->x + mev->X - drag_anchor_x;
    ny = ic->y + mev->Y - drag_anchor_y;
    if (nx < 1) nx = 1;
    if (ny < 2) ny = 2;
    if (nx > DESKTOP_W - ICON_W - 2) nx = DESKTOP_W - ICON_W - 2;
    if (ny > TASKBAR_Y - ICON_H - 1) ny = TASKBAR_Y - ICON_H - 1;
    ic->x = nx; ic->y = ny;
    TwSetXYGadget(ic->gadget, ic->x, ic->y);
    TwFlush();
    return;
  }
  if (drag_icon == idx && mev->Code == RELEASE_LEFT) {
    save_layout();
    drag_icon = -1;
    return;
  }
}

int main(void) {
  tmsg msg;
  tevent_any ev;
  uldat err;
  const char *home = getenv("HOME");
  snprintf(layout_path, sizeof(layout_path), "%s/.config/xavi-man/desktop.layout", home ? home : "/home/tbi");
  load_layout();

  if (!(TwCheckMagic(xavi_magic) && TwOpen(NULL) &&
        (msgport = TwCreateMsgPort(8, "xavi-man")))) goto fail;

  main_menu = TwCreateMenu(TCOL(tblack,twhite), TCOL(twhite,tblue),
                           TCOL((thigh|tblack),twhite), TCOL((thigh|tblack),tblack),
                           TCOL(tred,twhite), TCOL(tred,tblue), (byte)0);
  build_main();
  if (!main_win) goto fail;

  while ((msg = TwReadMsg(ttrue))) {
    ev = &msg->Event;

    /* Confirmation is modal: other gadget actions wait until Apply/Cancel. */
    if (confirm_win && msg->Type == TW_MSG_WIDGET_GADGET && ev->EventGadget.W != confirm_win) continue;

    if (msg->Type == TW_MSG_WIDGET_MOUSE) {
      int idx = icon_index_by_gadget(ev->EventMouse.W);
      if (idx >= 0) { handle_icon_mouse(&ev->EventMouse); continue; }
      if (ev->EventMouse.W == main_win && ev->EventMouse.Code == PRESS_RIGHT) {
        open_desktop_context();
        continue;
      }
      continue;
    }

    if (msg->Type != TW_MSG_WIDGET_GADGET) continue;

    if (confirm_win && ev->EventGadget.W == confirm_win) {
      if (ev->EventGadget.Code == 0 || ev->EventGadget.Code == CODE_CONFIRM_CANCEL) close_confirm();
      else if (ev->EventGadget.Code == CODE_CONFIRM_APPLY) {
        close_confirm();
        action_result("apply");
      }
      continue;
    }

    if (start_win && ev->EventGadget.W == start_win) {
      udat code = ev->EventGadget.Code;
      close_aux(&start_win);
      if (code == CODE_TASKS) open_tasks_menu();
      else handle_main_code(code);
      continue;
    }

    if (tasks_win && ev->EventGadget.W == tasks_win) {
      udat code = ev->EventGadget.Code;
      if (code == 0) close_aux(&tasks_win);
      else {
        ManagedWindow *m = find_task_code(code);
        if (m) { close_aux(&tasks_win); TwRaiseWindow(m->win); TwFlush(); }
      }
      continue;
    }

    if (context_win && ev->EventGadget.W == context_win) {
      udat code = ev->EventGadget.Code;
      int app = context_app_code;
      close_aux(&context_win);
      if (code == CODE_CTX_CANCEL || code == 0) continue;
      if (code == CODE_CTX_OPEN) handle_app_code(app);
      else if (code == CODE_CTX_PROPERTIES) properties_window(app);
      else if (code == CODE_CTX_SNAP) snap_icon(app);
      else if (code == CODE_DESKTOP_START) open_start_menu();
      else if (code == CODE_DESKTOP_REFRESH) handle_app_code(CODE_REFRESH);
      else if (code == CODE_DESKTOP_ARRANGE) arrange_icons();
      continue;
    }

    if (ev->EventGadget.W == main_win) {
      handle_main_code(ev->EventGadget.Code);
      continue;
    }

    if (ev->EventGadget.Code >= CODE_TASK_BASE && ev->EventGadget.Code < CODE_CONFIRM_APPLY) {
      ManagedWindow *m = find_task_code(ev->EventGadget.Code);
      if (m) { TwRaiseWindow(m->win); TwFlush(); }
      continue;
    }

    {
      ManagedWindow *m = find_window(ev->EventGadget.W);
      if (!m) continue;
      if (ev->EventGadget.Code == 0) {
        twindow old = m->win;
        forget_window(old);
        TwDeleteWindow(old);
        TwFlush();
      } else if (ev->EventGadget.Code >= CODE_ACTION_BASE && ev->EventGadget.Code < CODE_TASK_BASE) {
        int v = ev->EventGadget.Code - CODE_ACTION_BASE;
        int row = v / 10;
        int op = v % 10;
        if (op >= 1 && op <= 5) confirm_action(m, row, op);
      }
    }
  }

fail:
  err = TwErrno;
  if (err) fprintf(stderr, "xavi-man-twin: libtw error: %s%s\n", TwStrError(err), TwStrErrorDetail(err, TwErrnoDetail));
  if (!TwInPanic()) TwClose();
  return 1;
}
