<?php
namespace Xavi\FusionOS;

defined('C5_EXECUTE') or die('Access Denied.');

use Concrete\Core\User\User;

class ChatService
{
    private $db;

    public function __construct()
    {
        $this->db = app('database')->connection();
        $this->ensureSchema();
    }

    public function ensureSchema(): void
    {
        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionChatConversations (
            conversationID BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
            kind VARCHAR(16) NOT NULL,
            title VARCHAR(190) NOT NULL DEFAULT '',
            directKey VARCHAR(190) NULL,
            createdByUID INT UNSIGNED NOT NULL,
            createdByName VARCHAR(190) NOT NULL,
            createdAt DATETIME NOT NULL,
            updatedAt DATETIME NOT NULL,
            lastMessageID BIGINT UNSIGNED NULL,
            PRIMARY KEY (conversationID),
            UNIQUE KEY xaviFusionChatDirect (directKey),
            KEY xaviFusionChatUpdated (updatedAt)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionChatParticipants (
            conversationID BIGINT UNSIGNED NOT NULL,
            uID INT UNSIGNED NOT NULL,
            uName VARCHAR(190) NOT NULL,
            displayName VARCHAR(190) NOT NULL DEFAULT '',
            role VARCHAR(16) NOT NULL DEFAULT 'member',
            joinedAt DATETIME NOT NULL,
            lastReadMessageID BIGINT UNSIGNED NOT NULL DEFAULT 0,
            archived TINYINT(1) NOT NULL DEFAULT 0,
            PRIMARY KEY (conversationID, uID),
            KEY xaviFusionChatParticipantUser (uID, archived)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionChatMessages (
            messageID BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
            conversationID BIGINT UNSIGNED NOT NULL,
            senderUID INT UNSIGNED NOT NULL,
            senderName VARCHAR(190) NOT NULL,
            body TEXT NOT NULL,
            kind VARCHAR(16) NOT NULL DEFAULT 'text',
            replyToMessageID BIGINT UNSIGNED NULL,
            attachmentJson LONGTEXT NOT NULL,
            createdAt DATETIME NOT NULL,
            editedAt DATETIME NULL,
            deletedAt DATETIME NULL,
            PRIMARY KEY (messageID),
            KEY xaviFusionChatMessageConversation (conversationID, messageID),
            KEY xaviFusionChatMessageSender (senderUID, createdAt)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionChatReactions (
            messageID BIGINT UNSIGNED NOT NULL,
            uID INT UNSIGNED NOT NULL,
            emoji VARCHAR(32) NOT NULL,
            createdAt DATETIME NOT NULL,
            PRIMARY KEY (messageID, uID, emoji)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionChatSettings (
            uID INT UNSIGNED NOT NULL,
            uName VARCHAR(190) NOT NULL,
            availability VARCHAR(16) NOT NULL DEFAULT 'online',
            allowDirectMessages TINYINT(1) NOT NULL DEFAULT 1,
            readReceipts TINYINT(1) NOT NULL DEFAULT 1,
            soundEnabled TINYINT(1) NOT NULL DEFAULT 1,
            footerEnabled TINYINT(1) NOT NULL DEFAULT 1,
            chatHeadsEnabled TINYINT(1) NOT NULL DEFAULT 1,
            compactMode TINYINT(1) NOT NULL DEFAULT 0,
            lastSeenAt DATETIME NOT NULL,
            updatedAt DATETIME NOT NULL,
            PRIMARY KEY (uID)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    }

    public function bootstrap(User $user): array
    {
        return [
            'user' => ['id' => (string) $user->getUserID(), 'username' => $user->getUserName(), 'email' => null, 'is_admin' => $user->isSuperUser()],
            'settings' => $this->settings($user),
            'conversations' => $this->conversations($user),
            'online' => [],
            'socket' => ['url' => '/api/v1/chat/ws', 'protocol' => 'xavi-chat-v1', 'available' => false],
        ];
    }

    public function conversations(User $user): array
    {
        $ids = $this->db->fetchFirstColumn(
            'SELECT c.conversationID FROM XaviFusionChatConversations c JOIN XaviFusionChatParticipants p ON p.conversationID=c.conversationID WHERE p.uID=? AND p.archived=0 ORDER BY c.updatedAt DESC',
            [(int) $user->getUserID()]
        );
        return array_map(fn($id) => $this->conversation((int) $id, $user), $ids);
    }

    public function createDirect(User $user, array $payload): array
    {
        $targetID = (int) ($payload['user_id'] ?? 0);
        if ($targetID < 1 || $targetID === (int) $user->getUserID()) {
            throw new \InvalidArgumentException(t('Choose another active user.'));
        }
        $target = $this->db->fetchAssociative('SELECT uID,uName FROM Users WHERE uID=? AND uIsActive=1', [$targetID]);
        if (!$target) throw new \RuntimeException(t('The selected user is unavailable.'));
        $directKey = implode(':', array_map('strval', array_sort([(int)$user->getUserID(), $targetID])));
        $id = (int) $this->db->fetchOne('SELECT conversationID FROM XaviFusionChatConversations WHERE directKey=?', [$directKey]);
        $now = gmdate('Y-m-d H:i:s');
        if (!$id) {
            $this->db->insert('XaviFusionChatConversations', ['kind'=>'direct','title'=>'','directKey'=>$directKey,'createdByUID'=>(int)$user->getUserID(),'createdByName'=>$user->getUserName(),'createdAt'=>$now,'updatedAt'=>$now,'lastMessageID'=>null]);
            $id = (int) $this->db->lastInsertId();
        }
        $this->upsertParticipant($id, (int)$user->getUserID(), $user->getUserName(), 'owner');
        $this->upsertParticipant($id, $targetID, (string)$target['uName'], 'member');
        return $this->conversation($id, $user);
    }

    public function createGroup(User $user, array $payload): array
    {
        $title = mb_substr(trim((string)($payload['title'] ?? '')), 0, 190);
        if ($title === '') throw new \InvalidArgumentException(t('Enter a group name.'));
        $now = gmdate('Y-m-d H:i:s');
        $this->db->insert('XaviFusionChatConversations', ['kind'=>'group','title'=>$title,'directKey'=>null,'createdByUID'=>(int)$user->getUserID(),'createdByName'=>$user->getUserName(),'createdAt'=>$now,'updatedAt'=>$now,'lastMessageID'=>null]);
        $id = (int) $this->db->lastInsertId();
        $this->upsertParticipant($id, (int)$user->getUserID(), $user->getUserName(), 'owner');
        $seen = [(int)$user->getUserID() => true];
        foreach ((array)($payload['participants'] ?? []) as $person) {
            $uid = (int)($person['user_id'] ?? 0);
            if ($uid < 1 || isset($seen[$uid])) continue;
            $row = $this->db->fetchAssociative('SELECT uID,uName FROM Users WHERE uID=? AND uIsActive=1', [$uid]);
            if ($row) {$this->upsertParticipant($id, $uid, (string)$row['uName'], 'member');$seen[$uid]=true;}
        }
        if (count($seen) < 2) throw new \InvalidArgumentException(t('A group requires at least one other member.'));
        return $this->conversation($id, $user);
    }

    public function messages(User $user, int $conversationID, int $limit = 100): array
    {
        $this->requireParticipant($conversationID, $user);
        $ids = $this->db->fetchFirstColumn('SELECT messageID FROM XaviFusionChatMessages WHERE conversationID=? ORDER BY messageID DESC LIMIT ' . max(1,min(200,$limit)), [$conversationID]);
        return array_map(fn($id) => $this->message((int)$id), array_reverse($ids));
    }

    public function send(User $user, int $conversationID, array $payload): array
    {
        $this->requireParticipant($conversationID, $user);
        $body = mb_substr(trim((string)($payload['body'] ?? '')), 0, 32000);
        $attachment = is_array($payload['attachment'] ?? null) ? $payload['attachment'] : [];
        if ($body === '' && !$attachment) throw new \InvalidArgumentException(t('Enter a message.'));
        $now = gmdate('Y-m-d H:i:s');
        $this->db->insert('XaviFusionChatMessages', ['conversationID'=>$conversationID,'senderUID'=>(int)$user->getUserID(),'senderName'=>$user->getUserName(),'body'=>$body,'kind'=>in_array(($payload['kind']??'text'),['text','image','file'],true)?$payload['kind']:'text','replyToMessageID'=>!empty($payload['reply_to_message_id'])?(int)$payload['reply_to_message_id']:null,'attachmentJson'=>json_encode($attachment,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),'createdAt'=>$now,'editedAt'=>null,'deletedAt'=>null]);
        $id = (int) $this->db->lastInsertId();
        $this->db->update('XaviFusionChatConversations', ['lastMessageID'=>$id,'updatedAt'=>$now], ['conversationID'=>$conversationID]);
        $this->db->update('XaviFusionChatParticipants', ['lastReadMessageID'=>$id], ['conversationID'=>$conversationID,'uID'=>(int)$user->getUserID()]);
        return $this->message($id);
    }

    public function markRead(User $user, int $conversationID): array
    {
        $this->requireParticipant($conversationID, $user);
        $id = (int) $this->db->fetchOne('SELECT COALESCE(MAX(messageID),0) FROM XaviFusionChatMessages WHERE conversationID=?', [$conversationID]);
        $this->db->update('XaviFusionChatParticipants', ['lastReadMessageID'=>$id], ['conversationID'=>$conversationID,'uID'=>(int)$user->getUserID()]);
        return ['read'=>true,'message_id'=>$id];
    }

    public function deleteMessage(User $user, int $messageID): void
    {
        $row = $this->db->fetchAssociative('SELECT conversationID,senderUID FROM XaviFusionChatMessages WHERE messageID=? AND deletedAt IS NULL', [$messageID]);
        if (!$row) throw new \RuntimeException(t('Message not found.'));
        $participant = $this->requireParticipant((int)$row['conversationID'], $user);
        if ((int)$row['senderUID'] !== (int)$user->getUserID() && !in_array($participant['role'], ['owner','admin'], true) && !$user->isSuperUser()) throw new \RuntimeException(t('Message deletion is not permitted.'));
        $this->db->update('XaviFusionChatMessages', ['body'=>'','attachmentJson'=>'{}','deletedAt'=>gmdate('Y-m-d H:i:s')], ['messageID'=>$messageID]);
    }

    public function reaction(User $user, int $messageID, array $payload): array
    {
        $row = $this->db->fetchAssociative('SELECT conversationID FROM XaviFusionChatMessages WHERE messageID=?', [$messageID]);
        if (!$row) throw new \RuntimeException(t('Message not found.'));
        $this->requireParticipant((int)$row['conversationID'], $user);
        $emoji = mb_substr(trim((string)($payload['emoji'] ?? '')),0,32);
        if ($emoji === '') throw new \InvalidArgumentException(t('Choose a reaction.'));
        if (!empty($payload['active'])) $this->db->executeStatement('INSERT IGNORE INTO XaviFusionChatReactions (messageID,uID,emoji,createdAt) VALUES (?,?,?,?)', [$messageID,(int)$user->getUserID(),$emoji,gmdate('Y-m-d H:i:s')]);
        else $this->db->delete('XaviFusionChatReactions', ['messageID'=>$messageID,'uID'=>(int)$user->getUserID(),'emoji'=>$emoji]);
        return $this->message($messageID);
    }

    public function settings(User $user, ?array $patch = null): array
    {
        $uid = (int) $user->getUserID();$now=gmdate('Y-m-d H:i:s');
        if (!(int)$this->db->fetchOne('SELECT COUNT(*) FROM XaviFusionChatSettings WHERE uID=?',[$uid])) $this->db->insert('XaviFusionChatSettings',['uID'=>$uid,'uName'=>$user->getUserName(),'availability'=>'online','allowDirectMessages'=>1,'readReceipts'=>1,'soundEnabled'=>1,'footerEnabled'=>1,'chatHeadsEnabled'=>1,'compactMode'=>0,'lastSeenAt'=>$now,'updatedAt'=>$now]);
        if ($patch !== null) {
            $map=['availability'=>'availability','allow_direct_messages'=>'allowDirectMessages','read_receipts'=>'readReceipts','sound_enabled'=>'soundEnabled','footer_enabled'=>'footerEnabled','chat_heads_enabled'=>'chatHeadsEnabled','compact_mode'=>'compactMode'];$data=['updatedAt'=>$now,'uName'=>$user->getUserName()];
            foreach ($map as $input=>$column) if (array_key_exists($input,$patch)) $data[$column]=$input==='availability'&&in_array($patch[$input],['online','away','busy','offline'],true)?$patch[$input]:($input==='availability'?'online':(!empty($patch[$input])?1:0));
            $this->db->update('XaviFusionChatSettings',$data,['uID'=>$uid]);
        }
        $row=$this->db->fetchAssociative('SELECT * FROM XaviFusionChatSettings WHERE uID=?',[$uid]);
        return ['user_id'=>(string)$uid,'username'=>$row['uName'],'availability'=>$row['availability'],'allow_direct_messages'=>(bool)$row['allowDirectMessages'],'read_receipts'=>(bool)$row['readReceipts'],'sound_enabled'=>(bool)$row['soundEnabled'],'footer_enabled'=>(bool)$row['footerEnabled'],'chat_heads_enabled'=>(bool)$row['chatHeadsEnabled'],'compact_mode'=>(bool)$row['compactMode'],'last_seen_at'=>$row['lastSeenAt'],'updated_at'=>$row['updatedAt']];
    }

    private function conversation(int $id, User $user): array
    {
        $row=$this->db->fetchAssociative('SELECT c.*,p.role,p.lastReadMessageID,p.archived FROM XaviFusionChatConversations c JOIN XaviFusionChatParticipants p ON p.conversationID=c.conversationID AND p.uID=? WHERE c.conversationID=?',[(int)$user->getUserID(),$id]);
        if(!$row)throw new \RuntimeException(t('Conversation not found.'));
        $participants=$this->db->fetchAllAssociative('SELECT uID,uName,displayName,role,joinedAt,lastReadMessageID FROM XaviFusionChatParticipants WHERE conversationID=? ORDER BY joinedAt',[$id]);
        $unread=(int)$this->db->fetchOne('SELECT COUNT(*) FROM XaviFusionChatMessages WHERE conversationID=? AND messageID>? AND senderUID<>? AND deletedAt IS NULL',[$id,(int)$row['lastReadMessageID'],(int)$user->getUserID()]);
        return ['id'=>(string)$id,'kind'=>$row['kind'],'title'=>$row['title'],'created_by_id'=>(string)$row['createdByUID'],'created_by_username'=>$row['createdByName'],'created_at'=>$row['createdAt'],'updated_at'=>$row['updatedAt'],'last_message_id'=>$row['lastMessageID']?(int)$row['lastMessageID']:null,'role'=>$row['role'],'last_read_message_id'=>(int)$row['lastReadMessageID'],'archived'=>(bool)$row['archived'],'participants'=>array_map(fn($p)=>['user_id'=>(string)$p['uID'],'username'=>$p['uName'],'display_name'=>$p['displayName'],'role'=>$p['role'],'joined_at'=>$p['joinedAt'],'last_read_message_id'=>(int)$p['lastReadMessageID']],$participants),'last_message'=>$row['lastMessageID']?$this->message((int)$row['lastMessageID']):null,'unread_count'=>$unread];
    }

    private function message(int $id): array
    {
        $row=$this->db->fetchAssociative('SELECT * FROM XaviFusionChatMessages WHERE messageID=?',[$id]);if(!$row)throw new \RuntimeException(t('Message not found.'));
        $reactions=$this->db->fetchAllAssociative('SELECT emoji,uID FROM XaviFusionChatReactions WHERE messageID=? ORDER BY createdAt',[$id]);
        return ['id'=>(int)$row['messageID'],'conversation_id'=>(string)$row['conversationID'],'sender_id'=>(string)$row['senderUID'],'sender_username'=>$row['senderName'],'body'=>$row['deletedAt']?'':$row['body'],'kind'=>$row['kind'],'reply_to_message_id'=>$row['replyToMessageID']?(int)$row['replyToMessageID']:null,'attachment'=>$row['deletedAt']?[]:(json_decode($row['attachmentJson'],true)?:[]),'created_at'=>$row['createdAt'],'edited_at'=>$row['editedAt'],'deleted_at'=>$row['deletedAt'],'reactions'=>array_map(fn($r)=>['emoji'=>$r['emoji'],'user_id'=>(string)$r['uID']],$reactions)];
    }

    private function requireParticipant(int $conversationID, User $user): array
    {
        $row=$this->db->fetchAssociative('SELECT * FROM XaviFusionChatParticipants WHERE conversationID=? AND uID=?',[$conversationID,(int)$user->getUserID()]);if(!$row)throw new \RuntimeException(t('Conversation membership is required.'));return $row;
    }

    private function upsertParticipant(int $conversationID,int $uid,string $name,string $role): void
    {
        $exists=(int)$this->db->fetchOne('SELECT COUNT(*) FROM XaviFusionChatParticipants WHERE conversationID=? AND uID=?',[$conversationID,$uid]);$data=['uName'=>$name,'displayName'=>$name,'role'=>$role];
        if($exists)$this->db->update('XaviFusionChatParticipants',$data,['conversationID'=>$conversationID,'uID'=>$uid]);else$this->db->insert('XaviFusionChatParticipants',$data+['conversationID'=>$conversationID,'uID'=>$uid,'joinedAt'=>gmdate('Y-m-d H:i:s'),'lastReadMessageID'=>0,'archived'=>0]);
    }
}
