class MessengerClient extends EventTarget{
 constructor(){super();this.config=null;this.token=null;this.tokenExpires=0;this.user=null;this.settings={};this.conversations=[];this.messages=new Map();this.directory=[];this.online=new Map();this.typing=new Map();this.socket=null;this.socketState='offline';this.activeConversation='';this.pollTimer=0;this.reconnectTimer=0;this.reconnectAttempts=0;this.initPromise=null;this.channel='BroadcastChannel' in window?new BroadcastChannel('xavi-messenger'):null;this.channel?.addEventListener('message',e=>this.onBroadcast(e.data));}
 get unread(){return this.conversations.reduce((n,c)=>n+Number(c.unread_count||0),0)}
 emit(type='change',detail={}){this.dispatchEvent(new CustomEvent(type,{detail}));if(type==='change')window.dispatchEvent(new CustomEvent('xavi:messenger-change',{detail:{unread:this.unread,...detail}}));}
 async init(){if(this.initPromise)return this.initPromise;this.initPromise=this.bootstrap().catch(error=>{this.emit('error',{error});throw error});return this.initPromise;}
 async bootstrap(){const response=await fetch('/xavi-fusion/api/chat/config',{credentials:'same-origin',headers:{Accept:'application/json'}});if(response.status===401||response.status===403){this.config={enabled:false};this.emit();return this;}if(!response.ok)throw new Error(`Messenger configuration failed (${response.status})`);this.config=await response.json();if(!this.config.enabled){this.emit();return this;}await this.ensureToken();const payload=await this.api('/bootstrap');this.user=payload.user;this.settings=payload.settings||{};this.conversations=payload.conversations||[];(payload.online||[]).forEach(x=>this.online.set(String(x.user_id),x));this.emit();if(this.config.websocketEnabled)this.connectSocket();this.startPolling();return this;}
 async ensureToken(force=false){const now=Math.floor(Date.now()/1000);if(!force&&this.token&&this.tokenExpires>now+60)return this.token;const response=await fetch(this.config?.tokenUrl||'/xavi-fusion/api/token',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});if(!response.ok){const text=await response.text();throw new Error(`Messenger authentication failed (${response.status}) ${text.slice(0,120)}`);}const payload=await response.json();this.token=payload.access_token;this.tokenExpires=Number(payload.expires_at||now+Number(payload.expires_in||300));return this.token;}
 async api(path,options={},retry=true){await this.ensureToken();const headers=new Headers(options.headers||{});headers.set('Accept','application/json');headers.set('Authorization',`Bearer ${this.token}`);if(options.body&&!(options.body instanceof FormData))headers.set('Content-Type','application/json');const response=await fetch(`${this.config?.apiBase||'/api/v1/chat'}${path}`,{...options,headers,credentials:'same-origin'});if(response.status===401&&retry){await this.ensureToken(true);return this.api(path,options,false);}if(!response.ok){let message=`Messenger request failed (${response.status})`;try{const payload=await response.json();message=payload.detail||payload.error||message;}catch{}throw new Error(message);}if(response.status===204)return null;return response.json();}
 socketUrl(){const scheme=location.protocol==='https:'?'wss:':'ws:';return `${scheme}//${location.host}${this.config.websocketPath||'/api/v1/chat/ws'}`;}
 async connectSocket(){clearTimeout(this.reconnectTimer);if(!this.config?.enabled||!this.config.websocketEnabled)return;await this.ensureToken();if(this.socket&&[WebSocket.OPEN,WebSocket.CONNECTING].includes(this.socket.readyState))return;this.socketState='connecting';this.emit();try{const socket=new WebSocket(this.socketUrl(),['xavi-chat-v1',this.token]);this.socket=socket;socket.onopen=()=>{this.socketState='online';this.reconnectAttempts=0;this.emit();socket.send(JSON.stringify({type:'ping'}));};socket.onmessage=e=>{try{this.onEvent(JSON.parse(e.data));}catch{}};socket.onerror=()=>{this.socketState='error';this.emit();};socket.onclose=()=>{if(this.socket===socket)this.socket=null;this.socketState='offline';this.emit();this.scheduleReconnect();};}catch(error){this.socketState='error';this.emit('error',{error});this.scheduleReconnect();}}
 scheduleReconnect(){clearTimeout(this.reconnectTimer);if(!this.config?.websocketEnabled)return;const delay=Math.min(30000,1000*2**Math.min(5,this.reconnectAttempts++));this.reconnectTimer=setTimeout(()=>this.connectSocket(),delay);}
 startPolling(){clearInterval(this.pollTimer);const seconds=Math.max(5,Number(this.config?.pollSeconds||15));this.pollTimer=setInterval(()=>this.refreshConversations().catch(()=>{}),seconds*1000);}
 async refreshConversations(){if(!this.config?.enabled)return;const items=await this.api('/conversations');this.conversations=items;this.emit();}
 async loadMessages(conversationId,force=false){const id=String(conversationId);if(!force&&this.messages.has(id))return this.messages.get(id);const rows=await this.api(`/conversations/${encodeURIComponent(id)}/messages?limit=100`);this.messages.set(id,rows);this.activeConversation=id;await this.markRead(id);this.emit();return rows;}
 async markRead(id){const result=await this.api(`/conversations/${encodeURIComponent(id)}/read`,{method:'POST'});const conversation=this.conversations.find(x=>String(x.id)===String(id));if(conversation){conversation.unread_count=0;conversation.last_read_message_id=result.message_id;}this.broadcast({type:'read',conversationId:String(id)});this.emit();}
 async send(id,body,extra={}){const text=String(body||'').trim();if(!text&&!extra.attachment)return;const message=await this.api(`/conversations/${encodeURIComponent(id)}/messages`,{method:'POST',body:JSON.stringify({body:text,kind:extra.kind||'text',reply_to_message_id:extra.replyTo||null,attachment:extra.attachment||{}})});this.upsertMessage(String(id),message);this.emit();return message;}
 async createDirect(person){const conversation=await this.api('/direct',{method:'POST',body:JSON.stringify({user_id:String(person.id),username:person.username,display_name:person.displayName||person.username})});this.upsertConversation(conversation);await this.loadMessages(conversation.id,true);this.broadcast({type:'conversation',conversation});return conversation;}
 async createGroup(title,participants){const conversation=await this.api('/groups',{method:'POST',body:JSON.stringify({title,participants:participants.map(p=>({user_id:String(p.id),username:p.username,display_name:p.displayName||p.username}))})});this.upsertConversation(conversation);await this.loadMessages(conversation.id,true);this.broadcast({type:'conversation',conversation});return conversation;}
 async searchDirectory(query=''){const response=await fetch(`${this.config.directoryUrl}?q=${encodeURIComponent(query)}&limit=80`,{credentials:'same-origin',headers:{Accept:'application/json'}});if(!response.ok)throw new Error(`Member directory failed (${response.status})`);this.directory=(await response.json()).items||[];this.emit();return this.directory;}
 async react(messageId,emoji,active=true){const message=await this.api(`/messages/${messageId}/reaction`,{method:'POST',body:JSON.stringify({emoji,active})});this.upsertMessage(String(message.conversation_id),message);this.emit();}
 async updateSettings(patch){this.settings=await this.api('/settings',{method:'PATCH',body:JSON.stringify(patch)});this.emit();return this.settings;}
 typingEvent(id,active){if(this.socket?.readyState===WebSocket.OPEN)this.socket.send(JSON.stringify({type:'typing',conversation_id:String(id),active:Boolean(active)}));}
 onEvent(event){const type=event?.type;if(type==='socket.ready'){this.socketState='online';(event.online||[]).forEach(x=>this.online.set(String(x.user_id),x));}else if(type==='presence'&&event.user)this.online.set(String(event.user.user_id),event.user);else if(type==='typing'){const key=String(event.conversation_id);const map=this.typing.get(key)||new Map();event.active?map.set(String(event.user_id),event.username):map.delete(String(event.user_id));this.typing.set(key,map);}else if(type==='message.created'&&event.message){this.upsertMessage(String(event.conversation_id),event.message);if(String(event.conversation_id)!==String(this.activeConversation)||document.hidden){const c=this.conversations.find(x=>String(x.id)===String(event.conversation_id));if(c&&String(event.message.sender_id)!==String(this.user?.id))c.unread_count=Number(c.unread_count||0)+1;this.notify(event.message,c);}else this.markRead(event.conversation_id).catch(()=>{});this.refreshConversations().catch(()=>{});}else if(type==='message.updated'&&event.message)this.upsertMessage(String(event.conversation_id),event.message);else if(type==='message.deleted'){const rows=this.messages.get(String(event.conversation_id))||[];const row=rows.find(x=>Number(x.id)===Number(event.message_id));if(row){row.body='';row.deleted_at=new Date().toISOString();}}else if(type==='conversation.created')this.refreshConversations().catch(()=>{});else if(type==='conversation.read'){const c=this.conversations.find(x=>String(x.id)===String(event.conversation_id));const p=c?.participants?.find(x=>String(x.user_id)===String(event.user_id));if(p)p.last_read_message_id=event.message_id;}this.broadcast({type:'event',event});this.emit();}
 onBroadcast(message){if(!message||message.source===this.instanceId)return;if(message.type==='event')this.onEvent({...message.event,_broadcast:true});if(message.type==='conversation')this.upsertConversation(message.conversation);if(message.type==='read'){const c=this.conversations.find(x=>String(x.id)===message.conversationId);if(c)c.unread_count=0;}this.emit();}
 broadcast(payload){try{this.channel?.postMessage({...payload,source:this.instanceId})}catch{}}
 upsertConversation(conversation){const index=this.conversations.findIndex(x=>String(x.id)===String(conversation.id));index<0?this.conversations.unshift(conversation):this.conversations.splice(index,1,{...this.conversations[index],...conversation});}
 upsertMessage(id,message){const rows=this.messages.get(id)||[];const index=rows.findIndex(x=>Number(x.id)===Number(message.id));index<0?rows.push(message):rows.splice(index,1,message);rows.sort((a,b)=>Number(a.id)-Number(b.id));this.messages.set(id,rows);}
 conversationName(c){if(c.kind==='group')return c.title||'Group';const other=(c.participants||[]).find(x=>String(x.user_id)!==String(this.user?.id));return other?.display_name||other?.username||'Conversation';}
 notify(message,conversation){if(!this.settings.sound_enabled&&this.settings.sound_enabled!==undefined)return;this.emit('notification',{message,conversation});if('Notification' in window&&Notification.permission==='granted'&&document.hidden){new Notification(this.conversationName(conversation||{}),{body:message.body||'New message',tag:`xavi-chat-${message.conversation_id}`});}}
 open(conversationId=''){if(conversationId)this.activeConversation=String(conversationId);const opened=window.XaviFusionOS?.openProgram?.('messenger','primary');if(!opened){document.querySelector('xavi-messenger-dock')?.openPanel?.();}this.emit();}
}
MessengerClient.prototype.instanceId=crypto.randomUUID?.()||Math.random().toString(36).slice(2);
const client=window.XaviMessenger=window.XaviMessenger||new MessengerClient();

class MessengerView extends HTMLElement{
 constructor(){super();this.attachShadow({mode:'open'});this.tab='chats';this.selected='';this.search='';this.loading=false;this.error='';this._change=()=>this.render();}
