 thread(c,rows){const name=client.conversationName(c),typing=[...(client.typing.get(String(c.id))||new Map()).values()].filter(x=>x!==client.user?.username);return `<header class="thread-header"><span class="avatar">${esc(initials(name))}</span><div><h2>${esc(name)}</h2><small>${typing.length?`${esc(typing.join(', '))} typing…`:`${(c.participants||[]).length} participant${(c.participants||[]).length===1?'':'s'}`}</small></div><button data-thread-info>ⓘ</button></header><div class="messages" data-messages>${this.loading?'<p class="loading">Loading messages…</p>':rows.map(m=>this.message(m)).join('')||'<p class="blank">No messages yet. Say hello.</p>'}</div><form class="composer" data-composer><button type="button" data-emoji>☺</button><textarea name="body" rows="1" maxlength="${Number(client.config?.maxMessageLength||8000)}" placeholder="Message ${esc(name)}"></textarea><button type="submit" class="send">➤</button></form>`;}
 message(m){const mine=String(m.sender_id)===String(client.user?.id),deleted=Boolean(m.deleted_at),reactions=(m.reactions||[]).reduce((map,r)=>(map[r.emoji]=(map[r.emoji]||0)+1,map),{});return `<article class="message ${mine?'mine':''} ${deleted?'deleted':''}" data-message="${Number(m.id)}"><span class="message-avatar">${esc(initials(m.sender_username))}</span><div><small>${esc(m.sender_username)} · ${esc(fmt(m.created_at))}${m.edited_at?' · edited':''}</small><p>${deleted?'<em>Message removed</em>':esc(m.body)}</p>${Object.entries(reactions).length?`<div class="reactions">${Object.entries(reactions).map(([e,n])=>`<button data-reaction="${esc(e)}">${esc(e)} ${n}</button>`).join('')}</div>`:''}<div class="message-actions"><button data-add-reaction="👍">👍</button><button data-add-reaction="❤️">❤️</button>${mine&&!deleted?'<button data-delete>Delete</button>':''}</div></div></article>`;}
