# generic helpers before render
marker='
    render() {'
helper='''
    _activeRow() {
      const rows = this._rows || [];
      if (!rows.length) return null;
      return rows.find((row, idx) => this._rowKey(row, idx) === this._selected) || rows[0] || null;
    }

    async _copySelectedJson() {
      const row = this._activeRow();
      if (!row) return;
      try { await navigator.clipboard.writeText(this._json(row)); this._copyNote = 'Selected row copied.'; }
      catch (_) { this._copyNote = 'Selected row copy failed.'; }
      this.render();
    }

    _exportSelectedJson() {
      const row = this._activeRow();
      if (!row) return;
      const blob = new Blob([this._json(row)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `wgrnn-data-row-${Date.now()}.json`;
      a.click();
      URL.revokeObjectURL(url);
      this._copyNote = 'Selected row exported.';
      this.render();
    }

    _workspaceReadiness() {
      const rows = this._rows || [];
      const checks = [
        ['postgres rows', rows.length > 0],
        ['selected row', !!this._activeRow()],
        ['manager API', !!this._managerApi],
        ['no sqlite path', true],
      ];
      const score = checks.filter(([, ok]) => ok).length;
      const chips = checks.map(([k, ok]) => this._pill ? this._pill(`${ok ? '✓' : '·'} ${k}`, ok ? 'ok' : 'warn') : `<span class="pill ${ok ? 'ok' : 'warn'}">${this._esc(k)}</span>`).join('');
