import { create } from "zustand";
import api, { setAccessToken } from "../lib/api";
import { useSettingsStore } from "./settings";

interface User {
  id: string; email: string; username: string; rating: number; role?: string;
  tosAccepted?: boolean; avatarUrl?: string | null; darkMode?: boolean;
  boardTheme?: string; pieceSet?: string; soundEnabled?: boolean;
}
interface AuthState {
  user: User | null; isLoading: boolean;
  register: (email?: string, username?: string, password?: string, inviteCode?: string) => Promise<void>;
  login: (email?: string, password?: string) => Promise<void>;
  logout: () => Promise<void>; refresh: () => Promise<void>; fetchMe: () => Promise<void>;
}
class BrowserConcreteError extends Error { constructor(public readonly status: number) { super(`Concrete session check failed (${status})`); } }
function syncSettings(user: User) {
  if (user.darkMode !== undefined && user.boardTheme && user.pieceSet) {
    useSettingsStore.getState().loadFromUser({ darkMode: user.darkMode, soundEnabled: user.soundEnabled, boardTheme: user.boardTheme, pieceSet: user.pieceSet });
  }
}
function launchConcrete(next = "/chess/play") {
  if (typeof window !== "undefined") window.location.assign(`/api/jwt/chess?next=${encodeURIComponent(next)}`);
}
async function browserConcreteToken() {
  const response = await fetch("/api/jwt", { method: "GET", credentials: "include", cache: "no-store", headers: { Accept: "application/json" } });
  if (!response.ok) throw new BrowserConcreteError(response.status);
  const payload = await response.json() as { token?: unknown };
  const token = typeof payload.token === "string" ? payload.token : "";
  if (!token) throw new BrowserConcreteError(503);
  return token;
}
async function syncFromConcreteBrowser() {
  const token = await browserConcreteToken();
  return api.post("/api/v1/auth/concrete/session", { token });
}
let fetchMePromise: Promise<void> | null = null;
export const useAuthStore = create<AuthState>((set) => ({
  user: null, isLoading: true,
  register: async () => launchConcrete(),
  login: async () => launchConcrete(),
  logout: async () => {
    try { await api.post("/api/v1/auth/logout"); } catch { /* authoritative logout follows */ }
    setAccessToken(null); set({ user: null, isLoading: false });
    if (typeof window !== "undefined") window.location.assign("/api/jwt/logout?return=/chess/");
  },
  refresh: async () => {
    const { data } = await syncFromConcreteBrowser();
    setAccessToken(data.accessToken);
    if (data.user) { set({ user: data.user, isLoading: false }); syncSettings(data.user); }
  },
  fetchMe: async () => {
    if (fetchMePromise) return fetchMePromise;
    fetchMePromise = (async () => {
      try {
        const { data } = await syncFromConcreteBrowser();
        setAccessToken(data.accessToken); set({ user: data.user, isLoading: false }); syncSettings(data.user);
      } catch (err: unknown) {
        const status = err instanceof BrowserConcreteError ? err.status : (err as { response?: { status?: number } })?.response?.status;
        if (status === 400 || status === 401 || status === 403) { setAccessToken(null); set({ user: null, isLoading: false }); }
        else set({ isLoading: false });
      } finally { fetchMePromise = null; }
    })();
    return fetchMePromise;
  },
}));
