"use client";

import { useEffect } from "react";

const RETIRE_REVISION = "20260810-1049";

function isLegacyRegistration(registration: ServiceWorkerRegistration) {
  const scripts = [
    registration.active?.scriptURL,
    registration.waiting?.scriptURL,
    registration.installing?.scriptURL,
  ].filter((value): value is string => Boolean(value));

  return scripts.some((script) => {
    try {
      const pathname = new URL(script).pathname;
      return pathname === "/sw.js" || pathname === "/chess/chess-sw.js";
    } catch {
      return script.includes("/sw.js") || script.includes("/chess/chess-sw.js");
    }
  });
}

function waitForControllerChange(timeoutMs: number) {
  return new Promise<void>((resolve) => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      window.clearTimeout(timer);
      navigator.serviceWorker.removeEventListener("controllerchange", finish);
      resolve();
    };
    const timer = window.setTimeout(finish, timeoutMs);
    navigator.serviceWorker.addEventListener("controllerchange", finish);
  });
}

export default function ChessServiceWorker() {
  useEffect(() => {
    if (!("serviceWorker" in navigator)) return;

    void (async () => {
      try {
        let registrations = await navigator.serviceWorker.getRegistrations();
        const legacyRegistrations = registrations.filter(isLegacyRegistration);
        const hasRootLegacy = legacyRegistrations.some((registration) => {
          try {
            return new URL(registration.scope).pathname === "/";
          } catch {
            return registration.scope.endsWith("/");
          }
        });

        // A plain unregister leaves the currently controlling worker alive until
        // navigation. Force a cache-busted update at the same root scope first so
        // the no-op retirement shim replaces stale Workbox immediately, even when
        // /sw.js itself was previously cached for days.
        if (hasRootLegacy) {
          try {
            const controllerChanged = waitForControllerChange(5000);
            const retirement = await navigator.serviceWorker.register(
              `/sw.js?xavi-retire=${RETIRE_REVISION}`,
              { scope: "/", updateViaCache: "none" },
            );
            try {
              await retirement.update();
            } catch {
              // The initial cache-busted register is sufficient if update races activation.
            }
            await controllerChanged;
          } catch {
            // Fall through to unregister/cache cleanup below.
          }
        }

        registrations = await navigator.serviceWorker.getRegistrations();
        await Promise.all(
          registrations.filter(isLegacyRegistration).map((registration) => registration.unregister()),
        );

        if ("caches" in window) {
          const names = await caches.keys();
          await Promise.all(
            names
              .filter((name) => /workbox|precache|eyeonchess|chess|xavi-pwa|offline/i.test(name))
              .map((name) => caches.delete(name)),
          );
        }
      } catch {
        // Service-worker retirement is best-effort; Chess remains network-only.
      }
    })();
  }, []);

  return null;
}
TSX

