<?php
namespace Xavi\FusionOS;

defined('C5_EXECUTE') or die('Access Denied.');

use Concrete\Core\User\User;

class StartMenuService
{
    private $db;
    private const SIZES = ['small', 'medium', 'wide', 'large'];
    private const GRID_COLUMNS = 8;
    private const MAX_ROWS = 256;

    public function __construct()
    {
        $this->db = app('database')->connection();
        $this->ensureSchema();
    }

    public function ensureSchema(): void
    {
        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionStartMenuItems (
            uID INT UNSIGNED NOT NULL,
            appID VARCHAR(128) NOT NULL,
            startPinned TINYINT(1) NOT NULL DEFAULT 0,
            taskbarPinned TINYINT(1) NOT NULL DEFAULT 0,
            tileSize VARCHAR(16) NOT NULL DEFAULT 'medium',
            tileX INT NULL DEFAULT NULL,
            tileY INT NULL DEFAULT NULL,
            sortOrder INT NOT NULL DEFAULT 0,
            groupName VARCHAR(190) NOT NULL DEFAULT 'Pinned',
            updatedAt DATETIME NOT NULL,
            PRIMARY KEY (uID, appID),
            KEY xaviFusionStartUserOrder (uID, startPinned, groupName, sortOrder),
            KEY xaviFusionTaskbarUserOrder (uID, taskbarPinned, sortOrder)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $this->ensureColumn('tileX', 'INT NULL DEFAULT NULL');
        $this->ensureColumn('tileY', 'INT NULL DEFAULT NULL');
        $this->migrateLegacyRows();
    }

    public function layout(User $user): array
    {
        $this->registered($user);
        $rows = $this->db->fetchAllAssociative(
            'SELECT appID,startPinned,taskbarPinned,tileSize,tileX,tileY,sortOrder,groupName,updatedAt
             FROM XaviFusionStartMenuItems WHERE uID=? ORDER BY sortOrder,tileY,tileX,appID',
            [(int) $user->getUserID()]
        );
        return array_map(fn(array $row): array => $this->normalizeRow($row), $rows);
    }

    public function update(User $user, string $appID, array $patch): array
    {
        $this->registered($user);
        $appID = $this->appID($appID);
        $uID = (int) $user->getUserID();
        $existing = $this->db->fetchAssociative('SELECT * FROM XaviFusionStartMenuItems WHERE uID=? AND appID=?', [$uID, $appID]);
        $wasPinned = $existing ? !empty($existing['startPinned']) : false;
        $oldGroup = $existing ? (string)$existing['groupName'] : 'Pinned';
        $row = [
            'startPinned' => $existing ? (int)$existing['startPinned'] : 0,
            'taskbarPinned' => $existing ? (int)$existing['taskbarPinned'] : 0,
            'tileSize' => $this->size($existing['tileSize'] ?? 'medium'),
            'tileX' => $existing && $existing['tileX'] !== null ? (int)$existing['tileX'] : null,
            'tileY' => $existing && $existing['tileY'] !== null ? (int)$existing['tileY'] : null,
            'sortOrder' => $existing ? (int)$existing['sortOrder'] : $this->nextOrder($uID),
            'groupName' => $existing ? $this->group((string)$existing['groupName']) : 'Pinned',
            'updatedAt' => gmdate('Y-m-d H:i:s'),
        ];
        if (array_key_exists('startPinned', $patch)) $row['startPinned'] = filter_var($patch['startPinned'], FILTER_VALIDATE_BOOLEAN) ? 1 : 0;
        if (array_key_exists('taskbarPinned', $patch)) $row['taskbarPinned'] = filter_var($patch['taskbarPinned'], FILTER_VALIDATE_BOOLEAN) ? 1 : 0;
        if (array_key_exists('tileSize', $patch)) $row['tileSize'] = $this->size((string)$patch['tileSize']);
        if (array_key_exists('sortOrder', $patch)) $row['sortOrder'] = max(0, min(1000000, (int)$patch['sortOrder']));
        if (array_key_exists('groupName', $patch)) $row['groupName'] = $this->group((string)$patch['groupName']);
        if (array_key_exists('tileX', $patch)) $row['tileX'] = max(0, (int)$patch['tileX']);
        if (array_key_exists('tileY', $patch)) $row['tileY'] = max(0, (int)$patch['tileY']);

        $groupChanged = $row['groupName'] !== $oldGroup;
        if ($row['startPinned'] && (!$wasPinned || $row['tileX'] === null || $row['tileY'] === null || ($groupChanged && !array_key_exists('tileX', $patch)))) {
            [$row['tileX'], $row['tileY']] = $this->nextFreePosition($uID, $row['groupName'], $row['tileSize'], $appID);
        }
        [$width] = $this->dimensions($row['tileSize']);
        $row['tileX'] = min(max(0, (int)($row['tileX'] ?? 0)), self::GRID_COLUMNS - $width);
        $row['tileY'] = min(max(0, (int)($row['tileY'] ?? 0)), self::MAX_ROWS - 1);

        if ($existing) $this->db->update('XaviFusionStartMenuItems', $row, ['uID'=>$uID,'appID'=>$appID]);
        else $this->db->insert('XaviFusionStartMenuItems', $row + ['uID'=>$uID,'appID'=>$appID]);

        if ($row['startPinned']) $this->normalizeUserLayout($uID, $appID);
        return $this->item($user, $appID);
    }

    public function reorder(User $user, array $items): array
    {
        $this->registered($user);
        $uID = (int)$user->getUserID();
        $position = 10;
        $preferred = null;
        foreach (array_slice($items, 0, 500) as $item) {
            if (!is_array($item) || empty($item['appID'])) continue;
            $appID = $this->appID((string)$item['appID']);
            if ($preferred === null) $preferred = $appID;
            $existing = $this->db->fetchAssociative('SELECT * FROM XaviFusionStartMenuItems WHERE uID=? AND appID=?', [$uID,$appID]);
            $size = $this->size((string)($item['tileSize'] ?? ($existing['tileSize'] ?? 'medium')));
            [$width] = $this->dimensions($size);
            $data = [
                'startPinned' => array_key_exists('startPinned',$item) ? (!empty($item['startPinned'])?1:0) : ($existing ? (int)$existing['startPinned'] : 1),
                'taskbarPinned' => $existing ? (int)$existing['taskbarPinned'] : 0,
                'tileSize' => $size,
                'tileX' => min(max(0,(int)($item['tileX'] ?? ($existing['tileX'] ?? 0))), self::GRID_COLUMNS-$width),
                'tileY' => min(max(0,(int)($item['tileY'] ?? ($existing['tileY'] ?? 0))), self::MAX_ROWS-1),
                'sortOrder' => $position,
                'groupName' => $this->group((string)($item['groupName'] ?? ($existing['groupName'] ?? 'Pinned'))),
                'updatedAt' => gmdate('Y-m-d H:i:s'),
            ];
            if ($existing) $this->db->update('XaviFusionStartMenuItems',$data,['uID'=>$uID,'appID'=>$appID]);
            else $this->db->insert('XaviFusionStartMenuItems',$data+['uID'=>$uID,'appID'=>$appID]);
            $position += 10;
        }
        $this->normalizeUserLayout($uID, $preferred);
        return $this->layout($user);
    }

    public function reset(User $user, string $appID): void
    {
        $this->registered($user);
        $this->db->delete('XaviFusionStartMenuItems',['uID'=>(int)$user->getUserID(),'appID'=>$this->appID($appID)]);
    }

    public function item(User $user, string $appID): array
    {
        $this->registered($user);
        $row = $this->db->fetchAssociative(
            'SELECT appID,startPinned,taskbarPinned,tileSize,tileX,tileY,sortOrder,groupName,updatedAt
             FROM XaviFusionStartMenuItems WHERE uID=? AND appID=?',
            [(int)$user->getUserID(),$this->appID($appID)]
        );
        if (!$row) throw new \RuntimeException(t('Start menu item was not found.'));
        return $this->normalizeRow($row);
    }

    public function find(User $user, string $appID): ?array
    {
        try { return $this->item($user,$appID); } catch (\Throwable $ignored) { return null; }
    }

    private function normalizeUserLayout(int $uID, ?string $preferredAppID = null): void
    {
        $rows = $this->db->fetchAllAssociative(
            'SELECT * FROM XaviFusionStartMenuItems WHERE uID=? AND startPinned=1
             ORDER BY CASE WHEN appID=? THEN 0 ELSE 1 END, sortOrder,tileY,tileX,appID',
            [$uID,$preferredAppID ?? '']
        );
        $groups = [];
        foreach ($rows as $row) $groups[$this->group((string)$row['groupName'])][] = $row;
        foreach ($groups as $group => $groupRows) {
            $occupied = [];
            foreach ($groupRows as $row) {
                $size = $this->size((string)$row['tileSize']);
                [$width,$height] = $this->dimensions($size);
                $x = min(max(0,(int)$row['tileX']),self::GRID_COLUMNS-$width);
                $y = min(max(0,(int)$row['tileY']),self::MAX_ROWS-$height);
                if (!$this->isFree($occupied,$x,$y,$width,$height)) [$x,$y] = $this->findFree($occupied,$width,$height,$y);
                $this->occupy($occupied,$x,$y,$width,$height,(string)$row['appID']);
                $sort = ($y * self::GRID_COLUMNS + $x) * 10;
                if ($x !== (int)$row['tileX'] || $y !== (int)$row['tileY'] || $sort !== (int)$row['sortOrder'] || $group !== (string)$row['groupName']) {
                    $this->db->update('XaviFusionStartMenuItems',['tileX'=>$x,'tileY'=>$y,'sortOrder'=>$sort,'groupName'=>$group,'updatedAt'=>gmdate('Y-m-d H:i:s')],['uID'=>$uID,'appID'=>$row['appID']]);
                }
            }
        }
    }

    private function nextFreePosition(int $uID,string $group,string $size,?string $excludeAppID=null): array
    {
        $rows = $this->db->fetchAllAssociative('SELECT appID,tileSize,tileX,tileY FROM XaviFusionStartMenuItems WHERE uID=? AND startPinned=1 AND groupName=? ORDER BY tileY,tileX',[$uID,$group]);
        $occupied=[];
        foreach($rows as $row){
            if($excludeAppID!==null && (string)$row['appID']===$excludeAppID)continue;
            [$w,$h]=$this->dimensions($this->size((string)$row['tileSize']));
            $this->occupy($occupied,max(0,(int)$row['tileX']),max(0,(int)$row['tileY']),$w,$h,(string)$row['appID']);
        }
        [$w,$h]=$this->dimensions($size);
        return $this->findFree($occupied,$w,$h,0);
    }

    private function findFree(array $occupied,int $width,int $height,int $startY=0): array
    {
        $startY=max(0,min(self::MAX_ROWS-$height,$startY));
        for($pass=0;$pass<2;$pass++){
            $from=$pass===0?$startY:0;$to=$pass===0?self::MAX_ROWS-$height:$startY-1;
            for($y=$from;$y<=$to;$y++)for($x=0;$x<=self::GRID_COLUMNS-$width;$x++)if($this->isFree($occupied,$x,$y,$width,$height))return[$x,$y];
        }
        return [0,self::MAX_ROWS-$height];
    }

    private function isFree(array $occupied,int $x,int $y,int $width,int $height): bool
    {
        for($dy=0;$dy<$height;$dy++)for($dx=0;$dx<$width;$dx++)if(isset($occupied[($y+$dy).':'.($x+$dx)]))return false;
