import crypto from "crypto";
import { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { prisma } from "../lib/prisma.js";
import { logger } from "../lib/logger.js";
import { hashToken, signAccessToken } from "../lib/jwt.js";

const CONCRETE_COOKIE = process.env.CONCRETE_SESSION_COOKIE_NAME || "CONCRETE";
const CONCRETE_ISSUE_URL = process.env.CONCRETE_JWT_ISSUE_URL || "https://www.xavi.app/api/jwt";
const CONCRETE_VERIFY_URL = process.env.CONCRETE_JWT_VERIFY_URL || "https://www.xavi.app/api/jwt/verify";
const LEGACY_REFRESH_COOKIE = "refresh_token";
const AUTH_TIMEOUT_MS = Math.max(1000, Number(process.env.CONCRETE_AUTH_TIMEOUT_MS || 5000));

type ConcreteIdentity = { id: string; email: string; username: string };
type ChessUser = {
  id: string; email: string; username: string; rating: number; role: string;
  tosAccepted: boolean; avatarUrl: string | null; darkMode: boolean;
  boardTheme: string; pieceSet: string; soundEnabled: boolean;
};

class ConcreteAuthorityError extends Error {
  constructor(message: string, public readonly statusCode: number, public readonly authorityUnavailable = false) {
    super(message);
  }
}

async function fetchWithTimeout(url: string, init: RequestInit): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), AUTH_TIMEOUT_MS);
  try {
    return await fetch(url, { ...init, signal: controller.signal, redirect: "manual" });
  } catch (error) {
    throw new ConcreteAuthorityError(error instanceof Error ? error.message : "Concrete authentication unavailable", 503, true);
  } finally { clearTimeout(timer); }
}

async function issueConcreteToken(sessionCookie: string): Promise<string> {
  const response = await fetchWithTimeout(CONCRETE_ISSUE_URL, {
    method: "GET",
    headers: { Accept: "application/json", Cookie: `${CONCRETE_COOKIE}=${sessionCookie}`, "User-Agent": "Xavi-EyeOnChess-ConcreteSessionSync/1.0" },
  });
  if (response.status === 401 || response.status === 403) throw new ConcreteAuthorityError("Concrete session is not authenticated", 401);
  if (!response.ok) throw new ConcreteAuthorityError(`Concrete token issue failed (${response.status})`, 503, true);
  const payload = (await response.json()) as { token?: unknown };
  const token = typeof payload.token === "string" ? payload.token.trim() : "";
  if (!token) throw new ConcreteAuthorityError("Concrete returned no token", 503, true);
  return token;
}

async function verifyConcreteToken(token: string): Promise<ConcreteIdentity> {
  const response = await fetchWithTimeout(CONCRETE_VERIFY_URL, {
    method: "POST", headers: { Accept: "application/json", "Content-Type": "application/json" }, body: JSON.stringify({ token }),
  });
  if ([400, 401, 403].includes(response.status)) throw new ConcreteAuthorityError("Concrete token is invalid", 401);
  if (!response.ok) throw new ConcreteAuthorityError(`Concrete token verification failed (${response.status})`, 503, true);
  const payload = (await response.json()) as { valid?: boolean; user?: { id?: unknown; email?: unknown; username?: unknown } };
  const id = String(payload.user?.id ?? "").trim();
  const username = String(payload.user?.username ?? "").trim();
  const email = String(payload.user?.email ?? "").trim().toLowerCase();
  if (!payload.valid || !id || !username) throw new ConcreteAuthorityError("Concrete identity is incomplete", 401);
  return { id, username, email };
}

function presentUser(user: ChessUser) {
  return { id: user.id, email: user.email, username: user.username, rating: user.rating, role: user.role,
    tosAccepted: user.tosAccepted, avatarUrl: user.avatarUrl, darkMode: user.darkMode,
    boardTheme: user.boardTheme, pieceSet: user.pieceSet, soundEnabled: user.soundEnabled };
}

async function syncConcreteUser(identity: ConcreteIdentity): Promise<ChessUser> {
  const externalId = identity.id;
  const username = identity.username.slice(0, 100);
  const email = (identity.email || `concrete-${externalId}@users.invalid`).slice(0, 320);
  let user = await prisma.user.findUnique({ where: { externalId } });
  if (!user) {
    const [byEmail, byUsername] = await Promise.all([
      prisma.user.findUnique({ where: { email } }), prisma.user.findUnique({ where: { username } }),
    ]);
    if (byEmail && byUsername && byEmail.id !== byUsername.id) throw new ConcreteAuthorityError("Concrete identity matches two existing chess profiles", 409);
    user = byEmail || byUsername;
  }
  if (!user) {
    user = await prisma.user.create({ data: {
      externalId, email, username, passwordHash: `concrete-sso-disabled:${crypto.randomBytes(32).toString("hex")}`,
      verified: true, active: true,
    }});
  } else {
    const [emailConflict, usernameConflict] = await Promise.all([
      prisma.user.findFirst({ where: { email, id: { not: user.id } }, select: { id: true } }),
      prisma.user.findFirst({ where: { username, id: { not: user.id } }, select: { id: true } }),
    ]);
    user = await prisma.user.update({ where: { id: user.id }, data: {
      externalId, active: true, verified: true,
      ...(emailConflict ? {} : { email }), ...(usernameConflict ? {} : { username }),
    }});
  }
  const favorites = await prisma.collection.findFirst({ where: { userId: user.id, name: "Favorites" }, select: { id: true } });
  if (!favorites) await prisma.collection.create({ data: { userId: user.id, name: "Favorites" } });
  await prisma.refreshToken.deleteMany({ where: { userId: user.id } });
  return user as ChessUser;
}

async function clearLegacyRefresh(request: FastifyRequest, reply: FastifyReply) {
  const raw = request.cookies[LEGACY_REFRESH_COOKIE];
  if (raw) await prisma.refreshToken.deleteMany({ where: { token: hashToken(raw) } }).catch(() => undefined);
  reply.clearCookie(LEGACY_REFRESH_COOKIE, { path: "/" });
  reply.clearCookie(LEGACY_REFRESH_COOKIE, { path: "/", domain: ".xavi.app" });
}

function safeChessNext(value: unknown): string {
  const next = String(value ?? "").trim();
  return !next || /[\r\n]/.test(next) || !/^\/chess(?:\/|$|\?)/.test(next) ? "/chess/play" : next;
}

async function authenticateFromConcreteCookie(request: FastifyRequest): Promise<ConcreteIdentity> {
  const concrete = request.cookies[CONCRETE_COOKIE];
  if (!concrete) throw new ConcreteAuthorityError("No Concrete session", 401);
  return verifyConcreteToken(await issueConcreteToken(concrete));
}

export async function concreteAuthRoutes(app: FastifyInstance) {
  app.post("/auth/concrete/session", async (request, reply) => {
    try {
      const user = await syncConcreteUser(await authenticateFromConcreteCookie(request));
      await clearLegacyRefresh(request, reply);
      return { authenticated: true,
        accessToken: signAccessToken({ userId: user.id, email: user.email, username: user.username, role: user.role }),
        user: presentUser(user) };
    } catch (error) {
      if (error instanceof ConcreteAuthorityError) {
        if (!error.authorityUnavailable) await clearLegacyRefresh(request, reply);
        return reply.status(error.statusCode).send({ authenticated: false, authorityUnavailable: error.authorityUnavailable, error: error.message });
      }
      logger.error({ err: error }, "Concrete session synchronization failed");
      return reply.status(503).send({ authenticated: false, authorityUnavailable: true });
    }
  });

  app.post<{ Body: { token?: string; next?: string } }>("/auth/concrete/callback", async (request, reply) => {
    const token = String(request.body?.token ?? "").trim();
    if (!token) return reply.status(400).send({ error: "Missing Concrete token" });
    try {
      await syncConcreteUser(await verifyConcreteToken(token));
      await clearLegacyRefresh(request, reply);
      return reply.redirect(safeChessNext(request.body?.next));
    } catch (error) {
      if (error instanceof ConcreteAuthorityError) return reply.status(error.statusCode).send({ error: error.message });
      logger.error({ err: error }, "Concrete callback failed");
      return reply.status(503).send({ error: "Concrete authentication unavailable" });
    }
  });
}
