import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
const protectedRoutes = ["/play", "/friends", "/settings", "/history", "/collections", "/invites", "/stats"];
const authRoutes = ["/login", "/register"];
function prefix(request: NextRequest) { return (request.headers.get("x-forwarded-prefix") || "/chess").replace(/\/$/, "") || "/chess"; }
function host(request: NextRequest) {
  const h=(request.headers.get("x-forwarded-host") || request.headers.get("host") || "www.xavi.app").split(",",1)[0].trim();
  return h === "xavi.app" || h === "www.xavi.app" ? h : "www.xavi.app";
}
function publicPath(request: NextRequest, path: string) { return `${prefix(request)}${path}`; }
function currentPublicUrl(request: NextRequest) {
  const url=new URL(`https://${host(request)}${prefix(request)}${request.nextUrl.pathname}`);
  request.nextUrl.searchParams.forEach((value,key)=>url.searchParams.append(key,value)); return url.toString();
}
function promotionUrl(request: NextRequest) {
  const url=new URL(`https://${host(request)}/api/jwt/promote`); url.searchParams.set("return",currentPublicUrl(request)); return url;
}
export function middleware(request: NextRequest) {
  const { pathname, searchParams }=request.nextUrl;
  const hasConcrete=request.cookies.has("CONCRETE");
  const isProtected=protectedRoutes.some((route)=>pathname.startsWith(route));
  const isAuth=authRoutes.some((route)=>pathname.startsWith(route));
  if (isAuth && hasConcrete) return NextResponse.redirect(new URL(publicPath(request,"/play"),request.url));
  if ((isProtected || isAuth) && !hasConcrete) {
    if (searchParams.get("concrete_sso") === "none") {
      if (isProtected) return NextResponse.redirect(new URL(publicPath(request,"/login?concrete_sso=none"),request.url));
      return NextResponse.next();
    }
    return NextResponse.redirect(promotionUrl(request));
  }
  return NextResponse.next();
}
