def rank_web(rows,query):
    ranked=[]
    for r in dedupe(rows):
        x=dict(r); x["_score"]=web_score(x,query); ranked.append(x)
    ranked.sort(key=lambda r:(r["_score"],len(r.get("snippet") or "")),reverse=True)
    for r in ranked: r.pop("_score",None)
