async def searx_web_node(port,query,budget=3.4):
    try:
        params={"q":query,"categories":"general","format":"json","safesearch":0,"language":"all"}
        async with httpx.AsyncClient(timeout=httpx.Timeout(budget,connect=.7),trust_env=False) as c:
            r=await c.get(f"http://127.0.0.1:{port}/search",params=params)
            r.raise_for_status()
            return [x for x in (normalize(v,f"searx-{port}") for v in r.json().get("results",[])) if x]
    except Exception:
