async def live_web_search(query):
    h=int(hashlib.sha1(("web|"+query).encode()).hexdigest()[:8],16)
    ports=SEARX_PORTS[h%len(SEARX_PORTS):]+SEARX_PORTS[:h%len(SEARX_PORTS)]
    primary=ports[:min(5,len(ports))]
    tasks=[asyncio.create_task(searx_web_node(p,query,3.35)) for p in primary]
    done,pending=await asyncio.wait(tasks,timeout=3.55)
    for task in pending: task.cancel()
    rows=[]
    for task in done:
        try: rows.extend(task.result())
        except Exception: pass
    ranked=rank_web(rows,query)
    if len(ranked)<24:
        secondary=ports[len(primary):len(primary)+3]
        more=await asyncio.gather(*(searx_web_node(p,query,1.5) for p in secondary),return_exceptions=True)
        for batch in more:
            if isinstance(batch,list): rows.extend(batch)
    return rank_web(rows,query)

