<?php
namespace Xavi\FusionOS;

defined('C5_EXECUTE') or die('Access Denied.');

use Concrete\Core\User\User;

class StartMenuService
{
    private $db;
    private const SIZES = ['small','medium','wide','large'];
    private const EVENTS = ['category:open','category:updated','tile:pinned','tile:unpinned','tile:moved','tile:opened','automation:test'];
    private const DEFAULT_GROUP = 'pinned';
    private const MAX_COLUMNS = 128;
    private const MAX_ROWS = 512;

    public function __construct()
    {
        $this->db = app('database')->connection();
        $this->ensureSchema();
    }

    public function ensureSchema(): void
    {
        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionStartMenuItems (
            uID INT UNSIGNED NOT NULL,
            appID VARCHAR(128) NOT NULL,
            startPinned TINYINT(1) NOT NULL DEFAULT 0,
            taskbarPinned TINYINT(1) NOT NULL DEFAULT 0,
            tileSize VARCHAR(16) NOT NULL DEFAULT 'medium',
            tileX INT NULL DEFAULT NULL,
            tileY INT NULL DEFAULT NULL,
            groupID VARCHAR(64) NOT NULL DEFAULT 'pinned',
            sortOrder INT NOT NULL DEFAULT 0,
            groupName VARCHAR(190) NOT NULL DEFAULT 'Pinned',
            updatedAt DATETIME NOT NULL,
            PRIMARY KEY (uID, appID),
            KEY xaviFusionStartUserPosition (uID, startPinned, groupID, tileY, tileX),
            KEY xaviFusionTaskbarUserOrder (uID, taskbarPinned, sortOrder)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $this->ensureColumn('tileX','INT NULL DEFAULT NULL');
        $this->ensureColumn('tileY','INT NULL DEFAULT NULL');
        $this->ensureColumn('groupID',"VARCHAR(64) NOT NULL DEFAULT 'pinned'");

        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionStartMenuGroups (
            uID INT UNSIGNED NOT NULL,
            groupID VARCHAR(64) NOT NULL,
            name VARCHAR(190) NOT NULL,
            accent VARCHAR(16) NOT NULL DEFAULT '#0067c0',
            background VARCHAR(16) NOT NULL DEFAULT '#202020',
            gridColumns INT NOT NULL DEFAULT 8,
            gridRows INT NOT NULL DEFAULT 10,
            sortOrder INT NOT NULL DEFAULT 10,
            collapsed TINYINT(1) NOT NULL DEFAULT 0,
            automationEnabled TINYINT(1) NOT NULL DEFAULT 0,
            automationEvents VARCHAR(512) NOT NULL DEFAULT '',
            automationCode LONGTEXT NOT NULL,
            createdAt DATETIME NOT NULL,
            updatedAt DATETIME NOT NULL,
            PRIMARY KEY (uID, groupID),
            KEY xaviFusionStartGroupsOrder (uID, sortOrder, name)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $this->migrateLegacyRows();
    }

    public function layout(User $user): array
    {
        $this->registered($user);
        $this->ensureDefaultGroup((int)$user->getUserID());
        $rows=$this->db->fetchAllAssociative(
            'SELECT i.appID,i.startPinned,i.taskbarPinned,i.tileSize,i.tileX,i.tileY,i.groupID,i.sortOrder,i.groupName,i.updatedAt,g.name AS resolvedGroupName
             FROM XaviFusionStartMenuItems i
             LEFT JOIN XaviFusionStartMenuGroups g ON g.uID=i.uID AND g.groupID=i.groupID
             WHERE i.uID=? ORDER BY i.sortOrder,i.appID',
            [(int)$user->getUserID()]
        );
        return array_map(fn(array $row):array=>$this->normalizeRow($row),$rows);
    }

    public function groups(User $user): array
    {
        $this->registered($user);
        $uID=(int)$user->getUserID();
        $this->ensureDefaultGroup($uID);
        $rows=$this->db->fetchAllAssociative(
            'SELECT g.*,COUNT(i.appID) AS itemCount
             FROM XaviFusionStartMenuGroups g
             LEFT JOIN XaviFusionStartMenuItems i ON i.uID=g.uID AND i.groupID=g.groupID AND i.startPinned=1
             WHERE g.uID=? GROUP BY g.uID,g.groupID,g.name,g.accent,g.background,g.gridColumns,g.gridRows,g.sortOrder,g.collapsed,g.automationEnabled,g.automationEvents,g.automationCode,g.createdAt,g.updatedAt
             ORDER BY g.sortOrder,g.name,g.groupID',
            [$uID]
        );
        return array_map(fn(array $row):array=>$this->normalizeGroup($row),$rows);
    }

    public function createGroup(User $user,array $payload): array
    {
        $this->registered($user);
        $uID=(int)$user->getUserID();
        $name=$this->name((string)($payload['name']??'New category'));
        $groupID=$this->uniqueGroupID($uID,$name);
        $now=gmdate('Y-m-d H:i:s');
        $data=$this->groupData($payload,[
            'name'=>$name,'accent'=>'#0067c0','background'=>'#202020','gridColumns'=>8,'gridRows'=>10,
            'sortOrder'=>$this->nextGroupOrder($uID),'collapsed'=>0,'automationEnabled'=>0,'automationEvents'=>'','automationCode'=>'',
        ]);
        $this->db->insert('XaviFusionStartMenuGroups',$data+['uID'=>$uID,'groupID'=>$groupID,'createdAt'=>$now,'updatedAt'=>$now]);
        return $this->groupItem($user,$groupID);
    }

    public function updateGroup(User $user,string $groupID,array $payload): array
    {
        $this->registered($user);
        $uID=(int)$user->getUserID();$groupID=$this->groupID($groupID);
        $current=$this->db->fetchAssociative('SELECT * FROM XaviFusionStartMenuGroups WHERE uID=? AND groupID=?',[$uID,$groupID]);
        if(!$current)throw new \RuntimeException(t('Start category was not found.'));
        $data=$this->groupData($payload,$current);
        [$neededColumns,$neededRows]=$this->requiredExtent($uID,$groupID);
        $data['gridColumns']=max($data['gridColumns'],$neededColumns,4);
        $data['gridRows']=max($data['gridRows'],$neededRows,4);
        $data['updatedAt']=gmdate('Y-m-d H:i:s');
        $this->db->update('XaviFusionStartMenuGroups',$data,['uID'=>$uID,'groupID'=>$groupID]);
        if($data['name']!==(string)$current['name'])$this->db->update('XaviFusionStartMenuItems',['groupName'=>$data['name'],'updatedAt'=>gmdate('Y-m-d H:i:s')],['uID'=>$uID,'groupID'=>$groupID]);
        return $this->groupItem($user,$groupID);
    }

    public function deleteGroup(User $user,string $groupID,array $payload=[]): void
    {
        $this->registered($user);
        $uID=(int)$user->getUserID();$groupID=$this->groupID($groupID);
        if($groupID===self::DEFAULT_GROUP)throw new \RuntimeException(t('The default Pinned category cannot be deleted.'));
        $current=$this->db->fetchAssociative('SELECT * FROM XaviFusionStartMenuGroups WHERE uID=? AND groupID=?',[$uID,$groupID]);
        if(!$current)throw new \RuntimeException(t('Start category was not found.'));
        $mode=(string)($payload['mode']??'move');
        $targetID=$this->groupID((string)($payload['targetGroupID']??self::DEFAULT_GROUP));
        if($mode==='unpin'){
            $this->db->executeStatement('UPDATE XaviFusionStartMenuItems SET startPinned=0,updatedAt=? WHERE uID=? AND groupID=?',[gmdate('Y-m-d H:i:s'),$uID,$groupID]);
        }else{
            $target=$this->groupRow($uID,$targetID);
            $rows=$this->db->fetchAllAssociative('SELECT * FROM XaviFusionStartMenuItems WHERE uID=? AND groupID=? AND startPinned=1 ORDER BY sortOrder,appID',[$uID,$groupID]);
            foreach($rows as $row){
                [$x,$y]=$this->nextFreePosition($uID,$targetID,$this->size((string)$row['tileSize']),(string)$row['appID']);
                $this->db->update('XaviFusionStartMenuItems',['groupID'=>$targetID,'groupName'=>$target['name'],'tileX'=>$x,'tileY'=>$y,'updatedAt'=>gmdate('Y-m-d H:i:s')],['uID'=>$uID,'appID'=>$row['appID']]);
                [$w,$h]=$this->dimensions((string)$row['tileSize']);$this->expandGroup($uID,$targetID,$x+$w,$y+$h);
            }
        }
        $this->db->delete('XaviFusionStartMenuGroups',['uID'=>$uID,'groupID'=>$groupID]);
    }

    public function groupItem(User $user,string $groupID): array
    {
        $this->registered($user);$uID=(int)$user->getUserID();$groupID=$this->groupID($groupID);
        $row=$this->db->fetchAssociative('SELECT g.*,(SELECT COUNT(*) FROM XaviFusionStartMenuItems i WHERE i.uID=g.uID AND i.groupID=g.groupID AND i.startPinned=1) AS itemCount FROM XaviFusionStartMenuGroups g WHERE g.uID=? AND g.groupID=?',[$uID,$groupID]);
        if(!$row)throw new \RuntimeException(t('Start category was not found.'));
        return $this->normalizeGroup($row);
    }

    public function update(User $user,string $appID,array $patch): array
    {
        $this->registered($user);$uID=(int)$user->getUserID();$appID=$this->appID($appID);$this->ensureDefaultGroup($uID);
        $existing=$this->db->fetchAssociative('SELECT * FROM XaviFusionStartMenuItems WHERE uID=? AND appID=?',[$uID,$appID]);
        $groupID=$this->resolveGroupID($uID,$patch,$existing);
        $group=$this->groupRow($uID,$groupID);
        $size=$this->size((string)($patch['tileSize']??($existing['tileSize']??'medium')));
        $startPinned=array_key_exists('startPinned',$patch)?(!empty($patch['startPinned'])?1:0):($existing?(int)$existing['startPinned']:0);
        $taskbarPinned=array_key_exists('taskbarPinned',$patch)?(!empty($patch['taskbarPinned'])?1:0):($existing?(int)$existing['taskbarPinned']:0);
        $explicit=array_key_exists('tileX',$patch)&&array_key_exists('tileY',$patch);
        $x=$explicit?max(0,min(self::MAX_COLUMNS-1,(int)$patch['tileX'])):($existing&&$existing['tileX']!==null?(int)$existing['tileX']:null);
        $y=$explicit?max(0,min(self::MAX_ROWS-1,(int)$patch['tileY'])):($existing&&$existing['tileY']!==null?(int)$existing['tileY']:null);
        if($startPinned&&($x===null||$y===null||(!$explicit&&(!$existing||empty($existing['startPinned'])||(string)$existing['groupID']!==$groupID))))[$x,$y]=$this->nextFreePosition($uID,$groupID,$size,$appID);
        $x=max(0,(int)($x??0));$y=max(0,(int)($y??0));[$w,$h]=$this->dimensions($size);
        if($startPinned)$this->assertFree($uID,$groupID,$appID,$x,$y,$w,$h);
        $data=['startPinned'=>$startPinned,'taskbarPinned'=>$taskbarPinned,'tileSize'=>$size,'tileX'=>$x,'tileY'=>$y,'groupID'=>$groupID,'groupName'=>$group['name'],'sortOrder'=>$existing?(int)$existing['sortOrder']:$this->nextOrder($uID),'updatedAt'=>gmdate('Y-m-d H:i:s')];
        if(array_key_exists('sortOrder',$patch))$data['sortOrder']=max(0,min(1000000,(int)$patch['sortOrder']));
        if($existing)$this->db->update('XaviFusionStartMenuItems',$data,['uID'=>$uID,'appID'=>$appID]);else$this->db->insert('XaviFusionStartMenuItems',$data+['uID'=>$uID,'appID'=>$appID]);
        if($startPinned)$this->expandGroup($uID,$groupID,$x+$w,$y+$h);
        return $this->item($user,$appID);
    }

    public function reorder(User $user,array $items): array
    {
        $this->registered($user);$uID=(int)$user->getUserID();$this->ensureDefaultGroup($uID);
        $current=[];foreach($this->db->fetchAllAssociative('SELECT * FROM XaviFusionStartMenuItems WHERE uID=?',[$uID]) as $row)$current[(string)$row['appID']]=$row;
        $changes=[];$position=10;
        foreach(array_slice($items,0,1000) as $item){
            if(!is_array($item)||empty($item['appID']))continue;
            $appID=$this->appID((string)$item['appID']);$existing=$current[$appID]??null;$groupID=$this->resolveGroupID($uID,$item,$existing);$group=$this->groupRow($uID,$groupID);$size=$this->size((string)($item['tileSize']??($existing['tileSize']??'medium')));
            $changes[$appID]=['uID'=>$uID,'appID'=>$appID,'startPinned'=>array_key_exists('startPinned',$item)?(!empty($item['startPinned'])?1:0):($existing?(int)$existing['startPinned']:1),'taskbarPinned'=>$existing?(int)$existing['taskbarPinned']:0,'tileSize'=>$size,'tileX'=>max(0,min(self::MAX_COLUMNS-1,(int)($item['tileX']??($existing['tileX']??0)))),'tileY'=>max(0,min(self::MAX_ROWS-1,(int)($item['tileY']??($existing['tileY']??0)))),'groupID'=>$groupID,'groupName'=>$group['name'],'sortOrder'=>array_key_exists('sortOrder',$item)?max(0,(int)$item['sortOrder']):$position,'updatedAt'=>gmdate('Y-m-d H:i:s')];
            $position+=10;
        }
        $final=$current;foreach($changes as $appID=>$row)$final[$appID]=$row;
        $this->assertLayoutFree($final);
        foreach($changes as $appID=>$row){$data=$row;unset($data['uID'],$data['appID']);if(isset($current[$appID]))$this->db->update('XaviFusionStartMenuItems',$data,['uID'=>$uID,'appID'=>$appID]);else$this->db->insert('XaviFusionStartMenuItems',$row);if($row['startPinned']){[$w,$h]=$this->dimensions($row['tileSize']);$this->expandGroup($uID,$row['groupID'],$row['tileX']+$w,$row['tileY']+$h);}}
        return $this->layout($user);
    }

    public function reset(User $user,string $appID): void
    {
        $this->registered($user);$this->db->delete('XaviFusionStartMenuItems',['uID'=>(int)$user->getUserID(),'appID'=>$this->appID($appID)]);
    }

    public function item(User $user,string $appID): array
    {
        $this->registered($user);$row=$this->db->fetchAssociative('SELECT i.*,g.name AS resolvedGroupName FROM XaviFusionStartMenuItems i LEFT JOIN XaviFusionStartMenuGroups g ON g.uID=i.uID AND g.groupID=i.groupID WHERE i.uID=? AND i.appID=?',[(int)$user->getUserID(),$this->appID($appID)]);if(!$row)throw new \RuntimeException(t('Start menu item was not found.'));return $this->normalizeRow($row);
    }

    public function find(User $user,string $appID): ?array { try{return $this->item($user,$appID);}catch(\Throwable $ignored){return null;} }

    private function assertLayoutFree(array $rows): void
    {
        $occupied=[];
        foreach($rows as $row){if(empty($row['startPinned']))continue;$groupID=$this->groupID((string)($row['groupID']??self::DEFAULT_GROUP));$size=$this->size((string)$row['tileSize']);[$w,$h]=$this->dimensions($size);$x=max(0,(int)$row['tileX']);$y=max(0,(int)$row['tileY']);for($dy=0;$dy<$h;$dy++)for($dx=0;$dx<$w;$dx++){$key=$groupID.':'.($y+$dy).':'.($x+$dx);if(isset($occupied[$key]))throw new \RuntimeException(t('That Start grid space is occupied by another tile.'));$occupied[$key]=(string)$row['appID'];}}
    }

    private function assertFree(int $uID,string $groupID,string $appID,int $x,int $y,int $w,int $h): void
    {
        $rows=$this->db->fetchAllAssociative('SELECT appID,tileSize,tileX,tileY FROM XaviFusionStartMenuItems WHERE uID=? AND groupID=? AND startPinned=1 AND appID<>?',[$uID,$groupID,$appID]);
        foreach($rows as $row){[$ow,$oh]=$this->dimensions((string)$row['tileSize']);$ox=(int)$row['tileX'];$oy=(int)$row['tileY'];if(!($x+$w<=$ox||$ox+$ow<=$x||$y+$h<=$oy||$oy+$oh<=$y))throw new \RuntimeException(t('That Start grid space is occupied by another tile.'));}
    }

    private function nextFreePosition(int $uID,string $groupID,string $size,?string $excludeAppID=null): array
    {
        $group=$this->groupRow($uID,$groupID);$rows=$this->db->fetchAllAssociative('SELECT appID,tileSize,tileX,tileY FROM XaviFusionStartMenuItems WHERE uID=? AND groupID=? AND startPinned=1 ORDER BY tileY,tileX',[$uID,$groupID]);$occupied=[];foreach($rows as $row){if($excludeAppID!==null&&(string)$row['appID']===$excludeAppID)continue;[$w,$h]=$this->dimensions((string)$row['tileSize']);$this->occupy($occupied,(int)$row['tileX'],(int)$row['tileY'],$w,$h);}[$w,$h]=$this->dimensions($size);$columns=max(4,(int)$group['gridColumns']);$rowsLimit=max(4,(int)$group['gridRows']);for($y=0;$y<$rowsLimit;$y++)for($x=0;$x<=$columns-$w;$x++)if($this->isFree($occupied,$x,$y,$w,$h))return[$x,$y];return[0,$rowsLimit];
    }

    private function isFree(array $occupied,int $x,int $y,int $w,int $h): bool { for($dy=0;$dy<$h;$dy++)for($dx=0;$dx<$w;$dx++)if(isset($occupied[($y+$dy).':'.($x+$dx)]))return false;return true; }
    private function occupy(array &$occupied,int $x,int $y,int $w,int $h): void { for($dy=0;$dy<$h;$dy++)for($dx=0;$dx<$w;$dx++)$occupied[($y+$dy).':'.($x+$dx)]=true; }

    private function expandGroup(int $uID,string $groupID,int $columns,int $rows): void
    {
        $group=$this->groupRow($uID,$groupID);$columns=min(self::MAX_COLUMNS,max((int)$group['gridColumns'],$columns));$rows=min(self::MAX_ROWS,max((int)$group['gridRows'],$rows));if($columns!==(int)$group['gridColumns']||$rows!==(int)$group['gridRows'])$this->db->update('XaviFusionStartMenuGroups',['gridColumns'=>$columns,'gridRows'=>$rows,'updatedAt'=>gmdate('Y-m-d H:i:s')],['uID'=>$uID,'groupID'=>$groupID]);
    }

    private function requiredExtent(int $uID,string $groupID): array
    {
        $columns=4;$rows=4;foreach($this->db->fetchAllAssociative('SELECT tileSize,tileX,tileY FROM XaviFusionStartMenuItems WHERE uID=? AND groupID=? AND startPinned=1',[$uID,$groupID]) as $row){[$w,$h]=$this->dimensions((string)$row['tileSize']);$columns=max($columns,(int)$row['tileX']+$w);$rows=max($rows,(int)$row['tileY']+$h);}return[$columns,$rows];
    }

    private function resolveGroupID(int $uID,array $patch,?array $existing): string
    {
        if(!empty($patch['groupID'])){$id=$this->groupID((string)$patch['groupID']);$this->groupRow($uID,$id);return$id;}
