        if($existing&&!empty($existing['groupID']))return$this->groupID((string)$existing['groupID']);return self::DEFAULT_GROUP;
    }

    private function groupData(array $payload,array $current): array
    {
        $events=$this->events($payload['automationEvents']??($current['automationEvents']??''));$code=(string)($payload['automationCode']??($current['automationCode']??''));if(strlen($code)>20000)throw new \InvalidArgumentException(t('Category automation code is limited to 20,000 bytes.'));
        return ['name'=>$this->name((string)($payload['name']??$current['name']??'Pinned')),'accent'=>$this->color((string)($payload['accent']??$current['accent']??'#0067c0')),'background'=>$this->color((string)($payload['background']??$current['background']??'#202020')),'gridColumns'=>max(4,min(self::MAX_COLUMNS,(int)($payload['gridColumns']??$current['gridColumns']??8))),'gridRows'=>max(4,min(self::MAX_ROWS,(int)($payload['gridRows']??$current['gridRows']??10))),'sortOrder'=>max(0,min(1000000,(int)($payload['sortOrder']??$current['sortOrder']??10))),'collapsed'=>!empty($payload['collapsed']??$current['collapsed']??false)?1:0,'automationEnabled'=>!empty($payload['automationEnabled']??$current['automationEnabled']??false)?1:0,'automationEvents'=>implode(',',$events),'automationCode'=>$code];
    }

    private function createGroupForUID(int $uID,string $name): array
    {
        $groupID=$this->uniqueGroupID($uID,$name);$now=gmdate('Y-m-d H:i:s');$row=['uID'=>$uID,'groupID'=>$groupID,'name'=>$name,'accent'=>'#0067c0','background'=>'#202020','gridColumns'=>8,'gridRows'=>10,'sortOrder'=>$this->nextGroupOrder($uID),'collapsed'=>0,'automationEnabled'=>0,'automationEvents'=>'','automationCode'=>'','createdAt'=>$now,'updatedAt'=>$now];$this->db->insert('XaviFusionStartMenuGroups',$row);return$row;
    }

    private function ensureDefaultGroup(int $uID): void
    {
        if(!(int)$this->db->fetchOne('SELECT COUNT(*) FROM XaviFusionStartMenuGroups WHERE uID=? AND groupID=?',[$uID,self::DEFAULT_GROUP])){$now=gmdate('Y-m-d H:i:s');$this->db->insert('XaviFusionStartMenuGroups',['uID'=>$uID,'groupID'=>self::DEFAULT_GROUP,'name'=>'Pinned','accent'=>'#0067c0','background'=>'#202020','gridColumns'=>8,'gridRows'=>10,'sortOrder'=>10,'collapsed'=>0,'automationEnabled'=>0,'automationEvents'=>'','automationCode'=>'','createdAt'=>$now,'updatedAt'=>$now]);}
    }

    private function migrateLegacyRows(): void
    {
        $uids=$this->db->fetchFirstColumn('SELECT DISTINCT uID FROM XaviFusionStartMenuItems');foreach($uids as $uid){$uID=(int)$uid;$this->ensureDefaultGroup($uID);$groups=$this->db->fetchAllAssociative('SELECT DISTINCT groupName FROM XaviFusionStartMenuItems WHERE uID=?',[$uID]);foreach($groups as $groupRow){$name=$this->name((string)($groupRow['groupName']??'Pinned'));if(strcasecmp($name,'Pinned')===0){$id=self::DEFAULT_GROUP;}else{$existing=$this->db->fetchAssociative('SELECT * FROM XaviFusionStartMenuGroups WHERE uID=? AND name=?',[$uID,$name]);$id=$existing?(string)$existing['groupID']:(string)$this->createGroupForUID($uID,$name)['groupID'];}$this->db->executeStatement('UPDATE XaviFusionStartMenuItems SET groupID=?,groupName=? WHERE uID=? AND groupName=?',[$id,$name,$uID,$groupRow['groupName']]);}foreach($this->db->fetchAllAssociative('SELECT * FROM XaviFusionStartMenuItems WHERE uID=? AND (tileX IS NULL OR tileY IS NULL)',[$uID]) as $row){[$x,$y]=$this->nextFreePosition($uID,(string)$row['groupID'],$this->size((string)$row['tileSize']),(string)$row['appID']);$this->db->update('XaviFusionStartMenuItems',['tileX'=>$x,'tileY'=>$y,'updatedAt'=>gmdate('Y-m-d H:i:s')],['uID'=>$uID,'appID'=>$row['appID']]);}}
    }

