def deterministic_enrichment(title: str, content: str) -> dict[str,Any]:
    text=(str(title or '')+' '+str(content or '')).lower()
    categories={
      'tech':['ai','software','computer','chip','cyber','internet','technology','openai','google','microsoft'],
      'business':['business','market','stock','company','earnings','bank','economy','finance','investment'],
      'politics':['election','president','minister','parliament','congress','government','politic','senate'],
      'science':['science','research','study','space','physics','climate','nasa','biology'],
      'health':['health','medical','hospital','disease','drug','doctor','vaccine'],
      'sports':['sport','game','team','league','match','player','season','tournament'],
      'entertainment':['film','movie','music','actor','television','celebrity','album','show'],
      'world':['war','country','international','border','diplomacy','military','global'],
    }
    scores={k:sum(text.count(w) for w in words) for k,words in categories.items()}
    category=max(scores,key=scores.get) if max(scores.values(),default=0)>0 else 'world'
    positive=['gain','growth','win','success','improve','peace','record','breakthrough','strong']
    negative=['loss','fall','crisis','war','attack','death','risk','decline','weak','fail']
    pos=sum(text.count(w) for w in positive); neg=sum(text.count(w) for w in negative)
    sentiment=max(-1.0,min(1.0,(pos-neg)/max(3,pos+neg)))
    raw=re.findall(r"[A-Za-z][A-Za-z0-9'_-]{2,}",str(title or '')+' '+str(content or ''))
    stop={'the','and','for','with','that','this','from','have','has','was','were','are','will','into','about','after','before','their','they','its','not','but','you','your','his','her','our','out','new','says','said'}
    counts={}
    display={}
    for word in raw:
        key=word.lower()
        if key in stop: continue
        counts[key]=counts.get(key,0)+1; display.setdefault(key,word)
    keywords=[display[k] for k in sorted(counts,key=lambda k:(counts[k],len(k)),reverse=True)[:5]]
    sentences=re.split(r'(?<=[.!?])\s+',str(content or '').strip())
    summary=' '.join(x.strip() for x in sentences[:2] if x.strip())[:520] or str(title or '')[:520]
    return {'provider':'deterministic','model':'rules-enrich-v1','ok':True,'latency_ms':0,
            'category':category,'summary':summary,'keywords':keywords,'sentiment_score':round(sentiment,3),'confidence':.52}

def _normalized_enrichment(row: dict[str,Any]) -> dict[str,Any]:
    allowed={'politics','business','tech','science','sports','entertainment','health','world'}
    out=dict(row)
    cat=str(row.get('category') or '').strip().lower()
    out['category']=cat if cat in allowed else None
    summary=str(row.get('summary') or '').strip()
    out['summary']=summary[:900] if summary else None
    kws=row.get('keywords') or []
    if isinstance(kws,str): kws=[x.strip() for x in kws.split(',') if x.strip()]
    if not isinstance(kws,list): kws=[]
    out['keywords']=[str(x).strip()[:100] for x in kws if str(x).strip()][:8]
    try: out['sentiment_score']=max(-1.0,min(1.0,float(row.get('sentiment_score'))))
    except Exception: out['sentiment_score']=None
    try: out['confidence']=max(0.0,min(1.0,float(row.get('confidence',.5))))
    except Exception: out['confidence']=.5
    return out

