insert='''    public function sourceRoot(): string
    {
        return $this->sourceRoot;
    }

    /**
     * Read-only source discovery for the administrator dashboard.
     * This method never copies files, writes registry rows, or changes user state.
     */
    public function discoverSources(): array
    {
        $installed = [];
        foreach ($this->registry() as $row) {
            $installed[(string) $row['appID']] = $row;
        }
        $items = [];
        foreach (scandir($this->sourceRoot) ?: [] as $directory) {
            if ($directory === '.' || $directory === '..' || str_starts_with($directory, '.')) {
                continue;
            }
            $path = $this->sourceRoot . '/' . $directory;
            $manifestPath = $path . '/fusion-app.json';
            if (!is_dir($path) || is_link($path) || !is_file($manifestPath)) {
                continue;
            }
            $item = [
                'directory' => $directory,
                'valid' => false,
                'installed' => false,
                'updateAvailable' => false,
                'error' => '',
            ];
            try {
                $manifest = json_decode((string) file_get_contents($manifestPath), true, 512, JSON_THROW_ON_ERROR);
                if (!is_array($manifest) || ($manifest['format'] ?? '') !== 'xavi-fusion-app' || (int) ($manifest['formatVersion'] ?? 0) !== 1) {
                    throw new \\InvalidArgumentException(t('Invalid Fusion application manifest format.'));
                }
                $id = $this->normalizeAppID((string) ($manifest['id'] ?? ''));
                $version = trim((string) ($manifest['version'] ?? '1.0.0'));
                if (!preg_match('/^[A-Za-z0-9][A-Za-z0-9._-]{0,39}$/', $version)) {
                    throw new \\InvalidArgumentException(t('Invalid application version.'));
                }
                $entry = is_array($manifest['entry'] ?? null) ? $manifest['entry'] : [];
                $component = strtolower(trim((string) ($entry['component'] ?? $manifest['component'] ?? '')));
                $module = trim((string) ($entry['module'] ?? $manifest['module'] ?? 'index.js'));
                if (!preg_match('/^[a-z][a-z0-9._-]*-[a-z0-9._-]+$/', $component)) {
                    throw new \\InvalidArgumentException(t('Invalid custom-element component name.'));
                }
                if ($module === '' || str_contains($module, '..') || str_starts_with($module, '/') || !is_file($path . '/' . $module)) {
                    throw new \\InvalidArgumentException(t('The application entry module is missing.'));
                }
                $row = $installed[$id] ?? null;
                $manifestModified = (int) (filemtime($manifestPath) ?: 0);
                $installedModified = $row ? (int) (strtotime((string) ($row['updatedAt'] ?? '')) ?: 0) : 0;
                $item += [
                    'id' => $id,
                    'version' => $version,
                    'title' => trim((string) ($manifest['title'] ?? $id)),
                    'description' => trim((string) ($manifest['description'] ?? '')),
                    'category' => trim((string) ($manifest['category'] ?? 'Applications')),
                    'component' => $component,
                    'module' => $module,
                    'fileCount' => count(is_array($manifest['files'] ?? null) ? $manifest['files'] : []),
                    'valid' => true,
                    'installed' => (bool) $row,
                    'installedVersion' => $row ? (string) $row['version'] : '',
                    'enabledGlobal' => $row ? !empty($row['enabledGlobal']) : true,
                ];
                $item['updateAvailable'] = !$row || (string) $row['version'] !== $version || $manifestModified > $installedModified;
            } catch (\\Throwable $exc) {
                $item['error'] = $exc->getMessage();
            }
            $items[] = $item;
        }
        usort($items, static fn(array $a, array $b): int => strcasecmp((string) ($a['title'] ?? $a['directory']), (string) ($b['title'] ?? $b['directory'])));
        return $items;
    }

    public function setGlobalState(string $appID, bool $enabled): void
    {
        $appID = $this->normalizeAppID($appID);
        if (!(int) $this->db->fetchOne('SELECT COUNT(*) FROM XaviFusionApplications WHERE appID = ?', [$appID])) {
            throw new \\RuntimeException(t('Fusion application not found.'));
        }
        $this->db->update('XaviFusionApplications', [
            'enabledGlobal' => $enabled ? 1 : 0,
            'updatedAt' => gmdate('Y-m-d H:i:s'),
        ], ['appID' => $appID]);
    }
