<?php
namespace Xavi\FusionOS;

defined('C5_EXECUTE') or die('Access Denied.');

use Concrete\Core\User\User;

class StartMenuService
{
    private $db;
    private const SIZES = ['small', 'medium', 'wide', 'large'];

    public function __construct()
    {
        $this->db = app('database')->connection();
        $this->ensureSchema();
    }

    public function ensureSchema(): void
    {
        $this->db->executeStatement("CREATE TABLE IF NOT EXISTS XaviFusionStartMenuItems (
            uID INT UNSIGNED NOT NULL,
            appID VARCHAR(128) NOT NULL,
            startPinned TINYINT(1) NOT NULL DEFAULT 0,
            taskbarPinned TINYINT(1) NOT NULL DEFAULT 0,
            tileSize VARCHAR(16) NOT NULL DEFAULT 'medium',
            sortOrder INT NOT NULL DEFAULT 0,
            groupName VARCHAR(190) NOT NULL DEFAULT 'Pinned',
            updatedAt DATETIME NOT NULL,
            PRIMARY KEY (uID, appID),
            KEY xaviFusionStartUserOrder (uID, startPinned, groupName, sortOrder),
            KEY xaviFusionTaskbarUserOrder (uID, taskbarPinned, sortOrder)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    }

    public function layout(User $user): array
    {
        $this->registered($user);
        $rows = $this->db->fetchAllAssociative(
            'SELECT appID,startPinned,taskbarPinned,tileSize,sortOrder,groupName,updatedAt
             FROM XaviFusionStartMenuItems WHERE uID=? ORDER BY groupName,sortOrder,appID',
            [(int) $user->getUserID()]
        );
        return array_map(fn(array $row): array => $this->normalizeRow($row), $rows);
    }

    public function update(User $user, string $appID, array $patch): array
    {
        $this->registered($user);
        $appID = $this->appID($appID);
        $uID = (int) $user->getUserID();
        $existing = $this->db->fetchAssociative(
            'SELECT * FROM XaviFusionStartMenuItems WHERE uID=? AND appID=?',
            [$uID, $appID]
        );
        $row = [
            'startPinned' => $existing ? (int) $existing['startPinned'] : 0,
            'taskbarPinned' => $existing ? (int) $existing['taskbarPinned'] : 0,
            'tileSize' => $existing ? (string) $existing['tileSize'] : 'medium',
            'sortOrder' => $existing ? (int) $existing['sortOrder'] : $this->nextOrder($uID),
            'groupName' => $existing ? (string) $existing['groupName'] : 'Pinned',
            'updatedAt' => gmdate('Y-m-d H:i:s'),
        ];
        if (array_key_exists('startPinned', $patch)) $row['startPinned'] = filter_var($patch['startPinned'], FILTER_VALIDATE_BOOLEAN) ? 1 : 0;
        if (array_key_exists('taskbarPinned', $patch)) $row['taskbarPinned'] = filter_var($patch['taskbarPinned'], FILTER_VALIDATE_BOOLEAN) ? 1 : 0;
        if (array_key_exists('tileSize', $patch)) {
            $size = strtolower(trim((string) $patch['tileSize']));
            if (!in_array($size, self::SIZES, true)) throw new \InvalidArgumentException(t('Unsupported Start tile size.'));
            $row['tileSize'] = $size;
        }
        if (array_key_exists('sortOrder', $patch)) $row['sortOrder'] = max(0, min(1000000, (int) $patch['sortOrder']));
        if (array_key_exists('groupName', $patch)) {
            $group = trim((string) $patch['groupName']);
            $row['groupName'] = mb_substr($group !== '' ? $group : 'Pinned', 0, 190);
        }
        if ($existing) {
            $this->db->update('XaviFusionStartMenuItems', $row, ['uID'=>$uID, 'appID'=>$appID]);
        } else {
            $this->db->insert('XaviFusionStartMenuItems', $row + ['uID'=>$uID, 'appID'=>$appID]);
        }
        return $this->item($user, $appID);
    }

    public function reorder(User $user, array $items): array
    {
        $this->registered($user);
        $uID = (int) $user->getUserID();
        $position = 10;
        foreach (array_slice($items, 0, 500) as $item) {
            if (!is_array($item) || empty($item['appID'])) continue;
            $appID = $this->appID((string) $item['appID']);
            $group = mb_substr(trim((string) ($item['groupName'] ?? 'Pinned')) ?: 'Pinned', 0, 190);
            $existing = $this->db->fetchAssociative('SELECT * FROM XaviFusionStartMenuItems WHERE uID=? AND appID=?', [$uID,$appID]);
            $data = [
                'startPinned' => $existing ? (int)$existing['startPinned'] : 1,
                'taskbarPinned' => $existing ? (int)$existing['taskbarPinned'] : 0,
                'tileSize' => $existing && in_array($existing['tileSize'], self::SIZES, true) ? $existing['tileSize'] : 'medium',
                'sortOrder' => $position,
                'groupName' => $group,
                'updatedAt' => gmdate('Y-m-d H:i:s'),
            ];
            if ($existing) $this->db->update('XaviFusionStartMenuItems', $data, ['uID'=>$uID,'appID'=>$appID]);
            else $this->db->insert('XaviFusionStartMenuItems', $data + ['uID'=>$uID,'appID'=>$appID]);
            $position += 10;
        }
        return $this->layout($user);
    }

    public function item(User $user, string $appID): array
    {
        $this->registered($user);
