    public function find(User $user, string $appID): ?array
    {
        try { return $this->item($user, $appID); } catch (\Throwable $ignored) { return null; }
    }

    private function normalizeRow(array $row): array
    {
        return [
            'appID' => (string)$row['appID'],
            'startPinned' => !empty($row['startPinned']),
            'taskbarPinned' => !empty($row['taskbarPinned']),
            'tileSize' => in_array((string)$row['tileSize'], self::SIZES, true) ? (string)$row['tileSize'] : 'medium',
            'sortOrder' => (int)$row['sortOrder'],
            'groupName' => (string)$row['groupName'],
            'updatedAt' => (string)$row['updatedAt'],
        ];
    }

