    private function appID(string $appID): string
    {
        $appID = trim($appID);
        if ($appID === '' || strlen($appID) > 128 || !preg_match('/^[A-Za-z0-9_.:-]+$/', $appID)) throw new \InvalidArgumentException(t('Invalid application identifier.'));
        return $appID;
    }

    private function registered(User $user): void
    {
        if (!$user->isRegistered()) throw new \RuntimeException(t('A registered user is required.'));
    }
