function clip(v,n=1200){ if (v === undefined || v === null) return v; v=String(v); return v.length>n ? v.slice(0,n)+'...[truncated]' : v; }
function clean(o){
  if (!o || typeof o !== 'object') return o;
  const out = {};
  for (const k of Object.keys(o)) {
    if (/token|password|secret|key|jwt/i.test(k)) continue;
    const v=o[k];
    if (typeof v === 'string') out[k]=clip(v, 1600);
    else if (v instanceof Date) out[k]=v.toISOString();
    else if (Array.isArray(v)) out[k]=v.slice(0,6).map(x => typeof x === 'string' ? clip(x, 500) : clean(x));
    else if (v && typeof v === 'object') out[k]=clean(v);
    else out[k]=v;
  }
  return out;
}
const dbs = db.getMongo().getDBNames();
