from __future__ import annotations

import argparse
import os
import re
import signal
import subprocess
import sys
import tempfile
import termios
import time
from pathlib import Path

ROOT = Path('/var/www/xavi/xavi-man-app')
VENDOR = ROOT / 'vendor' / 'twin'
BIN = VENDOR / 'usr' / 'bin'
LIB = VENDOR / 'usr' / 'lib' / 'x86_64-linux-gnu'
SERVER = BIN / 'twin_server'
DISPLAY = BIN / 'twdisplay'
CLIENT = ROOT / 'native' / 'xavi-man-twin'
REDIRECT = ROOT / 'native' / 'libxavi_twin_redirect.so'
START_RE = re.compile(r'starting in background as (:[0-9]+) \(pid ([0-9]+)\)')
MOUSE_OFF = b'\x1b[?1006l\x1b[?1003l\x1b[?1002l\x1b[?1000l'


def base_env() -> dict[str, str]:
    env = dict(os.environ)
    env['LD_LIBRARY_PATH'] = str(LIB) + (':' + env['LD_LIBRARY_PATH'] if env.get('LD_LIBRARY_PATH') else '')
    env['PATH'] = str(BIN) + ':' + env.get('PATH', '')
    return env


def module_env(env: dict[str, str]) -> dict[str, str]:
    out = dict(env)
    out['LD_PRELOAD'] = str(REDIRECT) + (':' + out['LD_PRELOAD'] if out.get('LD_PRELOAD') else '')
    return out


def process_alive(pid: int) -> bool:
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True


def stop_pid(pid: int | None, sig: int = signal.SIGTERM) -> None:
    if not pid:
        return
    try:
        os.kill(pid, sig)
    except ProcessLookupError:
        pass


def stop_process(proc: subprocess.Popen[bytes] | None) -> None:
    if proc is None or proc.poll() is not None:
        return
    try:
        proc.terminate()
        proc.wait(timeout=1.0)
    except Exception:
        try:
            proc.kill()
        except Exception:
            pass


def stop_group(proc: subprocess.Popen[bytes] | None) -> None:
    if proc is None or proc.poll() is not None:
        return
    try:
        os.killpg(proc.pid, signal.SIGTERM)
        proc.wait(timeout=1.0)
    except Exception:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except Exception:
            pass


def start_server(env: dict[str, str]) -> tuple[str, int, Path]:
    fd, name = tempfile.mkstemp(prefix='xavi-man-twin-', suffix='.log')
    os.close(fd)
    log_path = Path(name)
    with log_path.open('wb') as log:
        run = subprocess.run(
            [str(SERVER), '--secure', '--nohw'],
            stdout=log,
            stderr=subprocess.STDOUT,
            env=module_env(env),
            cwd=ROOT,
            timeout=8,
            check=False,
        )
    text = log_path.read_text(errors='replace')
    match = START_RE.search(text)
    if not match:
        raise RuntimeError(f'Twin server did not publish a local display.\n{text}')
    display_name, pid_text = match.groups()
    pid = int(pid_text)
    if not process_alive(pid):
        raise RuntimeError(f'Twin server exited during startup.\n{text}')
    return display_name, pid, log_path


def run_attach(env: dict[str, str]) -> int:
    if not env.get('TWDISPLAY'):
        print('xavi-man: --attach requires TWDISPLAY.', file=sys.stderr)
        return 2
    return subprocess.call([str(CLIENT)], env=env, cwd=ROOT)


def run_gui(mode: str) -> int:
    env = base_env()
    server_pid: int | None = None
    server_log: Path | None = None
    client: subprocess.Popen[bytes] | None = None
    display_proc: subprocess.Popen[bytes] | None = None
    tty_fd: int | None = None
    saved_termios = None
    original_fg: int | None = None

    # The supervisor must be able to restore foreground ownership after the
    # display process exits. Ignore job-control stop signals while supervising.
    for sig in (signal.SIGTTOU, signal.SIGTTIN, signal.SIGTSTP):
        try:
            signal.signal(sig, signal.SIG_IGN)
        except Exception:
            pass

    try:
        if mode == 'tty':
            if not sys.stdin.isatty() or not sys.stdout.isatty():
                print('xavi-man: terminal mode requires an interactive TTY.', file=sys.stderr)
                return 2
            tty_fd = os.open('/dev/tty', os.O_RDWR | os.O_NOCTTY)
            saved_termios = termios.tcgetattr(tty_fd)
            original_fg = os.tcgetpgrp(tty_fd)
        elif mode == 'x11' and not env.get('DISPLAY'):
            print('xavi-man: --x11 requires DISPLAY.', file=sys.stderr)
            return 2

        twdisplay, server_pid, server_log = start_server(env)
        env['TWDISPLAY'] = twdisplay

        client = subprocess.Popen(
            [str(CLIENT)],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.PIPE,
            env=env,
            cwd=ROOT,
        )
        time.sleep(0.20)
        if client.poll() is not None:
            err = client.stderr.read().decode(errors='replace') if client.stderr else ''
            raise RuntimeError('Xavi Twin client exited during startup.\n' + err)

        hw = 'tty' if mode == 'tty' else f"xft@{env['DISPLAY']}"
        display_env = module_env(env)
        kwargs: dict[str, object] = {
            'args': [str(DISPLAY), '-f', '--quiet', f'--hw={hw}'],
            'env': display_env,
            'cwd': ROOT,
        }
        if mode == 'tty':
            assert tty_fd is not None
            # A separate process group lets the kernel deliver all keyboard/mouse
            # terminal traffic to Twin exactly like a normal foreground TUI.
            kwargs.update(stdin=tty_fd, stdout=tty_fd, stderr=tty_fd, preexec_fn=os.setpgrp)
        else:
            kwargs.update(stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
        display_proc = subprocess.Popen(**kwargs)  # type: ignore[arg-type]

        if mode == 'tty':
            assert tty_fd is not None
            # Hand the controlling terminal to twdisplay. If it raced and got
            # SIGTTIN first, SIGCONT resumes it once it owns the foreground.
            os.tcsetpgrp(tty_fd, display_proc.pid)
            try:
                os.killpg(display_proc.pid, signal.SIGCONT)
            except ProcessLookupError:
                pass

        while True:
            c_rc = client.poll()
            d_rc = display_proc.poll()
            if c_rc is not None:
                # Clicking Exit/closing the native manager ends the physical display.
                stop_group(display_proc) if mode == 'tty' else stop_process(display_proc)
                return c_rc
            if d_rc is not None:
                # Closing the display means the management session is over.
                stop_process(client)
                if d_rc != 0 and mode != 'tty' and display_proc.stderr:
                    msg = display_proc.stderr.read().decode(errors='replace')
                    if msg:
                        print(msg, file=sys.stderr)
                return d_rc
            time.sleep(0.08)
    except KeyboardInterrupt:
        return 130
    except Exception as exc:
        print(f'xavi-man: {exc}', file=sys.stderr)
        return 1
    finally:
        if mode == 'tty' and tty_fd is not None:
            # Restore this launcher's process group before touching tty state.
            if original_fg is not None:
                try:
                    os.tcsetpgrp(tty_fd, original_fg)
                except OSError:
                    pass
            try:
                os.write(tty_fd, MOUSE_OFF)
            except OSError:
                pass
            if saved_termios is not None:
                try:
                    termios.tcsetattr(tty_fd, termios.TCSADRAIN, saved_termios)
                except OSError:
                    pass
        stop_group(display_proc) if mode == 'tty' else stop_process(display_proc)
        stop_process(client)
        stop_pid(server_pid)
        if server_pid:
            for _ in range(20):
                if not process_alive(server_pid):
                    break
                time.sleep(0.05)
            if process_alive(server_pid):
                stop_pid(server_pid, signal.SIGKILL)
        if tty_fd is not None:
            os.close(tty_fd)
        if server_log is not None:
            try:
                server_log.unlink()
            except OSError:
                pass


def main() -> int:
    parser = argparse.ArgumentParser(prog='xavi-man-twin', add_help=False)
    parser.add_argument('mode', nargs='?', default='tty', choices=['tty', 'x11', 'attach'])
    args = parser.parse_args()
    env = base_env()
    if args.mode == 'attach':
        return run_attach(env)
    return run_gui(args.mode)


if __name__ == '__main__':
    raise SystemExit(main())
PY

