<?php

namespace Application\SinglePages\XaviMan\Auth;

use Concrete\Core\User\User;
use Concrete\Core\User\UserInfo;
use RuntimeException;

defined('C5_EXECUTE') or die('Access Denied.');

final class XaviManAuth
{
    private const JWT_TTL = 300;
    private const AUDIENCE = 'xavi-man';
    private const ISSUER = 'https://xavi.app';

    private string $jwtSecret;

    public function __construct(?string $envPath = null)
    {
        $this->jwtSecret = $this->loadJwtSecret($envPath);
    }

    public function isAdmin(User $user): bool
    {
        if (!$user->isRegistered()) {
            return false;
        }
        if ($user->isSuperUser()) {
            return true;
        }
        if (!defined('ADMIN_GROUP_ID')) {
            return false;
        }
        $adminGroupId = (int) ADMIN_GROUP_ID;
        foreach ((array) $user->getUserGroups() as $key => $value) {
            if ((int) $key === $adminGroupId || (int) $value === $adminGroupId) {
                return true;
            }
        }
        return false;
    }

    public function identity(User $user): ?array
    {
        if (!$this->isAdmin($user)) {
            return null;
        }
        $userInfo = $user->getUserInfoObject();
        if (!$userInfo instanceof UserInfo) {
            return null;
        }
        return [
            'siteUserId' => (int) $userInfo->getUserID(),
            'siteUsername' => (string) $userInfo->getUserName(),
            'email' => (string) $userInfo->getUserEmail(),
            'admin' => true,
        ];
    }

    public function issueToken(UserInfo $userInfo): array
    {
        $now = time();
        $expiresAt = $now + self::JWT_TTL;
        $header = $this->base64url((string) json_encode(['alg' => 'HS256', 'typ' => 'JWT'], JSON_UNESCAPED_SLASHES));
        $claims = [
            'iss' => self::ISSUER,
            'aud' => self::AUDIENCE,
            'sub' => 'ccu-' . (int) $userInfo->getUserID(),
            'uid' => (int) $userInfo->getUserID(),
            'username' => (string) $userInfo->getUserName(),
            'email' => (string) $userInfo->getUserEmail(),
            'admin' => true,
            'scope' => ['xavi-man:read', 'xavi-man:control'],
            'iat' => $now,
            'nbf' => $now - 2,
            'exp' => $expiresAt,
            'jti' => bin2hex(random_bytes(16)),
        ];
        $payload = $this->base64url((string) json_encode($claims, JSON_UNESCAPED_SLASHES));
        $signature = $this->base64url(hash_hmac('sha256', $header . '.' . $payload, $this->jwtSecret, true));
        return ['token' => $header . '.' . $payload . '.' . $signature, 'expiresAt' => $expiresAt, 'claims' => $claims];
    }

    private function loadJwtSecret(?string $envPath): string
    {
        $secret = (string) (getenv('XAVI_MAN_JWT_SECRET') ?: getenv('HOVOD_JWT_SECRET') ?: '');
        if ($secret !== '') {
            return $secret;
        }
        $envFile = $envPath ?: dirname(DIR_BASE) . '/srnn_server/havod/.env';
        if (is_file($envFile)) {
            foreach (file($envFile, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) ?: [] as $line) {
                $line = trim($line);
                if ($line === '' || $line[0] === '#' || strpos($line, '=') === false) {
                    continue;
                }
                [$key, $value] = explode('=', $line, 2);
                if (trim($key) === 'JWT_SECRET') {
                    $secret = trim(trim($value), "\"'");
                    break;
                }
            }
        }
        if ($secret === '') {
            throw new RuntimeException('xavi-man JWT secret is unavailable');
        }
        return $secret;
    }

    private function base64url(string $value): string
    {
        return rtrim(strtr(base64_encode($value), '+/', '-_'), '=');
    }
}
