defined('C5_EXECUTE') or die('Access Denied.');

require_once DIR_APPLICATION . '/single_pages/xavi_man/auth/XaviManAuth.php';

final class XaviMan extends PageController
{
    public function auth_check()
    {
        $rf = $this->app->make(ResponseFactory::class);
        $user = new User();
        if (!$user->isRegistered()) {
            return $rf->create('', 401, ['Cache-Control' => 'no-store']);
        }
        $auth = new XaviManAuth();
        $identity = $auth->identity($user);
        if (!$identity) {
            return $rf->create('', 403, ['Cache-Control' => 'no-store']);
        }
        $response = $rf->create('', 204);
        $response->headers->set('Cache-Control', 'no-store');
        $response->headers->set('X-Xavi-Man-User-Id', (string) $identity['siteUserId']);
        $response->headers->set('X-Xavi-Man-User-Name', (string) $identity['siteUsername']);
        $response->headers->set('X-Xavi-Man-User-Email', (string) $identity['email']);
        $response->headers->set('X-Xavi-Man-Admin', '1');
        return $response;
    }

    public function session_token()
