from __future__ import annotations

import json
import os
import re
import shutil
import socket
import subprocess
import threading
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Iterable


class StackError(RuntimeError):
    pass


XAVI_ROOT = Path("/var/www/xavi")
SAFE_TARGET = re.compile(r"^[A-Za-z0-9_.@:+-]+$")
COMPOSE_NAMES = ("compose.yml", "compose.yaml", "podman-compose.yml", "docker-compose.yml", "docker-compose.yaml")


def _run(argv: Iterable[str], *, timeout: int = 12, cwd: Path | None = None) -> dict[str, Any]:
    command = [str(part) for part in argv]
    started = time.monotonic()
    try:
        proc = subprocess.run(
            command,
            cwd=str(cwd) if cwd else None,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
            check=False,
        )
        return {
            "argv": command,
            "returncode": proc.returncode,
            "stdout": proc.stdout,
            "stderr": proc.stderr,
            "elapsed_ms": round((time.monotonic() - started) * 1000, 1),
        }
    except FileNotFoundError:
        return {"argv": command, "returncode": 127, "stdout": "", "stderr": f"command not found: {command[0]}", "elapsed_ms": 0}
    except subprocess.TimeoutExpired as exc:
        return {"argv": command, "returncode": 124, "stdout": exc.stdout or "", "stderr": f"timeout after {timeout}s", "elapsed_ms": round((time.monotonic() - started) * 1000, 1)}


def _json_output(result: dict[str, Any], default: Any) -> Any:
    if result.get("returncode") != 0:
        return default
    try:
        return json.loads(result.get("stdout") or "")
    except Exception:
        return default


class XaviBackend:
    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._cache: tuple[float, dict[str, Any]] | None = None

    def invalidate(self) -> None:
        with self._lock:
            self._cache = None

    def _identity(self) -> dict[str, Any]:
        info = _json_output(_run(["podman", "info", "--format", "json"], timeout=8), {})
        store = info.get("store", {}) if isinstance(info, dict) else {}
        host = info.get("host", {}) if isinstance(info, dict) else {}
        return {
            "user": os.environ.get("USER") or "tbi",
            "uid": os.getuid(),
            "rootless": os.geteuid() != 0,
            "hostname": socket.gethostname(),
            "graph_root": store.get("graphRoot") or store.get("graphroot") or "-",
            "podman_version": ((info.get("version") or {}).get("Version") if isinstance(info.get("version"), dict) else info.get("version")) if isinstance(info, dict) else None,
            "cgroup_version": host.get("cgroupVersion") if isinstance(host, dict) else None,
        }

    def _containers(self) -> tuple[list[dict[str, Any]], str | None]:
        result = _run(["podman", "ps", "-a", "--format", "json"], timeout=12)
        data = _json_output(result, None)
        if not isinstance(data, list):
            return [], result.get("stderr") or "Podman inventory unavailable"
        rows: list[dict[str, Any]] = []
        for entry in data:
            if not isinstance(entry, dict):
                continue
            names = entry.get("Names") or entry.get("names") or entry.get("Name") or entry.get("name") or []
            if isinstance(names, list):
                name = names[0] if names else "-"
            else:
                name = str(names)
            state = entry.get("State") or entry.get("state") or "unknown"
            status = entry.get("Status") or entry.get("status") or state
            health = entry.get("Health") or entry.get("health") or entry.get("HealthStatus") or "-"
            rows.append({
                "name": name,
                "id": entry.get("Id") or entry.get("ID") or entry.get("id"),
                "image": entry.get("Image") or entry.get("image"),
                "state": state,
                "status": status,
                "details": {"state": state, "status": status, "health": health},
            })
        rows.sort(key=lambda row: str(row.get("name", "")))
        return rows, None

    def _services(self) -> tuple[list[dict[str, Any]], str | None]:
        result = _run(["systemctl", "--user", "list-units", "--type=service", "--all", "--no-legend", "--no-pager", "--plain"], timeout=10)
        if result.get("returncode") != 0:
            return [], result.get("stderr") or "user systemd unavailable"
        rows: list[dict[str, Any]] = []
        for raw in (result.get("stdout") or "").splitlines():
            line = raw.strip()
            if not line:
                continue
            parts = line.split(None, 4)
            if len(parts) < 4:
                continue
            unit, load, active, sub = parts[:4]
            desc = parts[4] if len(parts) > 4 else ""
            rows.append({"scope": "user", "name": unit, "load": load, "active": active, "sub": sub, "description": desc})
        rows.sort(key=lambda row: row["name"])
        return rows, None

    def _projects(self) -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        try:
            entries = sorted(XAVI_ROOT.iterdir(), key=lambda p: p.name.lower())
        except OSError:
            return rows
        for path in entries:
            if not path.is_dir() or path.name.startswith("."):
                continue
            compose = next((path / name for name in COMPOSE_NAMES if (path / name).is_file()), None)
            if compose is None:
                continue
            rows.append({"id": path.name, "name": path.name, "path": str(path), "compose": str(compose), "state": "discovered"})
        return rows

    def _filesystems(self) -> list[dict[str, Any]]:
        result = _run(["df", "-P", "-B1"], timeout=8)
        rows: list[dict[str, Any]] = []
        for line in (result.get("stdout") or "").splitlines()[1:]:
            parts = line.split()
            if len(parts) < 6:
                continue
            fs, blocks, used, available, use_pct = parts[:5]
            mount = " ".join(parts[5:])
            if mount.startswith(("/var/www/xavi", "/datastore", "/home", "/")) or mount == "/":
                rows.append({"filesystem": fs, "bytes": int(blocks), "used": int(used), "available": int(available), "use_percent": use_pct, "mount": mount})
        return rows

    def _listeners(self) -> list[dict[str, Any]]:
        result = _run(["ss", "-ltnH"], timeout=8)
        rows: list[dict[str, Any]] = []
        for line in (result.get("stdout") or "").splitlines():
            parts = line.split()
            if len(parts) >= 4:
                rows.append({"state": parts[0], "local": parts[3]})
        return rows

    def _doctor(self, *, podman_error: str | None, service_error: str | None, containers: list[dict[str, Any]]) -> dict[str, Any]:
        issues: list[str] = []
        warnings: list[str] = []
        if podman_error:
            issues.append(f"Podman: {podman_error.strip()}")
        if service_error:
            issues.append(f"user systemd: {service_error.strip()}")
        unhealthy = [row["name"] for row in containers if str((row.get("details") or {}).get("health", "-")).lower() in {"unhealthy", "starting"}]
        if unhealthy:
            warnings.append("container health: " + ", ".join(unhealthy[:12]))
        return {
            "ok": not issues,
            "issue_count": len(issues),
            "warning_count": len(warnings),
            "issues": issues,
            "warnings": warnings,
        }

    def state(self, *, max_age: float = 2.0) -> dict[str, Any]:
        now = time.monotonic()
        with self._lock:
            if self._cache and now - self._cache[0] <= max_age:
                return self._cache[1]
        containers, podman_error = self._containers()
        services, service_error = self._services()
        projects = self._projects()
        payload = {
            "schema_version": 2,
            "operation": "xavi-man.state",
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "identity": self._identity(),
            "containers": containers,
            "services": services,
            "projects": projects,
            "remote_nodes": [],
            "filesystems": self._filesystems(),
            "listeners": self._listeners(),
            "doctor": self._doctor(podman_error=podman_error, service_error=service_error, containers=containers),
        }
        with self._lock:
            self._cache = (time.monotonic(), payload)
        return payload

    def resources(self) -> dict[str, Any]:
        mem: dict[str, int] = {}
        try:
            for line in Path("/proc/meminfo").read_text().splitlines():
                if ":" not in line:
                    continue
                key, value = line.split(":", 1)
                amount = value.strip().split()[0]
                if amount.isdigit():
                    mem[key] = int(amount) * 1024
        except OSError:
            pass
        load1, load5, load15 = os.getloadavg()
        return {
            "schema_version": 1,
            "operation": "xavi-man.resources",
            "cpu_count": os.cpu_count(),
            "load_average": [load1, load5, load15],
            "memory_total": mem.get("MemTotal"),
            "memory_available": mem.get("MemAvailable"),
            "filesystems": self._filesystems(),
        }

    def contract(self) -> dict[str, Any]:
        candidates = [XAVI_ROOT / "Duotronics", XAVI_ROOT / "Witness-Contract"]
        existing = [str(path) for path in candidates if path.exists()]
        return {"schema_version": 1, "operation": "xavi-man.contract", "available": bool(existing), "paths": existing}

    def advisor_status(self) -> dict[str, Any]:
        resources = self.resources()
        cpu = max(int(resources.get("cpu_count") or 1), 1)
        load1 = float((resources.get("load_average") or [0])[0])
        ratio = load1 / cpu
        return {
            "schema_version": 1,
            "operation": "xavi-man.advisor",
            "cpu_load_ratio": ratio,
            "recommendation": "high host load" if ratio > 1.0 else "capacity available" if ratio < 0.65 else "moderate host load",
        }

    def _safe_target(self, target: str) -> str:
        target = target.strip()
        if not target or not SAFE_TARGET.fullmatch(target):
            raise StackError("invalid management target")
        return target

    def logs(self, target: str, lines: int = 200) -> dict[str, Any]:
        target = self._safe_target(target)
        lines = max(1, min(int(lines), 1000))
        container_names = {row["name"] for row in self._containers()[0]}
        if target in container_names:
            result = _run(["podman", "logs", "--tail", str(lines), target], timeout=15)
        else:
            result = _run(["journalctl", "--user", "-u", target, "-n", str(lines), "--no-pager"], timeout=15)
        return {"target": target, "returncode": result["returncode"], "stdout": result["stdout"], "stderr": result["stderr"]}

    def _project_path(self, target: str) -> Path:
        target = self._safe_target(target)
        projects = {row["id"]: Path(row["path"]) for row in self._projects()}
        path = projects.get(target)
        if path is None:
            raise StackError(f"unknown Xavi project: {target}")
        return path

    def _project_commands(self, verb: str, target: str) -> tuple[Path, list[list[str]]]:
        path = self._project_path(target)
        if shutil.which("podman-compose"):
            prefix = ["podman-compose"]
        else:
            prefix = ["podman", "compose"]
        if verb == "start":
            commands = [prefix + ["up", "-d"]]
        elif verb == "stop":
            commands = [prefix + ["down"]]
        elif verb == "restart":
            commands = [prefix + ["down"], prefix + ["up", "-d"]]
        else:
            raise StackError(f"unsupported project action: {verb}")
        return path, commands

    def action(self, *, kind: str, verb: str, target: str, apply: bool = False) -> dict[str, Any]:
        kind = kind.strip().lower()
        verb = verb.strip().lower()
        allowed = {
            "container": {"start", "stop", "restart"},
            "service": {"start", "stop", "restart", "enable", "disable"},
            "project": {"start", "stop", "restart"},
        }
        if kind not in allowed or verb not in allowed[kind]:
            raise StackError(f"unsupported xavi-man action: {kind}/{verb}")
        target = self._safe_target(target)

        if kind == "container":
            commands = [["podman", verb, target]]
            cwd = None
        elif kind == "service":
            commands = [["systemctl", "--user", verb, target]]
            cwd = None
        else:
            cwd, commands = self._project_commands(verb, target)

        preview = {"kind": kind, "verb": verb, "target": target, "apply": apply, "cwd": str(cwd) if cwd else None, "commands": commands}
        if not apply:
            return {"preview": preview, "applied": False}

        results = [_run(command, timeout=60, cwd=cwd) for command in commands]
        failed = [result for result in results if result.get("returncode") != 0]
        if failed:
            raise StackError(f"operation failed: {failed[-1].get('stderr') or failed[-1].get('stdout')}")
        self.invalidate()
        return {"preview": preview, "applied": True, "results": results}
