<?php
namespace Concrete\Package\ConcreteJwtSso\Src;

use Concrete\Core\User\User;
use InvalidArgumentException;
use RuntimeException;

class JwtService
{
    private string $secret;
    private int $ttl;

    public function __construct(string $secret, int $ttl = 3600)
    {
        if ($secret === '') {
            throw new InvalidArgumentException('JWT signing secret is not configured.');
        }
        $this->secret = $secret;
        $this->ttl = max(60, $ttl);
    }

    public function generateToken(User $user): string
    {
        $now = time();
        $host = strtolower((string) ($_SERVER['HTTP_HOST'] ?? 'xavi.app'));
        $host = preg_replace('/:\\d+$/', '', $host) ?: 'xavi.app';
        $payload = [
            'sub' => (string) $user->getUserID(),
            'email' => (string) $user->getUserEmail(),
            'username' => (string) $user->getUserName(),
            'iat' => $now,
            'exp' => $now + $this->ttl,
            'iss' => 'https://' . $host,
            'aud' => 'external-apps',
        ];
        return $this->encode($payload);
    }

    public function verifyToken(string $token, array $allowedIssuers): array
    {
        $parts = explode('.', trim($token));
        if (count($parts) !== 3) {
            throw new RuntimeException('Malformed JWT.');
        }
        [$encodedHeader, $encodedPayload, $encodedSignature] = $parts;
        $header = json_decode($this->base64UrlDecode($encodedHeader), true);
        $payload = json_decode($this->base64UrlDecode($encodedPayload), true);
        if (!is_array($header) || !is_array($payload) || ($header['alg'] ?? null) !== 'HS256') {
            throw new RuntimeException('Unsupported JWT.');
        }
        $expected = $this->base64UrlEncode(hash_hmac('sha256', $encodedHeader . '.' . $encodedPayload, $this->secret, true));
        if (!hash_equals($expected, $encodedSignature)) {
            throw new RuntimeException('Invalid JWT signature.');
        }
        $now = time();
        if (!isset($payload['exp']) || !is_numeric($payload['exp']) || (int) $payload['exp'] <= $now) {
            throw new RuntimeException('JWT expired.');
        }
        if (!isset($payload['iat']) || !is_numeric($payload['iat']) || (int) $payload['iat'] > ($now + 60)) {
            throw new RuntimeException('Invalid JWT issue time.');
        }
        if (($payload['aud'] ?? null) !== 'external-apps') {
            throw new RuntimeException('Invalid JWT audience.');
        }
        $issuer = (string) ($payload['iss'] ?? '');
        if ($issuer === '' || !in_array($issuer, $allowedIssuers, true)) {
            throw new RuntimeException('Invalid JWT issuer.');
        }
        if ((string) ($payload['sub'] ?? '') === '' || (string) ($payload['username'] ?? '') === '') {
            throw new RuntimeException('JWT is missing identity claims.');
        }
        return $payload;
    }

    private function encode(array $payload): string
    {
        $header = ['typ' => 'JWT', 'alg' => 'HS256'];
        $encodedHeader = $this->base64UrlEncode(json_encode($header, JSON_UNESCAPED_SLASHES));
        $encodedPayload = $this->base64UrlEncode(json_encode($payload, JSON_UNESCAPED_SLASHES));
        $signature = hash_hmac('sha256', $encodedHeader . '.' . $encodedPayload, $this->secret, true);
        return $encodedHeader . '.' . $encodedPayload . '.' . $this->base64UrlEncode($signature);
    }

    private function base64UrlEncode(string $data): string
    {
        return rtrim(strtr(base64_encode($data), '+/', '-_'), '=');
    }

    private function base64UrlDecode(string $data): string
    {
        $padding = strlen($data) % 4;
        if ($padding) {
            $data .= str_repeat('=', 4 - $padding);
        }
        $decoded = base64_decode(strtr($data, '-_', '+/'), true);
        if ($decoded === false) {
            throw new RuntimeException('Invalid base64url data.');
        }
        return $decoded;
    }
}
