<?php
namespace Concrete\Package\ConcreteJwtSso\Controller\Api;

use Concrete\Core\Controller\AbstractController;
use Concrete\Core\User\User;
use Concrete\Package\ConcreteJwtSso\Src\JwtService;
use Symfony\Component\HttpFoundation\JsonResponse;
use Throwable;

class Jwt extends AbstractController
{
    private function service(): JwtService
    {
        $config = $this->app->make('config');
        return new JwtService((string) $config->get('jwt_sso.secret', ''), (int) $config->get('jwt_sso.ttl', 3600));
    }

    private function allowedIssuers(): array
    {
        $config = $this->app->make('config');
        $issuers = $config->get('jwt_sso.allowed_issuers', []);
        if (!is_array($issuers) || !$issuers) {
            $issuers = [
                'https://xavi.app',
                'https://www.xavi.app',
                'https://princegeorge.app',
                'https://www.princegeorge.app',
            ];
        }
        return array_values(array_unique(array_map('strval', $issuers)));
    }

    public function get()
    {
        $user = new User();
        if (!$user->isLoggedIn()) {
            return new JsonResponse(['error' => 'Unauthenticated'], 401);
        }
        try {
            return new JsonResponse(['token' => $this->service()->generateToken($user)]);
        } catch (Throwable $e) {
            error_log('Concrete JWT SSO token issue failed: ' . $e->getMessage());
            return new JsonResponse(['error' => 'Token service unavailable'], 503);
        }
    }

    public function verify()
    {
        $input = json_decode((string) file_get_contents('php://input'), true);
        $token = is_array($input) ? trim((string) ($input['token'] ?? '')) : '';
        if ($token === '') {
            $authorization = (string) ($_SERVER['HTTP_AUTHORIZATION'] ?? $_SERVER['REDIRECT_HTTP_AUTHORIZATION'] ?? '');
            if (stripos($authorization, 'Bearer ') === 0) {
                $token = trim(substr($authorization, 7));
            }
        }
        if ($token === '') {
            return new JsonResponse(['valid' => false, 'error' => 'Missing token'], 400);
        }
        try {
            $claims = $this->service()->verifyToken($token, $this->allowedIssuers());
            return new JsonResponse([
                'valid' => true,
                'user' => [
                    'id' => (string) $claims['sub'],
                    'email' => (string) ($claims['email'] ?? ''),
                    'username' => (string) $claims['username'],
                ],
                'issuer' => (string) $claims['iss'],
                'audience' => (string) $claims['aud'],
                'issued_at' => (int) $claims['iat'],
                'expires_at' => (int) $claims['exp'],
            ]);
        } catch (Throwable $e) {
            return new JsonResponse(['valid' => false, 'error' => 'Invalid token'], 401);
        }
    }
}
