def runtime_mcp_tools() -> list[dict[str, Any]]:
    try:
        response = runtime_mcp_rpc("tools/list", {}, timeout=10)
        tools = response.get("result", {}).get("tools", [])
        if isinstance(tools, list):
            return tools
    except Exception:
        return []
    return []


def merged_tools() -> list[dict[str, Any]]:
    seen: set[str] = set()
    merged: list[dict[str, Any]] = []
    for tool in TOOLS + runtime_mcp_tools():
        name = tool.get("name") if isinstance(tool, dict) else None
        if not name or name in seen:
            continue
        seen.add(name)
        normalized = dict(tool)
        # Adapter uses MCP inputSchema; runtime uses inputSchema too via mcp_protocol.
        if "input_schema" in normalized and "inputSchema" not in normalized:
            normalized["inputSchema"] = normalized.pop("input_schema")
        merged.append(normalized)
    return merged


def runtime_mcp_tool_call(name: str, args: dict[str, Any]) -> Any:
    response = runtime_mcp_rpc("tools/call", {"name": name, "arguments": args}, timeout=120)
    if "error" in response:
        raise RuntimeError(json.dumps(response["error"], sort_keys=True))
    result = response.get("result", {})
    if isinstance(result, dict) and "structuredContent" in result:
        return result["structuredContent"]
    return result
