# save/load dimension-aware v2 layout
pat=r'''static void save_layout\(void\) \{.*?\n\}\n\nstatic void load_layout\(void\) \{.*?\n\}'''
rep=r'''static void save_layout(void) {
  FILE *f;
  int i;
  char dir[512], *slash;
  snprintf(dir, sizeof(dir), "%s", layout_path);
  slash = strrchr(dir, '/');
  if (slash) { *slash = 0; mkdir(dir, 0755); }
  f = fopen(layout_path, "w");
  if (!f) return;
  fprintf(f, "# xavi-man-layout-v2 %d %d\n", desktop_w, desktop_h);
  for (i = 0; i < MAX_ICONS; ++i) fprintf(f, "%d\t%d\t%d\n", icons[i].code, icons[i].x, icons[i].y);
  fclose(f);
  layout_saved_w = desktop_w;
  layout_saved_h = desktop_h;
}

static void load_layout(void) {
  FILE *f = fopen(layout_path, "r");
  char line[256];
  if (!f) return;
  while (fgets(line, sizeof(line), f)) {
    int code, x, y, w, h;
    if (sscanf(line, "# xavi-man-layout-v2 %d %d", &w, &h) == 2) {
      layout_saved_w = w; layout_saved_h = h; continue;
    }
    if (sscanf(line, "%d\t%d\t%d", &code, &x, &y) == 3) {
      DesktopIcon *ic = icon_by_code(code);
      if (ic) { ic->x = x; ic->y = y; }
    }
  }
  fclose(f);
}'''
