rep=r'''static void arrange_icons(void) {
  int i;
  int step_x = ICON_W + 2;
  int step_y = desktop_h < 22 ? 2 : 4;
  int cols = (desktop_w - 4) / step_x;
  if (cols < 1) cols = 1;
  if (cols > MAX_ICONS) cols = MAX_ICONS;
  for (i = 0; i < MAX_ICONS; ++i) {
    int col = i % cols, row = i / cols;
    int y = 3 + row * step_y;
    if (y > taskbar_y - ICON_H - 1) y = taskbar_y - ICON_H - 1;
    if (y < 2) y = 2;
    icons[i].x = 2 + col * step_x;
    icons[i].y = y;
    if (icons[i].gadget) TwSetXYGadget(icons[i].gadget, icons[i].x, icons[i].y);
  }
  save_layout();
  TwFlush();
}'''
