# geometry helper + main builder
pat=r'''static void build_main\(void\) \{.*?\n\}\n\nstatic void handle_main_code'''
rep=r'''static void read_screen_geometry(void) {
  tany sw = TwStat(TwFirstScreen(), TWS_screen_XWidth);
  tany sh = TwStat(TwFirstScreen(), TWS_screen_YWidth);
  desktop_w = (int)sw;
  desktop_h = (int)sh;
  if (desktop_w < 40) desktop_w = 40;
  if (desktop_h < 14) desktop_h = 14;
  taskbar_y = desktop_h - 2;
}

static int layout_fits_screen(void) {
  int i;
  if (layout_saved_w != desktop_w || layout_saved_h != desktop_h) return 0;
  for (i = 0; i < MAX_ICONS; ++i) {
    if (icons[i].x < 1 || icons[i].y < 2 ||
        icons[i].x + ICON_W >= desktop_w ||
        icons[i].y + ICON_H >= taskbar_y) return 0;
  }
  return 1;
}

static void write_clipped(twindow w, int x, int y, const char *text, int maxw) {
  int n = (int)strlen(text);
  if (maxw < 0) return;
  if (n > maxw) n = maxw;
  if (n <= 0) return;
  TwGotoXYWindow(w, x, y);
  TwWriteCharsetWindow(w, n, text);
}

static void draw_separator(twindow w, int y) {
  char *line;
  int n = desktop_w;
  if (n < 1) return;
  line = malloc((size_t)n);
  if (!line) return;
  memset(line, '_', (size_t)n);
  TwGotoXYWindow(w, 0, y);
  TwWriteCharsetWindow(w, n, line);
  free(line);
}

static void build_main(void) {
  const char *title = "Xavi Manager";
  time_t now = time(NULL);
  struct tm tmv;
  char clockbuf[32];
  read_screen_geometry();
  main_win = TwCreateWindow(strlen(title), title, NULL, main_menu,
      TCOL(tblack,twhite), TW_LINECURSOR,
      TW_WINDOW_WANT_KEYS | TW_WINDOW_WANT_MOUSE | TW_WINDOW_WANT_MOUSE_MOTION | TW_WINDOW_WANT_CHANGES,
      TW_WINDOWFL_BORDERLESS | TW_WINDOWFL_ROWS_DEFCOL, desktop_w, desktop_h, 0);
  if (!main_win) return;
  TwSetColorsWindow(main_win, (1 << 6), (tcolor)0, (tcolor)0, (tcolor)0, (tcolor)0, (tcolor)0, (tcolor)0,
                    TCOL((thigh|twhite),tblue), (tcolor)0, (tcolor)0);
  TwSetXYWindow(main_win, 0, 0);
  write_clipped(main_win, 2, 0, "XAVI BACKEND OPERATIONS DESKTOP", desktop_w - 4);
  if (desktop_h >= 20)
    write_clipped(main_win, 2, 1, "Click an icon to open it. Right-click for options. Drag icons to arrange the desktop.", desktop_w - 4);
  create_desktop_icons();
  if (!layout_fits_screen()) arrange_icons();

  draw_separator(main_win, taskbar_y - 1);
  start_gadget = TwCreateButtonGadget(main_win, 8, 1, " Start ", 0, CODE_START,
      TCOL(tblack,twhite),TCOL(twhite,tblue),TCOL((thigh|twhite),tblue),1,taskbar_y);
  tasks_gadget = TwCreateButtonGadget(main_win, 8, 1, " Tasks ", 0, CODE_TASKS,
      TCOL(tblack,twhite),TCOL(twhite,tblue),TCOL((thigh|twhite),tblue),9,taskbar_y);
  localtime_r(&now, &tmv);
  strftime(clockbuf, sizeof(clockbuf), "%H:%M", &tmv);
  write_clipped(main_win, desktop_w > 8 ? desktop_w - 7 : 1, taskbar_y, clockbuf, 5);
  if (desktop_h >= 18)
    write_clipped(main_win, 2, taskbar_y + 1, "Allowlisted controls. Mutations require preview + Apply.", desktop_w - 4);

  TwMapWindow(main_win, TwFirstScreen());
  TwRaiseWindow(main_win);
  rebuild_taskbar();
  TwFlush();
}

