cat > "$PLAY" <<'JS'
class SrnnManagerPlaying extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._state = { nowPlaying: null, status: 'Loading backend player…', error: false, busy: false };
    this._timer = null;
  }

  connectedCallback() {
    this._srnnApi = this.getAttribute('srnn-api') || window.srnnApiUrl || '/rnn_chat/srnn_api';
    this._render();
    this.shadowRoot.addEventListener('click', (event) => this._onClick(event));
    this._load();
    this._timer = setInterval(() => this._load(), 8000);
  }

  disconnectedCallback() {
    if (this._timer) clearInterval(this._timer);
    this._timer = null;
  }

  async _fetchJson(url, options) {
    let resp;
    try {
      resp = await fetch(url, options);
    } catch (err) {
      if (url.startsWith('/') && !url.startsWith('/index.php/')) resp = await fetch(`/index.php${url}`, options);
      else throw err;
    }
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    return resp.json();
  }

  _postJson(url, payload) {
    return this._fetchJson(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify(payload),
    });
  }

  _normalize(raw) {
    const data = raw && typeof raw === 'object' ? raw : {};
    const canonical = data.now_playing && typeof data.now_playing === 'object' ? data.now_playing : {};
    const info = data.track_info && typeof data.track_info === 'object' ? data.track_info : {};
    const currentTrack = Number(canonical.track_number || data.current_track || data.track_number || 0) || 0;
    const duration = Number(canonical.duration_seconds || data.server_track_duration_seconds || info.duration || 0) || 0;
    const elapsed = Math.max(0, Number(canonical.elapsed_seconds || data.server_elapsed_seconds || 0) || 0);
    const progress = duration > 0 ? Math.max(0, Math.min(100, (elapsed / duration) * 100)) : 0;
    const rawUpcoming = Array.isArray(data.queue?.upcoming) ? data.queue.upcoming : (Array.isArray(data.upcoming) ? data.upcoming : []);
    const upcoming = rawUpcoming.map((row, index) => {
      const track = Number(row?.track_number || row?.track || 0) || 0;
      if (!track) return null;
      return {
        track_number: track,
        queue_index: Number(row?.queue_index || index + 1) || index + 1,
        title: String(row?.title || `Track ${track}`),
        artist: String(row?.artist || ''),
        genre: String(row?.genre || ''),
        video_id: String(row?.video_id || ''),
      };
    }).filter(Boolean);
    return {
      current_track: currentTrack,
      current_position: Number(data.current_position || 0) || 0,
      total_tracks: Number(data.total_tracks || 0) || 0,
      arrangement_name: String(data.arrangement_name || ''),
      epoch: Number(data.epoch || 0) || 0,
      title: String(canonical.title || info.title || (currentTrack ? `Track ${currentTrack}` : 'No active track')),
      artist: String(canonical.artist || info.artist || ''),
      genre: String(canonical.genre || info.genre || ''),
      video_id: String(canonical.video_id || info.video_id || ''),
      elapsed_seconds: elapsed,
      duration_seconds: duration,
      progress_pct: progress,
      upcoming,
      queue_health: data.queue_health || data.queue || {},
    };
  }

  async _load() {
    try {
      const raw = await this._fetchJson(`${this._srnnApi}?action=now-playing&upcoming=8`);
      this._state.nowPlaying = this._normalize(raw);
      this._state.status = 'Backend player is live.';
      this._state.error = false;
    } catch (err) {
      this._state.status = err?.message || 'Failed to load backend player.';
      this._state.error = true;
    }
    this._render();
  }

  async _command(action, trackNumber = 0) {
    try {
      this._state.busy = true;
      this._state.status = 'Sending playback command…';
      this._state.error = false;
      this._render();
      if (action === 'previous') await this._postJson(this._srnnApi, { action: 'session-previous' });
      else if (action === 'next') await this._postJson(this._srnnApi, { action: 'session-skip' });
      else if (action === 'play-track' && trackNumber > 0) await this._postJson(this._srnnApi, { action: 'session-skip', track_number: trackNumber, fast: 1 });
      await this._load();
      this._state.status = 'Playback command applied.';
    } catch (err) {
      this._state.status = err?.message || 'Playback command failed.';
      this._state.error = true;
    } finally {
      this._state.busy = false;
      this._render();
    }
  }

  _onClick(event) {
    if (this._state.busy) return;
    const target = event.target.closest('[data-action]');
    if (!target) return;
    const action = target.getAttribute('data-action');
    if (action === 'previous' || action === 'next') return this._command(action);
    if (action === 'play-track') {
      const input = this.shadowRoot.getElementById('track-input');
      const track = Number(input?.value || 0) || 0;
      if (track > 0) this._command('play-track', track);
    }
    if (action === 'play-upcoming') {
      const track = Number(target.getAttribute('data-track') || 0) || 0;
      if (track > 0) this._command('play-track', track);
    }
  }

  _escape(value) {
    return String(value ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
  }

  _time(value) {
    const sec = Math.max(0, Math.round(Number(value || 0)));
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return `${m}:${String(s).padStart(2, '0')}`;
  }

