    collaboration = board.get("_collaboration") if isinstance(board.get("_collaboration"), dict) else {}

    def rows(*keys: str) -> list[Any]:
        for source in (board, collaboration):
            if not isinstance(source, dict):
                continue
            for key in keys:
                value = source.get(key)
                if isinstance(value, list):
                    return value
        return []

    def slim(items: list[Any], fields: tuple[str, ...], limit: int) -> list[dict[str, Any]]:
        output: list[dict[str, Any]] = []
        for item in items[:limit]:
            if not isinstance(item, dict):
                continue
            row = {key: item.get(key) for key in fields if item.get(key) not in (None, "", [], {})}
            if row:
                output.append(row)
        return output

    compact = {
