  const base = location.pathname.endsWith("/") ? location.pathname : location.pathname + "/";
  const desktop = document.getElementById("desktop");
  const grid = document.getElementById("icon-grid");
  const connection = document.getElementById("connection-status");
  const summary = document.getElementById("summary-status");
  const template = document.getElementById("window-template");
  let state = null;
  let topZ = 20;
  const openWindows = new Map();

  const apps = [
    ["overview","▣","Overview"],["containers","▤","Containers"],["services","⚙","Services"],
    ["projects","▦","Projects"],["remote","⇄","Remote Nodes"],["storage","▥","Storage"],
    ["doctor","✓","Doctor"],["resources","◇","WG-RNN Resources"],["advisor","◎","AI Advisor"],
    ["contract","W","Witness Contract"],["about","?","About Xavi-Man"]
  ];

  function esc(value){return String(value ?? "").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));}
  function json(value){return `<pre>${esc(JSON.stringify(value,null,2))}</pre>`;}
  function setSummary(s){
    if(!s)return;
    const d=s.doctor||{};
    summary.textContent=`${(s.containers||[]).length} containers · ${(s.services||[]).length} services · ${(s.projects||[]).length} projects · doctor ${d.ok?"PASS":"ATTENTION"}`;
  }

  function createIcon([id,glyph,label]){
    const b=document.createElement("button");b.className="program-icon";b.dataset.app=id;
    b.innerHTML=`<span class="glyph">${esc(glyph)}</span><span class="label">${esc(label)}</span>`;
    b.addEventListener("dblclick",()=>openApp(id));b.addEventListener("click",()=>{b.focus();});
    b.addEventListener("keydown",e=>{if(e.key==="Enter")openApp(id);});
    return b;
  }
  apps.forEach(a=>grid.appendChild(createIcon(a)));

  function focusWindow(win){document.querySelectorAll(".child-window").forEach(w=>w.classList.remove("active"));win.classList.add("active");win.style.zIndex=String(++topZ);}
  function makeDraggable(win){
    const bar=win.querySelector(".draggable");let dragging=false,dx=0,dy=0;
    bar.addEventListener("pointerdown",e=>{if(e.target.closest("button"))return;dragging=true;focusWindow(win);dx=e.clientX-win.offsetLeft;dy=e.clientY-win.offsetTop;bar.setPointerCapture(e.pointerId);});
    bar.addEventListener("pointermove",e=>{if(!dragging)return;const maxX=desktop.clientWidth-win.offsetWidth,maxY=desktop.clientHeight-win.offsetHeight;win.style.left=Math.max(0,Math.min(maxX,e.clientX-dx))+"px";win.style.top=Math.max(0,Math.min(maxY,e.clientY-dy))+"px";});
    bar.addEventListener("pointerup",()=>dragging=false);win.addEventListener("pointerdown",()=>focusWindow(win));
  }

  function windowFor(id,title){
    if(openWindows.has(id)){const existing=openWindows.get(id);focusWindow(existing);return existing;}
    const win=template.content.firstElementChild.cloneNode(true);win.dataset.id=id;win.querySelector(".window-title").textContent=title;
    win.querySelector(".close-button").addEventListener("click",()=>{openWindows.delete(id);win.remove();});
    win.querySelector(".window-refresh").addEventListener("click",()=>renderApp(id,win));
    desktop.appendChild(win);openWindows.set(id,win);makeDraggable(win);focusWindow(win);return win;
  }

  async function action(kind,verb,target,win){
    const status=win.querySelector(".window-status");status.textContent=`Previewing ${verb} ${target}…`;
    const preview=await fetchJson("api/action",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({kind,verb,target,apply:false})});
    if(preview.error){status.textContent=preview.error;return;}
    const phrase=window.prompt(`Xavi-Man preview:\n\n${JSON.stringify(preview,null,2).slice(0,1800)}\n\nType APPLY to ${verb.toUpperCase()} ${target}:`,"");
    if(phrase!=="APPLY"){status.textContent="Cancelled";return;}
    status.textContent=`Applying ${verb} ${target}…`;
    const result=await fetchJson("api/action",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({kind,verb,target,apply:true,confirm:"APPLY"})});
    status.textContent=result.error?`FAILED: ${result.error}`:`${verb} complete`;
    await refreshState();renderApp(win.dataset.id,win);
  }

  function actionButtons(kind,target,win){
    if(!target)return "";
    return `<div class="action-group"><button data-k="${esc(kind)}" data-v="start" data-t="${esc(target)}">Start</button><button data-k="${esc(kind)}" data-v="stop" data-t="${esc(target)}">Stop</button><button data-k="${esc(kind)}" data-v="restart" data-t="${esc(target)}">Restart</button></div>`;
  }
  function wireActions(win){win.querySelectorAll("[data-k][data-v][data-t]").forEach(b=>b.addEventListener("click",()=>action(b.dataset.k,b.dataset.v,b.dataset.t,win)));}

  function table(headers,rows){return `<table class="classic-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${rows.join("")}</tbody></table>`;}
  function overviewHtml(){if(!state)return "Loading…";const d=state.doctor||{},i=state.identity||{};return `<div class="panel"><div class="kv"><b>User</b><span>${esc(i.user||"-")}</span><b>Rootless</b><span>${esc(i.rootless)}</span><b>Podman graph</b><span>${esc(i.graph_root||"-")}</span><b>Generated</b><span>${esc(state.generated_at)}</span></div></div><div class="panel"><span class="badge ${d.ok?"ok":"bad"}">Doctor ${d.ok?"PASS":"ATTENTION"}</span> &nbsp; Issues ${esc(d.issue_count||0)} &nbsp; Warnings ${esc(d.warning_count||0)}</div><div class="panel"><b>Backend inventory</b><br><br>${(state.containers||[]).length} containers<br>${(state.services||[]).length} services<br>${(state.projects||[]).length} projects<br>${(state.remote_nodes||[]).length} remote nodes<br>${(state.listeners||[]).length} listeners</div>`;}
  function containersHtml(win){const rows=(state?.containers||[]).map(r=>{const d=r.details||{},name=r.name||"";return `<tr><td>${esc(name)}</td><td>${esc(d.state||r.state||"unknown")}</td><td>${esc(d.health||"-")}</td><td>${esc(r.project||"-")}</td><td>${actionButtons("container",name,win)}</td></tr>`});return table(["Container","State","Health","Project","Actions"],rows);}
  function servicesHtml(win){const rows=(state?.services||[]).map(r=>{const name=r.name||"";const actions=r.scope==="user"?actionButtons("service",name,win):"broker-gated";return `<tr><td>${esc(r.scope||"-")}</td><td>${esc(name)}</td><td>${esc((r.active||"-")+"/"+(r.sub||"-"))}</td><td>${esc(r.expected||"-")}</td><td>${actions}</td></tr>`});return table(["Scope","Service","State","Expected","Actions"],rows);}
  function projectsHtml(win){const rows=(state?.projects||[]).map(r=>{const name=r.id||r.name||r.project||"";return `<tr><td>${esc(name)}</td><td>${esc(r.state||r.status||"-")}</td><td>${esc(r.path||r.cwd||"-")}</td><td>${actionButtons("project",name,win)}</td></tr>`});return table(["Project","State","Path","Actions"],rows);}
  function remoteHtml(){return json(state?.remote_nodes||[])} function storageHtml(){return json(state?.filesystems||[])} function doctorHtml(){return json(state?.doctor||{})}

  async function renderApp(id,win){
    const content=win.querySelector(".window-content"),hint=win.querySelector(".window-hint");hint.textContent="Live via ConcreteCMS + WebSocket";
    try{
      if(id==="overview")content.innerHTML=overviewHtml();
      else if(id==="containers")content.innerHTML=containersHtml(win);
      else if(id==="services")content.innerHTML=servicesHtml(win);
      else if(id==="projects")content.innerHTML=projectsHtml(win);
      else if(id==="remote")content.innerHTML=remoteHtml();
      else if(id==="storage")content.innerHTML=storageHtml();
      else if(id==="doctor")content.innerHTML=doctorHtml();
      else if(id==="resources")content.innerHTML=json(await fetchJson("api/resources"));
      else if(id==="advisor")content.innerHTML=json(await fetchJson("api/advisor"));
      else if(id==="contract")content.innerHTML=json(await fetchJson("api/contract"));
      else content.innerHTML=`<div class="notice"><b>Xavi Manager 0.1</b><br><br>Windows 3.11-inspired backend operations desktop.<br><br>TUI: <code>cd /var/www/xavi &amp;&amp; ./xavi-man</code><br>Web: this authenticated console.<br><br>The browser never receives a shell. It can only call StackManager's allowlisted operations.</div>`;
      wireActions(win);win.querySelector(".window-status").textContent="Ready";
    }catch(err){content.innerHTML=`<div class="error">${esc(err.message||err)}</div>`;}
  }

  function openApp(id){const app=apps.find(a=>a[0]===id);const win=windowFor(id,app?app[2]:id);renderApp(id,win);}
  async function fetchJson(path,options={}){const res=await fetch(base+path,{credentials:"same-origin",cache:"no-store",...options});let data={};try{data=await res.json();}catch{data={error:`HTTP ${res.status}`}}if(!res.ok&&!data.error)data.error=`HTTP ${res.status}`;return data;}
  async function refreshState(){const next=await fetchJson("api/state");if(next.error)throw new Error(next.error);state=next;setSummary(state);for(const [id,win] of openWindows)if(["overview","containers","services","projects","remote","storage","doctor"].includes(id))renderApp(id,win);}

  function connectWs(){
    const scheme=location.protocol==="https:"?"wss":"ws";const ws=new WebSocket(`${scheme}://${location.host}${base}ws`);
    ws.onopen=()=>connection.textContent="Connected — live stream";
    ws.onmessage=e=>{try{const m=JSON.parse(e.data);if(m.type==="state"){state=m.payload;setSummary(state);for(const [id,win] of openWindows)if(["overview","containers","services","projects","remote","storage","doctor"].includes(id))renderApp(id,win);}}catch{}};
    ws.onerror=()=>connection.textContent="Stream error";ws.onclose=()=>{connection.textContent="Disconnected — retrying";setTimeout(connectWs,2500);};
  }

  document.getElementById("refresh-btn").addEventListener("click",()=>refreshState().catch(e=>connection.textContent=e.message));
  document.getElementById("token-btn").addEventListener("click",async()=>{
    const res=await fetch("/xavi-man/session-token",{credentials:"same-origin",cache:"no-store"});const data=await res.json().catch(()=>({}));
    if(!res.ok||!data.token){alert(data.message||`Token request failed (${res.status})`);return;}
    try{await navigator.clipboard.writeText(data.token);alert(`Short-lived xavi-man JWT copied. Expires ${new Date(data.expiresAt*1000).toLocaleString()}.`);}catch{window.prompt("Copy xavi-man token:",data.token);}
  });
  document.addEventListener("keydown",e=>{if(e.key==="F5"){e.preventDefault();refreshState();}if(e.key==="Escape"){const active=[...document.querySelectorAll(".child-window.active")].pop();if(active){openWindows.delete(active.dataset.id);active.remove();}}});
  refreshState().catch(e=>connection.textContent=e.message);connectWs();
})();
