/* Right-edge search information drawer. */
(() => {
    'use strict';

    const root = document.getElementById('xng-search-app');
    if (!root || root.dataset.xngInfoDrawerReady === '1') return;
    root.dataset.xngInfoDrawerReady = '1';

    const shell = root.querySelector('[data-role="info-drawer-shell"]');
    const drawer = root.querySelector('[data-role="info-drawer"]');
    const toggle = root.querySelector('[data-role="info-drawer-toggle"]');
    const close = root.querySelector('[data-role="info-drawer-close"]');
    if (!shell || !drawer || !toggle) return;

    const setOpen = (open, { focusClose = false } = {}) => {
        shell.classList.toggle('is-open', open);
        drawer.setAttribute('aria-hidden', open ? 'false' : 'true');
        toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
        toggle.setAttribute('aria-label', open ? 'Collapse search information' : 'Open search information');
        document.documentElement.classList.toggle('xng-info-drawer-active', open);
        if (open && focusClose) window.setTimeout(() => close?.focus(), 230);
    };

    setOpen(false);

    toggle.addEventListener('click', () => {
        setOpen(!shell.classList.contains('is-open'));
    });

    close?.addEventListener('click', () => {
        setOpen(false);
        toggle.focus();
    });

    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape' && shell.classList.contains('is-open')) {
            setOpen(false);
            toggle.focus();
        }
    });
})();
