new_search=r'''    private function searchRequestForMode(string $query, string $mode): array
    {
        switch ($mode) {
            case 'images':
                return [$query, 'images'];
            case 'news':
                return [$query, 'news'];
            case 'videos':
                return [$query, 'videos'];
            case 'maps':
                return [$query, 'map'];
            case 'files':
                return [$query, 'files'];
            case 'torrent':
                // Preserve any explicit SearXNG bang. Only inject !torrent for a plain query.
                if (!preg_match('/^\s*![a-z0-9_-]+(?:\s|$)/i', $query)) {
                    $query = '!torrent ' . $query;
                }
                return [$query, ''];
            case 'research':
            case 'web':
            default:
                return [$query, 'general'];
        }
    }

    private function expandLocalDorks(string $query): array
    {
        $map = [
            'x:pdf' => 'filetype:pdf',
            'x:docs' => '(filetype:pdf OR filetype:doc OR filetype:docx OR filetype:odt)',
            'x:books' => '(filetype:pdf OR filetype:epub)',
            'x:code' => '(site:github.com OR site:gitlab.com OR site:codeberg.org)',
            'x:archive' => 'site:archive.org',
            'x:forums' => '(inurl:forum OR inurl:threads OR inurl:discussion)',
            'x:video' => '(filetype:mp4 OR filetype:webm OR filetype:mkv)',
            'x:audio' => '(filetype:mp3 OR filetype:flac OR filetype:ogg)',
        ];
        $applied = [];
        foreach ($map as $token => $replacement) {
            $pattern = '/(^|\s)' . preg_quote($token, '/') . '(?=\s|$)/i';
            if (preg_match($pattern, $query)) {
                $query = preg_replace($pattern, '$1' . $replacement, $query);
                $applied[] = $token;
            }
        }
        return [$this->cleanQuery($query), $applied];
    }

    private function buildSearchLanes(string $query, string $mode): array
    {
        $lanes = [$query];
        if ($mode === 'torrent' && preg_match('/^\s*!t(?:orrent)?\s+/i', $query)) {
            $rest = trim((string) preg_replace('/^\s*!t(?:orrent)?\s+/i', '', $query));
            $unquoted = trim(str_replace('"', '', $rest));
            if ($unquoted !== '' && $unquoted !== $rest) {
                $lanes[] = '!torrent ' . $unquoted;
            }
        }
        return array_values(array_unique($lanes));
    }

    private function selectSearxNodes(string $query, int $page, int $fanout): array
    {
        $ports = self::SEARX_PORTS;
        $fanout = max(1, min(count($ports), $fanout));
        $offset = (int) (sprintf('%u', crc32($query . '|' . $page)) % count($ports));
        $nodes = [];
        for ($i = 0; $i < $fanout; ++$i) {
            $port = $ports[($offset + $i) % count($ports)];
            $nodes[] = ['id' => 'searx-' . $port, 'base' => 'http://127.0.0.1:' . $port];
        }
        return $nodes;
    }

    private function fetchSearchBatches(array $nodes, array $lanes, array $params, float $timeout): array
    {
        $client = new Client([
            'timeout' => $timeout,
            'connect_timeout' => min(1.2, $timeout),
            'http_errors' => false,
            'headers' => [
                'User-Agent' => 'Xavi-XNG-Fanout/1.0',
                'Accept' => 'application/json',
            ],
        ]);

        $promises = [];
        $meta = [];
        foreach ($nodes as $index => $node) {
            $lane = $lanes[$index % max(1, count($lanes))] ?? ($lanes[0] ?? '');
            $nodeParams = $params;
            $nodeParams['q'] = $lane;
            $url = $node['base'] . '/search?' . http_build_query($nodeParams);
            $promises[$index] = $client->requestAsync('GET', $url);
            $meta[$index] = [
                'node' => $node['id'],
                'query' => $lane,
                'started' => microtime(true),
            ];
        }

        $settled = Utils::settle($promises)->wait();
        $out = [];
        foreach ($settled as $index => $state) {
            $elapsed = (int) round((microtime(true) - $meta[$index]['started']) * 1000);
            $row = [
                'node' => $meta[$index]['node'],
                'query' => $meta[$index]['query'],
                'elapsed_ms' => $elapsed,
                'ok' => false,
                'payload' => [],
            ];
            if (($state['state'] ?? '') === 'fulfilled') {
                $response = $state['value'];
                $status = $response->getStatusCode();
                $payload = json_decode((string) $response->getBody(), true);
                if ($status >= 200 && $status < 300 && is_array($payload)) {
                    $row['ok'] = true;
                    $row['payload'] = $payload;
                }
            }
            $out[] = $row;
        }
        return $out;
    }

    private function fetchAutocomplete(array $nodes, string $query, float $timeout): array
    {
        $client = new Client([
            'timeout' => $timeout,
            'connect_timeout' => min(0.8, $timeout),
            'http_errors' => false,
            'headers' => [
                'User-Agent' => 'Xavi-XNG-Suggest/1.0',
                'Accept' => 'application/json',
            ],
        ]);
        $promises = [];
        foreach ($nodes as $index => $node) {
            $promises[$index] = $client->requestAsync('GET', $node['base'] . '/autocompleter?' . http_build_query(['q' => $query]));
        }
        $settled = Utils::settle($promises)->wait();
        $out = [];
        foreach ($settled as $state) {
            if (($state['state'] ?? '') !== 'fulfilled') {
                continue;
            }
            $response = $state['value'];
            if ($response->getStatusCode() < 200 || $response->getStatusCode() >= 300) {
                continue;
            }
            $payload = json_decode((string) $response->getBody(), true);
            $values = is_array($payload[1] ?? null) ? $payload[1] : [];
            foreach ($values as $value) {
                $value = trim((string) $value);
                if ($value !== '') {
                    $out[$this->fold($value)] = $value;
                }
            }
        }
        return array_values($out);
    }

    private function normalizeEngines(string $value): array
    {
        $out = [];
        foreach (preg_split('/\s*,\s*/', trim($value)) ?: [] as $engine) {
            $engine = trim($engine);
            if ($engine === '' || !preg_match('/^[a-zA-Z0-9 _.-]{1,80}$/', $engine)) {
                continue;
            }
            $out[$this->fold($engine)] = $engine;
            if (count($out) >= 12) {
                break;
            }
        }
        return array_values($out);
    }

    private function normalizeTorrentSort(string $value): string
    {
        $value = strtolower(trim($value));
        return in_array($value, ['relevance', 'seeders', 'size'], true) ? $value : 'relevance';
    }

    private function filterAndSortResults(array $results, string $mode, int $minSeeds, int $maxSizeMb, string $sort): array
    {
        if ($mode !== 'torrent') {
            return array_values($results);
        }
        $maxBytes = $maxSizeMb > 0 ? $maxSizeMb * 1024 * 1024 : 0;
        $results = array_values(array_filter($results, static function (array $row) use ($minSeeds, $maxBytes): bool {
            if ((int) ($row['seed'] ?? 0) < $minSeeds) {
                return false;
            }
            if ($maxBytes > 0 && (int) ($row['filesize'] ?? 0) > $maxBytes) {
                return false;
            }
            return true;
        }));
        if ($sort === 'seeders') {
            usort($results, static fn(array $a, array $b): int => ((int) ($b['seed'] ?? 0)) <=> ((int) ($a['seed'] ?? 0)));
        } elseif ($sort === 'size') {
            usort($results, static fn(array $a, array $b): int => ((int) ($b['filesize'] ?? 0)) <=> ((int) ($a['filesize'] ?? 0)));
        }
        return $results;
    }

    private function mergeResultBatches(array $batches): array
    {
        $merged = [];
        foreach ($batches as $batch) {
            foreach (($batch['results'] ?? []) as $row) {
                if (!is_array($row)) {
                    continue;
                }
                $key = $this->resultKey($row);
                if (!isset($merged[$key])) {
                    $merged[$key] = $row;
                    continue;
                }
                $current = $merged[$key];
                $current['engines'] = array_values(array_unique(array_merge($current['engines'] ?? [], $row['engines'] ?? [])));
                $current['source_nodes'] = array_values(array_unique(array_merge($current['source_nodes'] ?? [], $row['source_nodes'] ?? [])));
                if (mb_strlen((string) ($row['content'] ?? '')) > mb_strlen((string) ($current['content'] ?? ''))) {
                    $current['content'] = $row['content'];
                }
                foreach (['seed', 'leech', 'filesize'] as $field) {
                    $current[$field] = max((int) ($current[$field] ?? 0), (int) ($row[$field] ?? 0));
                }
                if (empty($current['magnetlink']) && !empty($row['magnetlink'])) {
                    $current['magnetlink'] = $row['magnetlink'];
                }
                $merged[$key] = $current;
