VIDEO_EXT={'.mp4','.mkv','.webm','.avi','.mov','.m4v','.wmv','.mpeg','.mpg','.ts','.mts','.m2ts','.flv','.ogv'}
AUDIO_EXT={'.mp3','.wav','.flac','.aac','.m4a','.ogg','.opus','.wma','.aiff','.ape'}
IMAGE_EXT={'.jpg','.jpeg','.png','.gif','.webp','.bmp','.tif','.tiff'}
PDF_EXT={'.pdf'}
TEXT_EXT={'.txt','.md','.rst','.json','.jsonl','.ndjson','.csv','.tsv','.xml','.html','.htm','.yaml','.yml','.toml','.ini','.cfg','.conf','.srt','.vtt','.lrc'}
URL_RE=re.compile(r'https?://[^\s<>"\']+',re.I)
SECRET_RE=re.compile(r'(^|[._-])(secret|token|password|passwd|credential|private|jwt|enrollment)([._-]|$)',re.I)
PRIVATE_PARTS={'social','facebook','messages','message','chats','chat','personal','firehose','private'}
SKIP_PREFIX=('mediacms/library/','duotronic-runtime/runtime-data/')


def sha256_file(path: Path) -> str:
    h=hashlib.sha256()
    with path.open('rb') as f:
        for block in iter(lambda:f.read(4*1024*1024),b''):
            h.update(block)
    return 'sha256:'+h.hexdigest()


def url_digest(url: str) -> str:
    return 'sha256:'+hashlib.sha256(url.encode('utf-8')).hexdigest()


def safe_name(name: str) -> str:
    stem=re.sub(r'[^A-Za-z0-9._ -]+','_',name).strip(' ._') or 'media'
    return stem[:180]


def is_private_path(rel: str) -> bool:
    parts={p.lower() for p in Path(rel).parts}
    return bool(parts & PRIVATE_PARTS) or 'facebook' in rel.lower()


def classify_local(path: Path) -> str | None:
    ext=path.suffix.lower()
    if ext in VIDEO_EXT: return 'video'
    if ext in AUDIO_EXT: return 'audio'
    if ext in IMAGE_EXT: return 'image'
    if ext in PDF_EXT: return 'pdf'
    return None


def parse_external(raw: str):
    raw=raw.rstrip('.,;:!?)\]}\"\'')
    try: u=urlparse(raw)
    except Exception: return None
    host=(u.hostname or '').lower().removeprefix('www.')
    path=u.path.strip('/')
    if host in {'youtube.com','m.youtube.com','music.youtube.com','youtube-nocookie.com'}:
        vid=''
        if path=='watch': vid=(parse_qs(u.query).get('v') or [''])[0]
        elif path.startswith(('shorts/','embed/','live/')): vid=path.split('/',1)[1].split('/')[0]
        if vid:
            canonical=f'https://www.youtube.com/watch?v={vid}'
            return {'provider':'youtube','url':canonical,'embed':f'https://www.youtube-nocookie.com/embed/{vid}','type':'video','title':f'YouTube · {vid}','thumb':f'https://i.ytimg.com/vi/{vid}/hqdefault.jpg'}
    if host=='youtu.be' and path:
        vid=path.split('/')[0]; canonical=f'https://www.youtube.com/watch?v={vid}'
        return {'provider':'youtube','url':canonical,'embed':f'https://www.youtube-nocookie.com/embed/{vid}','type':'video','title':f'YouTube · {vid}','thumb':f'https://i.ytimg.com/vi/{vid}/hqdefault.jpg'}
    if host in {'vimeo.com','player.vimeo.com'}:
        ids=[p for p in u.path.split('/') if p.isdigit()]
        if ids:
            vid=ids[-1]
            return {'provider':'vimeo','url':f'https://vimeo.com/{vid}','embed':f'https://player.vimeo.com/video/{vid}','type':'video','title':f'Vimeo · {vid}','thumb':''}
    if host.endswith('soundcloud.com') and path:
        canonical=f'https://soundcloud.com/{path}'
        return {'provider':'soundcloud','url':canonical,'embed':'https://w.soundcloud.com/player/?url='+quote(canonical,safe=''),'type':'audio','title':'SoundCloud · '+path.split('/')[-1],'thumb':''}
    if host=='open.spotify.com':
        parts=[p for p in u.path.split('/') if p]
        if len(parts)>=2 and parts[0] in {'track','album','playlist','episode','show'}:
            typ,ident=parts[0],parts[1]
            return {'provider':'spotify','url':f'https://open.spotify.com/{typ}/{ident}','embed':f'https://open.spotify.com/embed/{typ}/{ident}','type':'audio','title':f'Spotify {typ} · {ident}','thumb':''}
    if host in {'archive.org','www.archive.org'} and path.startswith('details/'):
        ident=path.split('/',1)[1].split('/')[0]
        if ident:
            return {'provider':'internet-archive','url':f'https://archive.org/details/{ident}','embed':f'https://archive.org/embed/{ident}','type':'video','title':f'Internet Archive · {ident}','thumb':''}
    return None


class SyncState:
    def __init__(self, media_root: Path):
        self.root=media_root/'.xavi-datalake-sync'; self.root.mkdir(parents=True,exist_ok=True)
        self.db=sqlite3.connect(self.root/'state.sqlite3',timeout=30)
        self.db.row_factory=sqlite3.Row
        self.db.executescript('''
        PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL;
        CREATE TABLE IF NOT EXISTS source_files(path TEXT PRIMARY KEY,size INTEGER NOT NULL,mtime_ns INTEGER NOT NULL,digest TEXT,kind TEXT,status TEXT,media_id INTEGER,updated_ms INTEGER NOT NULL);
        CREATE INDEX IF NOT EXISTS source_status ON source_files(status,kind);
        CREATE TABLE IF NOT EXISTS external_refs(url TEXT PRIMARY KEY,provider TEXT NOT NULL,media_id INTEGER,first_source_path TEXT,updated_ms INTEGER NOT NULL);
        ''')
    def fresh(self, rel, st, kind):
        r=self.db.execute('SELECT size,mtime_ns,kind,status FROM source_files WHERE path=?',(rel,)).fetchone()
        return bool(r and r['size']==st.st_size and r['mtime_ns']==st.st_mtime_ns and r['kind']==kind and r['status']=='done')
    def done(self, rel, st, kind, digest='', media_id=None):
        self.db.execute('INSERT INTO source_files(path,size,mtime_ns,digest,kind,status,media_id,updated_ms) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(path) DO UPDATE SET size=excluded.size,mtime_ns=excluded.mtime_ns,digest=excluded.digest,kind=excluded.kind,status=excluded.status,media_id=excluded.media_id,updated_ms=excluded.updated_ms',(rel,st.st_size,st.st_mtime_ns,digest,kind,'done',media_id,int(time.time()*1000))); self.db.commit()
    def failed(self, rel, st, kind):
        self.db.execute('INSERT INTO source_files(path,size,mtime_ns,digest,kind,status,media_id,updated_ms) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(path) DO UPDATE SET size=excluded.size,mtime_ns=excluded.mtime_ns,kind=excluded.kind,status=excluded.status,updated_ms=excluded.updated_ms',(rel,st.st_size,st.st_mtime_ns,'',kind,'error',None,int(time.time()*1000))); self.db.commit()
    def external_seen(self,url): return self.db.execute('SELECT media_id FROM external_refs WHERE url=?',(url,)).fetchone()
    def external_done(self,obj,media_id,source):
        self.db.execute('INSERT INTO external_refs(url,provider,media_id,first_source_path,updated_ms) VALUES(?,?,?,?,?) ON CONFLICT(url) DO UPDATE SET provider=excluded.provider,media_id=excluded.media_id,updated_ms=excluded.updated_ms',(obj['url'],obj['provider'],media_id,source,int(time.time()*1000))); self.db.commit()


class Command(BaseCommand):
    help='Incrementally catalog /datastore2/xavi/data in MediaCMS without copying canonical files.'
    def add_arguments(self,p):
        p.add_argument('--root',default=os.environ.get('XAVI_DATALAKE_ROOT','/xavi-data-lake'))
        p.add_argument('--user',default=os.environ.get('XAVI_DATALAKE_MEDIACMS_USER','tbi'))
        p.add_argument('--limit',type=int,default=250)
        p.add_argument('--external-text-limit',type=int,default=200)
        p.add_argument('--local-only',action='store_true')
        p.add_argument('--external-only',action='store_true')
        p.add_argument('--force',action='store_true')
        p.add_argument('--dry-run',action='store_true')
    def handle(self,*args,**opt):
        root=Path(opt['root']).resolve(); media_root=Path(settings.MEDIA_ROOT).resolve()
        if not root.is_dir(): raise CommandError(f'data lake unavailable: {root}')
        user=User.objects.filter(username=opt['user']).first() or User.objects.filter(is_superuser=True).order_by('id').first()
        if not user: raise CommandError('no MediaCMS owner user available')
        projection=media_root/'datalake_catalog'; projection.mkdir(parents=True,exist_ok=True)
        state=SyncState(media_root); limit=max(0,opt['limit']); local_count=external_count=errors=0
        if not opt['external_only']:
            local_count,err=self.sync_local(root,media_root,projection,state,user,limit,opt['force'],opt['dry_run']); errors+=err
        if not opt['local_only']:
            external_count,err=self.sync_external(root,state,user,max(0,opt['external_text_limit']),opt['force'],opt['dry_run']); errors+=err
        self.stdout.write(f'XAVI_DATALAKE_SYNC local={local_count} external={external_count} errors={errors}')
    def walk(self,root):
        for base,dirs,files in os.walk(root,followlinks=False):
            b=Path(base); relbase=b.relative_to(root).as_posix()
            dirs[:]=[d for d in dirs if not any(((relbase+'/'+d).strip('/')==p.rstrip('/') or (relbase+'/'+d).strip('/').startswith(p)) for p in SKIP_PREFIX)]
            for name in files:
                p=b/name
                if p.is_symlink(): continue
                rel=p.relative_to(root).as_posix()
                if any(rel==x.rstrip('/') or rel.startswith(x) for x in SKIP_PREFIX): continue
                yield p,rel
    def desired_state(self,rel): return 'unlisted' if is_private_path(rel) else 'public'
    def media_tags(self,media,*names):
        for n in names:
            try: tag,_=Tag.objects.get_or_create(title=n); media.tags.add(tag)
            except Exception: pass
    def sync_local(self,root,media_root,projection,state,user,limit,force,dry):
        count=errors=0
        for src,rel in self.walk(root):
            typ=classify_local(src)
            if not typ: continue
            if limit and count>=limit: break
            try: st=src.stat()
            except OSError: continue
            if not force and state.fresh(rel,st,'local'): continue
            try:
                digest=sha256_file(src); hexid=digest.split(':',1)[1]
                existing=Media.objects.filter(xavi_managed=True,xavi_external_url='',xavi_source_digest=digest).order_by('id').first()
                if existing:
                    state.done(rel,st,'local',digest,existing.id); continue
                if dry:
                    self.stdout.write(f'LOCAL {typ} {rel} {digest}'); state.done(rel,st,'local',digest,None); count+=1; continue
                d=projection/hexid[:2]/hexid; d.mkdir(parents=True,exist_ok=True)
                target=d/safe_name(src.name)
                if target.exists() or target.is_symlink(): target.unlink()
                target.symlink_to(src)
                relative=target.relative_to(media_root).as_posix()
                media=Media(user=user,title=src.stem[:100],description='Indexed from the Xavi WG-RNN data lake.',media_file=relative,media_type=typ,encoding_status='success',is_reviewed=True,xavi_managed=True,xavi_source_kind='datalake-file',xavi_source_path=rel,xavi_source_digest=digest,xavi_source_size=st.st_size,xavi_source_mtime_ns=st.st_mtime_ns)
                try: media.set_media_type(save=False)
                except Exception: media.media_type=typ
                media.encoding_status='success'; media.is_reviewed=True; media.save()
                desired=self.desired_state(rel); Media.objects.filter(pk=media.pk).update(state=desired,encoding_status='success',listable=(desired=='public' and media.is_reviewed))
                media.refresh_from_db(); self.media_tags(media,'data-lake','wg-rnn',typ)
                try: media.update_search_vector()
                except Exception: pass
                state.done(rel,st,'local',digest,media.id); count+=1
                self.stdout.write(f'LOCAL+ {media.id} {typ} {rel}')
            except Exception as e:
                errors+=1; state.failed(rel,st,'local'); self.stderr.write(f'LOCAL! {rel}: {type(e).__name__}: {e}')
        return count,errors
    def sync_external(self,root,state,user,doc_limit,force,dry):
        created=errors=scanned=0
        for src,rel in self.walk(root):
            if src.suffix.lower() not in TEXT_EXT or SECRET_RE.search(src.name): continue
            if doc_limit and scanned>=doc_limit: break
            try: st=src.stat()
            except OSError: continue
            if not force and state.fresh(rel,st,'refs'): continue
            scanned+=1
            try:
                text=src.read_bytes()[:2_000_000].decode('utf-8','replace')
                found={}
                for raw in URL_RE.findall(text):
                    obj=parse_external(raw)
                    if obj: found[obj['url']]=obj
                for obj in found.values():
                    row=state.external_seen(obj['url'])
                    media=Media.objects.filter(xavi_managed=True,xavi_external_url=obj['url']).order_by('id').first()
                    if not media and not dry:
                        media=Media(user=user,title=obj['title'][:100],description=f'External media reference discovered in Xavi data lake: {rel}',media_file='',media_type=obj['type'],encoding_status='success',is_reviewed=True,xavi_managed=True,xavi_source_kind='external-embed-ref',xavi_source_path=rel,xavi_source_digest=url_digest(obj['url']),xavi_source_size=0,xavi_source_mtime_ns=st.st_mtime_ns,xavi_external_url=obj['url'],xavi_external_embed_url=obj['embed'],xavi_external_provider=obj['provider'],xavi_external_thumbnail_url=obj.get('thumb',''))
                        media.save(); desired=self.desired_state(rel); Media.objects.filter(pk=media.pk).update(state=desired,encoding_status='success',listable=(desired=='public' and media.is_reviewed)); media.refresh_from_db(); self.media_tags(media,'data-lake','external-embed',obj['provider']);
                        try: media.update_search_vector()
                        except Exception: pass
                        created+=1; self.stdout.write(f'EXTERNAL+ {media.id} {obj["provider"]} {obj["url"]}')
                    elif not media and dry:
                        self.stdout.write(f'EXTERNAL {obj["provider"]} {obj["url"]} <- {rel}'); created+=1
                    if media: state.external_done(obj,media.id,rel)
                state.done(rel,st,'refs','',None)
            except Exception as e:
                errors+=1; state.failed(rel,st,'refs'); self.stderr.write(f'REFS! {rel}: {type(e).__name__}: {e}')
        return created,errors
