def rpc(url,method,params,to=6):
    body=json.dumps({'jsonrpc':'2.0','id':1,'method':method,'params':params}).encode()
    req=urllib.request.Request(url,data=body,headers={'content-type':'application/json','accept':'application/json, text/event-stream','x-api-key':key,'mcp-protocol-version':'2025-06-18'},method='POST')
