        decision_event_count: items.filter((item) => item.colorKey === "control-decision").length,
        avg_authority_t: items.length ? items.reduce((sum, item) => sum + Number(item.authority || 0), 0) / items.length : 0,
        witness_count: Number(sourceCounts.evidence_witnesses || 0) + Number(sourceCounts.nla_activation_witnesses || 0),
        memory_update_count: Number(sourceCounts.wgrnn_memory_updates || 0),
        module_invocation_count: Number(sourceCounts.module_invocations || 0),
        source_document_count: Number(sourceCounts.source_documents || 0),
      };
      this._state.warnings = (Array.isArray(payload.warnings) ? payload.warnings : []).map((warning) => {
        if (typeof warning === "string") return warning;
        return `${warning?.source || "source"}: ${warning?.error || "unavailable"}`;
      });
      this._state.alerts = items
        .filter((item) => ["warning", "critical"].includes(String(item.severity || "").toLowerCase()))
        .slice(0, 40)
        .map((item) => ({ severity: item.severity, kind: item.activityKind || item.label, summary: item.text, created_at: item.timestamp, bundle_id: item.id }));
      this._state.temporalAnomalies = [];
      this._state.decisionEvents = items.filter((item) => item.colorKey === "control-decision");
      this._state.runtime = {
        ...runtime,
        sourceCounts,
        sourceCount: Number(runtime.source_count || Object.keys(sourceCounts).length || 0),
        onlineCount: Number(runtime.active_source_count || Object.keys(sourceCounts).length || 0),
        gates: Array.isArray(runtime.gates) ? runtime.gates : [],
        contract: runtime.contract || null,
        wgrnn,
      };
      this._state.lastUpdated = payload.generated_at || new Date().toISOString();
      this._syncStreams(this._state.filteredItems);
      this._injectLiveItems(newItems);
      this._renderHud();
      this._renderRuntimeHud();

      const sourceCount = Object.keys(sourceCounts).length;
      const warningSuffix = this._state.warnings.length ? ` · ${this._state.warnings.length} source warning${this._state.warnings.length === 1 ? "" : "s"}` : "";
      const newSuffix = newItems.length ? ` · ${newItems.length} new` : "";
      this._setStatus(
        `Live ${formatStamp(this._state.lastUpdated)} · ${items.length} records · ${sourceCount} sources${newSuffix}${warningSuffix}`,
        this._state.warnings.length ? "warn" : "ok",
      );
    } catch (error) {
      window.__firehoseErrors = [...(window.__firehoseErrors || []), String(error?.message || error)];
      this._setStatus(error?.message || String(error), "error");
      this._renderHud();
      this._renderRuntimeHud();
    }
  }

  async _fetchJson(url, timeoutMs = 4500) {
    const controller = new AbortController();
    const timeout = Math.max(1000, Number(timeoutMs) || 4500);
    const timer = window.setTimeout(() => controller.abort(), timeout);
    try {
      const response = await fetch(url, {
        credentials: "same-origin",
        headers: { Accept: "application/json" },
        signal: controller.signal,
        cache: "no-store",
      });
      if (!response.ok) throw new Error(`firehose http ${response.status}`);
      const contentType = String(response.headers.get("content-type") || "").toLowerCase();
      if (!contentType.includes("json")) throw new Error(`firehose returned ${contentType || "non-json"}`);
      return await response.json();
    } catch (error) {
      if (error?.name === "AbortError") throw new Error(`firehose timeout after ${timeout}ms`);
      throw error;
    } finally {
      window.clearTimeout(timer);
    }
  }

  _renderRuntimeHud() {
    const runtime = this._state.runtime || {};
    const sourceCounts = runtime.sourceCounts || {};
    const sourceCount = Number(runtime.sourceCount || Object.keys(sourceCounts).length || 0);
    const onlineCount = Number(runtime.onlineCount || Object.keys(sourceCounts).length || 0);
    const warningCount = this._state.warnings.length;
    const state = runtime.online === false || onlineCount === 0 ? "offline" : (warningCount ? "degraded" : "live");
    const dot = this.querySelector("[data-runtime-dot]");
    const stateNode = this.querySelector("[data-runtime-state]");
    const metricsNode = this.querySelector("[data-runtime-metrics]");
    const gatesNode = this.querySelector("[data-runtime-gates]");
    const contractNode = this.querySelector("[data-runtime-contract]");
    if (dot) dot.dataset.state = state;
    if (stateNode) stateNode.textContent = `${state} ${onlineCount}/${sourceCount || onlineCount || 0}`;

    const wgrnn = runtime.wgrnn || {};
    const slots = Number(wgrnn.num_slots);
    const ledger = Number(wgrnn.ledger_entries);
    const witnessCount = Number(sourceCounts.evidence_witnesses || 0) + Number(sourceCounts.nla_activation_witnesses || 0);
    if (metricsNode) {
      metricsNode.innerHTML = [
        `<span>records <b>${this._state.items.length}</b></span>`,
        `<span>sources <b>${Object.keys(sourceCounts).length}</b></span>`,
        `<span>witnesses <b>${witnessCount}</b></span>`,
        `<span>slots <b>${Number.isFinite(slots) ? slots : "--"}</b></span>`,
      ].join("");
    }

    const gates = [...(Array.isArray(runtime.gates) ? runtime.gates : [])].slice(0, 12);
    while (gates.length < 12) gates.push({ name: `gate ${String(gates.length + 1).padStart(2, "0")}`, state: "unknown", raw: "unreported" });
    if (gatesNode) {
      gatesNode.innerHTML = gates.map((gate, index) => {
        const gateState = ["pass", "fail"].includes(gate?.state) ? gate.state : "unknown";
        const title = this._escapeHtml(`${gate?.name || `gate ${index + 1}`}: ${gate?.raw || gateState}`);
        return `<span class="wgrnn-firehose__gate is-${gateState}" title="${title}">${String(index + 1).padStart(2, "0")}</span>`;
      }).join("");
    }
    if (contractNode) {
      const suffix = Number.isFinite(ledger) ? ` · ledger ${ledger}` : "";
      contractNode.textContent = runtime.contract ? `active contract: ${runtime.contract}${suffix}` : `WG-RNN ${wgrnn.namespace || "runtime"}${suffix}`;
    }
  }

  _escapeHtml(value) {
    return String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#039;" }[char]));
  }

'''
