const { chromium } = require('playwright');

async function checkViewport(browser, name, viewport) {
  const page = await browser.newPage({ viewportSize: viewport });
  const consoleErrors = [];
  const pageErrors = [];
  const feedStatuses = [];
  page.on('console', m => { if (m.type() === 'error') consoleErrors.push(m.text()); });
  page.on('pageerror', e => pageErrors.push(String(e)));
  page.on('response', r => { if (r.url().includes('/packages/wgrnn_firehose/firehose.php')) feedStatuses.push(r.status()); });
  await page.goto('https://xavi.app/wgrnn_firehose', { waitUntil: 'domcontentloaded', timeout: 45000 });
  await page.waitForSelector('wgrnn-firehose-app', { timeout: 20000 });
  await page.waitForFunction(() => {
    const a = document.querySelector('wgrnn-firehose-app');
    return a && a._pixiApp && a._hasLoaded && Array.isArray(a._streams) && a._streams.length > 0;
  }, null, { timeout: 30000 });
  await page.waitForTimeout(1200);

  const base = await page.evaluate(() => {
    const app = document.querySelector('wgrnn-firehose-app');
    const root = app.querySelector('.wgrnn-firehose');
    const before = getComputedStyle(root, '::before').content;
    const active = app._streams.filter(s => s && s.entry && !s.waitingForEntry);
    const bootstrap = [];
    const count = Math.max(1, Math.min(18, app._laneCount || 18));
    for (let i = 0; i < count; i++) {
      const y = app._bootstrapStreamY(i, count, app._rowHeight || 12);
      bootstrap.push(y);
    }
    return {
      ascending: app._isAscending(),
      stageHeight: app._stageHeight,
      stageWidth: app._stageWidth,
      activeCount: active.length,
      streamCount: app._streams.length,
      itemCount: app._state?.items?.length || 0,
      sourceCount: app._state?.runtime?.sourceCount || 0,
      status: app._state?.status || '',
      before,
      bootstrap,
      bodyWidth: document.body.scrollWidth,
      viewportWidth: window.innerWidth,
      pending: app._pendingEntries?.length || 0,
      staged: app._stagedEntries?.length || 0,
      release: app._releaseQueue?.length || 0,
    };
  });

  const samples = [];
  for (let i = 0; i < 8; i++) {
    samples.push(await page.evaluate(() => {
      const app = document.querySelector('wgrnn-firehose-app');
      const out = {};
      for (const s of app._streams || []) {
        if (!s || !s.entry || s.waitingForEntry) continue;
        const id = String(s.entry.id || s.item?.id || '');
        if (!id) continue;
        out[id] = Number(s.y);
      }
      return out;
    }));
    await page.waitForTimeout(180);
  }

  let comparable = 0;
  let wrongWay = 0;
  let maxWrongDelta = 0;
  for (let i = 1; i < samples.length; i++) {
    const prev = samples[i - 1], cur = samples[i];
    for (const [id, y0] of Object.entries(prev)) {
      if (!(id in cur)) continue;
      const y1 = cur[id];
      const d = y1 - y0;
      comparable++;
      const wrong = base.ascending ? d > 0.75 : d < -0.75;
      if (wrong) { wrongWay++; maxWrongDelta = Math.max(maxWrongDelta, Math.abs(d)); }
    }
  }

  const edgeBootstrap = base.bootstrap.every(y => base.ascending ? y >= base.stageHeight : y <= 0);
  const noOverflow = base.bodyWidth <= base.viewportWidth + 1;
  const result = {
    name, viewport, ...base, comparable, wrongWay, maxWrongDelta,
    edgeBootstrap, noOverflow,
    feedStatuses,
    consoleErrors,
    pageErrors,
  };
  console.log(JSON.stringify(result));

  if (!base.before.includes('DUOTRONICS')) throw new Error(`${name}: Duotronics pipeline header missing`);
  if (!edgeBootstrap) throw new Error(`${name}: bootstrap can spawn inside viewport`);
  if (!noOverflow) throw new Error(`${name}: horizontal overflow ${base.bodyWidth}>${base.viewportWidth}`);
  if (base.itemCount < 1 || base.sourceCount < 1) throw new Error(`${name}: feed state empty`);
  if (!feedStatuses.some(s => s === 200)) throw new Error(`${name}: no successful public feed response`);
  if (wrongWay > 0) throw new Error(`${name}: ${wrongWay}/${comparable} persistent records moved the wrong direction; max delta ${maxWrongDelta}`);
  if (consoleErrors.length) throw new Error(`${name}: console errors: ${consoleErrors.join(' | ')}`);
  if (pageErrors.length) throw new Error(`${name}: page errors: ${pageErrors.join(' | ')}`);
  await page.close();
}

