import { lookup } from 'node:dns/promises'
import { isIP } from 'node:net'

import type { SearchResultItem } from '@/lib/types'

const CACHE_TTL_MS = 6 * 60 * 60 * 1000
const MAX_HTML_BYTES = 450_000
const PREVIEW_TIMEOUT_MS = 1800
const MAX_REDIRECTS = 2
const previewCache = new Map<string, { value?: string; expires: number }>()

function isPrivateIPv4(ip: string): boolean {
  const parts = ip.split('.').map(Number)
  if (parts.length !== 4 || parts.some(n => Number.isNaN(n))) return true
  const [a, b] = parts
  return (
    a === 10 ||
    a === 127 ||
    a === 0 ||
    (a === 169 && b === 254) ||
    (a === 172 && b >= 16 && b <= 31) ||
    (a === 192 && b === 168) ||
    (a === 100 && b >= 64 && b <= 127)
  )
}

function isPrivateIPv6(ip: string): boolean {
  const value = ip.toLowerCase()
  return (
    value === '::1' ||
    value === '::' ||
    value.startsWith('fc') ||
    value.startsWith('fd') ||
    value.startsWith('fe8') ||
    value.startsWith('fe9') ||
    value.startsWith('fea') ||
    value.startsWith('feb') ||
    value.startsWith('::ffff:127.') ||
    value.startsWith('::ffff:10.') ||
    value.startsWith('::ffff:192.168.')
  )
}

async function validatePublicUrl(value: string): Promise<URL | null> {
  try {
    const url = new URL(value)
    if (!['http:', 'https:'].includes(url.protocol)) return null
    if (url.username || url.password) return null
    if (url.port && !['80', '443'].includes(url.port)) return null
    const host = url.hostname.toLowerCase()
    if (host === 'localhost' || host.endsWith('.localhost')) return null

    const literalKind = isIP(host)
    if (literalKind === 4 && isPrivateIPv4(host)) return null
    if (literalKind === 6 && isPrivateIPv6(host)) return null
    if (!literalKind) {
      const addresses = await lookup(host, { all: true, verbatim: true })
      if (
        addresses.length === 0 ||
        addresses.some(({ address, family }) =>
          family === 4 ? isPrivateIPv4(address) : isPrivateIPv6(address)
        )
      ) {
        return null
      }
    }
    return url
  } catch {
    return null
  }
}

function decodeHtmlAttribute(value: string): string {
  return value
    .replace(/&amp;/gi, '&')
    .replace(/&#x27;/gi, "'")
    .replace(/&#39;/gi, "'")
    .replace(/&quot;/gi, '"')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
}

function extractPreviewImage(html: string, pageUrl: URL): string | undefined {
  const tags = html.match(/<meta\b[^>]*>/gi) || []
  for (const tag of tags) {
    const marker = tag.match(
      /(?:property|name)\s*=\s*["'](?:og:image(?::secure_url)?|twitter:image(?::src)?)["']/i
    )
    if (!marker) continue
    const content = tag.match(/content\s*=\s*["']([^"']+)["']/i)?.[1]
    if (!content) continue
    try {
      const imageUrl = new URL(decodeHtmlAttribute(content), pageUrl)
      if (['http:', 'https:'].includes(imageUrl.protocol)) return imageUrl.toString()
    } catch {
      // Ignore malformed metadata and keep looking.
    }
  }
  return undefined
}

async function readLimitedHtml(response: Response): Promise<string> {
  if (!response.body) return ''
  const reader = response.body.getReader()
  const chunks: Uint8Array[] = []
  let total = 0
  try {
    while (total < MAX_HTML_BYTES) {
      const { done, value } = await reader.read()
      if (done) break
      if (!value) continue
      const remaining = MAX_HTML_BYTES - total
      const chunk = value.byteLength > remaining ? value.slice(0, remaining) : value
      chunks.push(chunk)
      total += chunk.byteLength
      if (value.byteLength > remaining) break
    }
  } finally {
    void reader.cancel().catch(() => {})
  }
  const merged = new Uint8Array(total)
  let offset = 0
  for (const chunk of chunks) {
    merged.set(chunk, offset)
    offset += chunk.byteLength
  }
  return new TextDecoder().decode(merged)
}

export async function resolvePreviewThumbnail(
  sourceUrl: string
): Promise<string | undefined> {
  const cached = previewCache.get(sourceUrl)
  if (cached && cached.expires > Date.now()) return cached.value

  let current = await validatePublicUrl(sourceUrl)
  if (!current) return undefined

  try {
    for (let redirects = 0; redirects <= MAX_REDIRECTS; redirects++) {
      const response = await fetch(current, {
        method: 'GET',
        redirect: 'manual',
        signal: AbortSignal.timeout(PREVIEW_TIMEOUT_MS),
        headers: {
          Accept: 'text/html,application/xhtml+xml',
          'User-Agent': 'Mozilla/5.0 (compatible; XaviPreview/1.0)'
        }
      })

      if (response.status >= 300 && response.status < 400) {
        const location = response.headers.get('location')
        if (!location || redirects === MAX_REDIRECTS) break
        current = await validatePublicUrl(new URL(location, current).toString())
        if (!current) break
        continue
      }

      if (!response.ok) break
      const contentType = response.headers.get('content-type') || ''
      if (contentType && !contentType.includes('text/html')) break
      const html = await readLimitedHtml(response)
      const thumbnail = extractPreviewImage(html, current)
      previewCache.set(sourceUrl, {
        value: thumbnail,
        expires: Date.now() + CACHE_TTL_MS
      })
      return thumbnail
    }
  } catch {
    // Preview metadata is best-effort; search itself must still succeed.
  }

  previewCache.set(sourceUrl, { value: undefined, expires: Date.now() + CACHE_TTL_MS })
  return undefined
}

export async function enrichSearchResultThumbnails(
  results: SearchResultItem[],
  limit = 4
): Promise<SearchResultItem[]> {
  const enriched = await Promise.all(
    results.slice(0, limit).map(async result => {
      if (result.thumbnailUrl) return result
      const thumbnailUrl = await resolvePreviewThumbnail(result.url)
      return thumbnailUrl ? { ...result, thumbnailUrl } : result
    })
  )
  return [...enriched, ...results.slice(limit)]
}
